#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int mac_ie;
    time_t timestamp;
    int crc_flag;
} LTE_MAC_PDU;

typedef struct {
    LTE_MAC_PDU* data;
    size_t capacity;
    size_t size;
} LTE_MAC_PDU_LIST;

LTE_MAC_PDU_LIST* lte_mac_pdu_list_create(size_t initial_capacity) {
    LTE_MAC_PDU_LIST* list = malloc(sizeof(LTE_MAC_PDU_LIST));
    if (!list) return NULL;
    list->data = malloc(initial_capacity * sizeof(LTE_MAC_PDU));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

void lte_mac_pdu_list_free(LTE_MAC_PDU_LIST* list) {
    if (!list) return;
    free(list->data);
    free(list);
}

void lte_mac_pdu_list_insert(LTE_MAC_PDU_LIST* list, LTE_MAC_PDU new_pdu) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_MAC_PDU* new_data = realloc(list->data, new_capacity * sizeof(LTE_MAC_PDU));
        if (!new_data) return;
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = new_pdu;
}

LTE_MAC_PDU lte_mac_pdu_list_get(LTE_MAC_PDU_LIST* list, size_t index) {
    if (index >= list->size) return (LTE_MAC_PDU){0, 0, 0};
    return list->data[index];
}
