#define MAX_LINE_LENGTH 1024
#define MAX_FILE_NAME 256

int main(int argc, char *argv[]) {
    int opt;
    int manpage = 0;
    int count_lines = 1;
    int total_chars = 0;
    int average_chars_per_line = 0;
    char *input_file = NULL;
    char *output_file = NULL;

    while ((opt = getopt(argc, argv, "mcs:o:")) != -1) {
        switch (opt) {
            case 'm':
                manpage = 1;
                break;
            case 'c':
                count_lines = 0;
                break;
            case 's':
                // Handle --sort option
                break;
            case 'o':
                output_file = optarg;
                break;
        }
    }

    if (argc == 1) {
        fprintf(stderr, "Usage: %s [-m|--manpage] [-c|--count-lines] [-o|--output-file <file>]\n", argv[0]);
        return 1;
    }

    input_file = optarg;

    int file_fd;
    if (input_file) {
        file_fd = open(input_file, O_RDONLY);
        if (file_fd == -1) {
            perror("Error opening input file");
            return 1;
        }
    } else {
        file_fd = fileno(stdin);
    }

    int chars_per_line = 0;
    char buffer[MAX_LINE_LENGTH];
    while (read(file_fd, buffer, MAX_LINE_LENGTH) > 0) {
        total_chars += strlen(buffer);
        chars_per_line++;
    }

    close(file_fd);

    if (!output_file) {
        output_file = "stdout";
    }

    int out_fd;
    if ((out_fd = open(output_file, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR)) == -1) {
        perror("Error opening output file");
        return 1;
    }

    fprintf(out_fd, "Total lines: %d\n", chars_per_line);
    fprintf(out_fd, "Total characters: %d\n", total_chars);
    fprintf(out_fd, "Average characters per line: %.2f\n", (double)total_chars / chars_per_line);

    close(out_fd);

    return 0;
}

void generate_test_file(int size) {
    FILE *file = fopen("test.txt", "w");
