        close(sockfd);
        return NULL;
    }

    HostInfo* host_info = malloc(sizeof(HostInfo));
    host_info->hostname = strdup(hostname);
    memcpy(host_info->ip, ip, sizeof(ip));

    close(sockfd);

    return host_info;
}

