int find_largest(int* arr, int size);

int main() {
    int n;
    scanf("%d", &n);

    if(n > 1000) {
        printf("Error: Input list exceeds maximum size of 1000 elements.\n");
        exit(1);
    }

    int* numbers = (int*)malloc(n * sizeof(int));
    for(int i = 0; i < n; i++) {
        scanf("%d", &numbers[i]);
    }

    int max = find_largest(numbers, n);

    free(numbers);
    printf("The largest integer in the array is: %d\n", max);

    return 0;
}

int find_largest(int* arr, int size) {
    if(size == 0)
        return -1;

    int max = arr[0];
    for(int i = 1; i < size; i++) {
        if(arr[i] > max)
            max = arr[i];
    }
    return max;
}
