#define LOG_FILE "log.txt"
#define MAX_LOG_LEVEL 3 // 0: error, 1: warning, 2: info
#define DEFAULT_LOG_LEVEL 1

int log_level = DEFAULT_LOG_LEVEL;
FILE *log_file = fopen(LOG_FILE, "a");

void set_log_level(int level) {
    log_level = level;
}

void log_message(int severity, const char *fmt, ...) {
    if (severity > log_level) return;

    time_t now = time(NULL);
    struct tm *t = localtime(&now);

    va_list args;
    va_start(args, fmt);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ", t->tm_year + 1900, t->tm_mon, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec);
    if (severity == 0) {
        fprintf(log_file, "[ERROR] ");
    } else if (severity == 1) {
        fprintf(log_file, "[WARNING] ");
    } else {
        fprintf(log_file, "[INFO] ");
    }

    vfprintf(log_file, fmt, args);
    va_end(args);

    fprintf(log_file, "\n");
}

void close_log_file() {
    fclose(log_file);
}
