    // Copy the available cryptographic hash functions and block ciphers to the cache
    for (int i = 0; i < sizeof(hash_funcs) / sizeof(hash_func_t); i++) {
        cache[cache_size].name = strcpy((char*)malloc(strlen(hash_funcs[i].name) + 1), hash_funcs[i].name);
        cache[cache_size++].func = hash_funcs[i].func;
        cache[cache_size-1].param = hash_funcs[i].param;
    }

    for (int i = 0; i < sizeof(cipher_funcs) / sizeof(cipher_func_t); i++) {
        cache[cache_size].name = strcpy((char*)malloc(strlen(cipher_funcs[i].name) + 1), cipher_funcs[i].name);
        cache[cache_size++].func = cipher_funcs[i].func;
        cache[cache_size-1].param = cipher_funcs[i].param;
    }

    return cache;
}

void free_crypto_cache() {
