#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

sem_t* manageSemaphore(int initial_value) {
    sem_t* semaphore = NULL;

    // Check for invalid initial value (0 or negative)
    if(initial_value <= 0) {
        // Log error and return
        printf("Invalid initial value for semaphore. It should be greater than 0.\n");
        return NULL;
    }

    // Create the semaphore with the specified initial value
    semaphore = sem_open("/my_semaphore", O_CREAT | O_RDWR, 0600, initial_value);

    if(semaphore == SEM_FAILED) {
        // Log error and return
        printf("Error creating semaphore.\n");
        return NULL;
    }

    // Set up a timeout to detect potential race conditions
    struct timespec timeout = {0, 1000000}; // 1 second

    while(1) {
        if(sem_timedwait(semaphore, &timeout) == -1) {
            // Log error and return
            printf("Error managing semaphore.\n");
            sem_close(semaphore);
            return NULL;
        }

        if(sem_getvalue(semaphore, NULL) == initial_value) {
            break;
        }
    }

    return semaphore;
}
