    void insertAfterKey(std::vector<std::pair<int, std::string>>& vec, int key, const std::string& new_value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = std::find_if(vec.begin(), vec.end(), [key](const auto& pair) { return pair.first == key; });
        if (it != vec.end()) {
            vec.insert(it + 1, std::make_pair(key, new_value));
        } else {
            vec.push_back(std::make_pair(key, new_value));
        }
    }

