        if (settings.find(key) != settings.end()) {
            settings[key] = value;
            return true;
        } else {
            return false; // Key not found
        }
    }

    std::string getConfigValue(const std::string& key) {
        auto it = settings.find(key);
        if (it != settings.end()) {
            return it->second;
        } else {
            return ""; // Key not found
        }
    }

