using System;
using System.Data;
using System.Data.SqlClient;

public class StoredProcExecutor
{
    public IDataReader ExecuteStoredProcedure(SqlConnection connection, List<SqlParameter> parameters, string storedProcedureName)
    {
        // Create a parameterized SQL command
        SqlCommand command = new SqlCommand(storedProcedureName, connection);
        command.CommandType = CommandType.StoredProcedure;

        // Add input parameters to the command
        foreach (SqlParameter parameter in parameters)
        {
            command.Parameters.Add(parameter);
        }

        try
        {
            // Execute the stored procedure and return a data reader for the result set
            using (SqlDataReader reader = command.ExecuteReader())
            {
                return reader;
            }
        }
        catch (Exception ex)
        {
            // Handle potential exceptions
            throw new Exception("Error executing stored procedure: " + ex.Message);
        }
        finally
        {
            // Ensure proper resource disposal
            if (command.Connection != null)
            {
                command.Connection.Dispose();
            }
        }
    }
}
