class UpdateResource(Resource):
    method_decorators = [jwt_required]

    def put(self, resource_id):
        # Validate the request body against the schema
        try:
            validate(request.json, resource_schema)
        except ValidationError as e:
            return {"error": str(e)}, 400

        # Update the resource with optimistic locking
        db_resource = get_resource(resource_id)
        if not db_resource or db_resource.version != request.json.get("version", 0):
            return {"error": "Resource not found or concurrent update detected"}, 404

        # Update the database and invalidate cache
        update_db_resource(resource_id, request.json)
        cache.delete("resource_" + resource_id)

        return {}, 204

class DeleteResource(Resource):
    method_decorators = [jwt_required]

    def delete(self, resource_id):
        # Delete the resource with pessimistic locking
        db_resource = get_resource(resource_id)
        if not db_resource:
            return {"error": "Resource not found"}, 404

        # Return a new resource with default values
        return create_default_resource(), 201

class GetResource(Resource):
    def get(self, resource_id):
        # Retrieve the resource from the database and cache
        cached_resource = cache.get("resource_" + resource_id)
        if cached_resource:
            return jsonify(cached_resource)

        db_resource = get_resource(resource_id)
        if not db_resource:
            return {"error": "Resource not found"}, 404

        # Cache the retrieved resource
        cache.set("resource_" + resource_id, db_resource, timeout=60*60)  # cache for 1 hour

        return jsonify(db_resource)

