public string GetXmlElement(string xmlDocument, string elementName)
{
    XPathDocument document = new XPathDocument(xmlDocument);
    XPathNavigator navigator = document.CreateNavigator();
    XPathExpression expression = navigator.Compile("/" + elementName);
    XPathNodeIterator iterator = navigator.Select(expression);

    if (!iterator.MoveNext())
        return null;

    return iterator.Current.Value;
}
