import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5HashGenerator {
    private static final String LOG_FILE = "system.log";

    public static String generateMD5Hash(String input) throws Exception {
        if (input == null || input.isEmpty()) {
            throw new Exception("Input string is null or empty");
        }

        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.length; i++) {
                String hex = Integer.toHexString(0xff & hashBytes[i]);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            logError("MD5 hash generation failed", e);
            throw new Exception("Failed to generate MD5 hash");
        }
    }

    private static void logError(String message, Throwable t) {
        File logFile = new File(LOG_FILE);

        try (FileWriter writer = new FileWriter(logFile, true)) {
            writer.write(message + ": " + t.getMessage() + "\n");
        } catch (IOException e) {
            System.err.println("Failed to write to log file: " + e.getMessage());
        }
    }
}
