    public class DynamicPageController : ControllerBase
    {
        private readonly ICDNService _cdnService;
        private readonly IElementService _elementService;
        private readonly ICachingService _cachingService;

        public DynamicPageController(ICDNService cdnService, IElementService elementService, ICachingService cachingService)
        {
            _cdnService = cdnService;
            _elementService = elementService;
            _cachingService = cachingService;
        }

        [HttpPost]
        [Route("update")]
        public async Task<IActionResult> UpdatePageSection([FromBody]UpdatePageSectionRequest request)
        {
            try
            {
                // Handle concurrent updates using a transactional approach
                using (var transaction = _elementService.BeginTransaction())
                {
                    await _elementService.UpdateElement(request.PageSectionId, request.ElementId, request.HtmlContent);
                    await transaction.Commit();
                }

                // Update the CDN with the new content
                await _cdnService.UpdateCachedContent(request.PageSectionId, request.ElementId, request.HtmlContent);

                // Return a response indicating that the page should be refreshed
                return Ok(new { ShouldRefresh = true });
            }
            catch (Exception ex)
            {
                // Handle errors and logging
                Console.WriteLine($"Error updating page section: {ex.Message}");
                return StatusCode(500, "Internal Server Error");
            }
        }
    }

    public class UpdatePageSectionRequest
    {
        public int PageSectionId { get; set; }
        public string ElementId { get; set; }
        public string HtmlContent { get; set; }
    }
