import android.graphics.drawable.BitmapDrawable;

public class ThemeCache {
    private Map<String, Bitmap> themeBitmaps = new HashMap<>();
    private String defaultThemeDir;
    private File cacheRootDir;

    public ThemeCache(File cacheRootDir) {
        this.cacheRootDir = cacheRootDir;
        this.defaultThemeDir = "default_theme";
    }

    public void clearUnusedBitmaps() {
        for (Map.Entry<String, Bitmap> entry : themeBitmaps.entrySet()) {
            if (!isBitmapInUse(entry.getValue())) {
                entry.getValue().recycle();
                themeBitmaps.put(entry.getKey(), null);
            }
        }
    }

    public void setDefaultThemeDir(String defaultThemeDir) {
        this.defaultThemeDir = defaultThemeDir;
    }

    public Bitmap getThemeBitmap(String themeName) {
        return themeBitmaps.getOrDefault(themeName, loadThemeBitmap(themeName));
    }

    private Bitmap loadThemeBitmap(String themeName) {
        File themeFile = new File(cacheRootDir, themeName + ".png");
        if (!themeFile.exists()) {
            // Handle file not found
        }
        try (InputStream is = new FileInputStream(themeFile)) {
            return BitmapFactory.decodeStream(is);
        } catch (IOException e) {
            // Handle file read error
        }
