function extractTechnicalTerms(text) {
  const stopWords = ["the", "and", "is"];
  const apiEndpoint = "https://api.example.com/terms";
  let cachedTerms;

  function fetchTerms() {
    return new Promise((resolve, reject) => {
      fetch(apiEndpoint)
        .then(response => response.json())
        .then(data => resolve(data))
        .catch(error => reject(error));
    });
  }

  async function getTerms() {
    if (cachedTerms && Date.now() - cachedTerms.timestamp < 5 * 60 * 1000) {
      return cachedTerms.terms;
    }
    try {
      const terms = await fetchTerms();
      cachedTerms = { timestamp: Date.now(), terms };
      return terms;
    } catch (error) {
      console.error("Failed to fetch terms:", error);
      throw error;
    }
  }

  function extractMatches(text, termRegexes) {
    const matches = {};
    for (const termRegex of termRegexes) {
      const matchesArray = text.match(termRegex);
      if (!matchesArray) continue;
      for (const match of matchesArray) {
        match = match.toLowerCase().replace(/[^\w]/g, "");
        if (stopWords.includes(match)) continue;
        matches[match] = (matches[match] || 0) + 1;
      }
    }
    return matches;
  }

  async function processText(text) {
    const termRegexes = getTerms();
    const matches = extractMatches(text.toLowerCase().replace(/[^\w\s]/g, ""), termRegexes);
    return matches;
  }

  return processText(text);
}
