function renderScripts(scripts) {
  const sanitizedScripts = scripts.map((script) => ({
    ...script,
    code: sanitize(script.code),
  }));

  let renderedHTML = '';
  for (const script of sanitizedScripts) {
    const id = generateUniqueId(script.code);
    renderedHTML += `<script id="${id}">${script.code}</script>`;
  }

  return renderedHTML;

  function sanitize(code) {
    // Sanitize the code to ensure it's safe for rendering
    return code.replace(/</gi, '&lt;').replace(/>/gi, '&gt;');
  }

  function generateUniqueId(code) {
    // Generate a unique ID based on the script's content and timestamp
    const timestamp = Date.now();
    let id = '';
    for (const char of code.toLowerCase()) {
      if (char.match(/[a-z0-9]/)) {
        id += char;
      }
    }
    return `script-${timestamp}-${id}`;
  }

  // Function to fetch new scripts from an external data source
  async function updateScripts() {
    try {
      const response = await fetch('https://example.com/scripts');
      const newScripts = await response.json();
      // Update the existing scripts array with the new scripts
      scripts.push(...newScripts);
      return renderScripts(scripts);
    } catch (error) {
      console.error(error);
      return 'Error fetching new scripts';
    }
  }

  // Function to handle dynamic script updates
  function updateScriptFooter() {
    setInterval(() => {
      updateScripts().then((html) => {
        if (typeof html === 'string') {
          document.getElementById('script-footer').innerHTML = '';
          document.getElementById('script-footer').appendChild(document.createElement('div')).innerHTML = html;
        }
      });
    }, 1000); // Update scripts every 1 second
  }

  updateScriptFooter();
}
