    auto it = list.begin();
    while (it != list.end()) {
        if (*it == resourceID) {
            foundResource = true;
            break;
        }
        ++it;
    }

    // If the resource ID is not found, insert the URL at the end of the list
    if (!foundResource) {
        list.insert_after(list.end(), url);
        return;
