function mergeStreams(...streams) {
    const buffers = [];
    for (const stream of streams) {
        let buffer;
        try {
            buffer = Buffer.allocUnsafe(1024);
            let bytesRead;
            while ((bytesRead = stream.read(buffer, 0, buffer.length)) > 0) {
                buffer.copy(buffer, 0, bytesRead - bytesRead);
            }
        } catch (err) {
            if (!stream.destroyed) stream.destroy();
        } finally {
            buffers.push(buffer);
        }
    }
    return Buffer.concat(buffers).slice(0, Math.min(...buffers.map(b => b.length)));
}
