function traverseDOM(root, selectors, cb) {
  const result = [];
  (function traverse(node, path) {
    if (!node) return;
    node.querySelectorAll(`.${selectors.join(',.')}`).forEach((child) => {
      child.classList.forEach((cls) => {
        if (cls.includes('js-traverse')) {
          result.push(...traverse(child, `${path} ${child.nodeName.toLowerCase()}`));
        }
      });
      cb && cb(node, path);
    });
  })(root);

  return result;
}

// Example usage:
const root = document.body;
const selectors = ['.header', '.footer'];
const callback = (node, path) => {
  if (path.includes('header')) console.log('Header element found:', node);
};

const result = traverseDOM(root, selectors, callback);
