#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* modifyExtension(char* filename) {
  int len = strlen(filename);
  int digits = 0;
  char file_type[3];

  for (int i = len - 1; i >= 0; --i) {
    if (isdigit(filename[i])) {
      ++digits;
    } else {
      break;
    }
  }

  int j = len - 1;
  while (j >= 0 && !isdigit(filename[j])) {
    --j;
  }
  strcpy(file_type, &filename[j + 1]);

  char* new_filename = malloc((len + 2) * sizeof(char));
  sprintf(new_filename, "%.*s-%d.%s", digits, filename, digits, file_type);

  return new_filename;
}

int main() {
  // Use the C function to modify an example filename
  char* original_filename = "example.txt";
  char* modified_filename = modifyExtension(original_filename);
  printf("Original: %s\nModified: %s\n", original_filename, modified_filename);

  return 0;
}
