import java.util.*;

class UnionFind {
    private int[] parent;
    private int[] size;

    public UnionFind(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY)
            return;
        if (size[rootX] < size[rootY]) {
            parent[rootX] = rootY;
            size[rootY] += size[rootX];
        } else {
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }

    public boolean connected(int x, int y) {
        return find(x) == find(y);
    }
}

public class Main {
    private static Map<Integer, Integer> cache;

    public static int countDisjointPairs(List<Integer> list) {
        UnionFind uf = new UnionFind(list.size());
        long start = System.nanoTime();
        for (int i = 0; i < list.size(); i++) {
            for (int j = i + 1; j < list.size(); j++) {
                if (!uf.connected(i, j)) {
                    if (cache == null) cache = new HashMap<>();
                    int key = list.get(i) | (list.get(j) << 16);
                    if (!cache.containsKey(key)) {
                        uf.union(i, j);
                        long end = System.nanoTime();
                        System.out.println("Time taken for pair (" + i + ", " + j + "): " + (end - start));
                    }
                }
            }
        }
        return list.size() * (list.size() - 1) / 2 - uf.components();
    }

    private static int components() {
        if (cache == null) return 0;
        int count = 0;
        for (int i = 0; i < cache.size(); i++) {
            int root = findRoot(cache.get(i));
            if (root != i) {
                count++;
                cache.put(root, i);
            }
        }
        return count;
    }

    private static int findRoot(int x) {
        while (cache.containsKey(x)) x = cache.get(x);
        return x;
    }
}']

