public class DataProcessor {
    private ExecutorService executor;
    private Random random = new Random();
    private int delayRangeMin;
    private int delayRangeMax;
    private Logger logger;

    public DataProcessor(int delayRangeMin, int delayRangeMax) {
        this.delayRangeMin = delayRangeMin;
        this.delayRangeMax = delayRangeMax;
        this.executor = Executors.newSingleThreadExecutor();
        this.logger = new Logger("DataProcessor");
    }

    public void startService() {
        RandomProcessingTask task = new RandomProcessingTask();
        executor.submit(task);
    }

    private class RandomProcessingTask implements Runnable {
        @Override
        public void run() {
            try {
                // Start processing data
                long startTime = System.nanoTime();
                // Simulate CPU-intensive processing
                int iterations = 1000000;
                for (int i = 0; i < iterations; i++) {
                    Math.sin(Math.PI * i / iterations);
                }
                long duration = System.nanoTime() - startTime;

                // Log processing time and status update
                logger.log("Processing completed in " + duration + " nanoseconds");

                // Send status update to monitoring system
                sendStatusUpdate("SERVICE_STOPPED", duration);

                // Random delay before next start
                int randomDelay = random.nextInt(delayRangeMax - delayRangeMin) + delayRangeMin;
                Thread.sleep(randomDelay);

            } catch (InterruptedException e) {
                logger.log("Interrupted while waiting for processing to complete");
                Thread.currentThread().interrupt();
            }
        }
    }

    private class Logger implements java.util.logging.Logger {
        public Logger(String name) {
            super(name);
        }
    }

    private void sendStatusUpdate(String status, long duration) {
        // Implement external logging and monitoring system integration
        System.out.println("Sending status update: " + status + ", duration: " + duration);
    }
}
