class EnvConfig {
    private $config = [];
    private $env = 'dev';
    private $logger;
    private $cache;

    public function __construct() {
        $this->logger = new Logger();
        $this->cache = new APCache();

        if (isset($_ENV['APP_ENV'])) {
            $this->env = $_ENV['APP_ENV'];
        }
    }

    public function loadConfig($file) {
        try {
            $configData = json_decode(file_get_contents($file), true);
            if ($configData) {
                $this->config = array_merge($this->config, $configData);
            } else {
                $this->logger->error('Invalid configuration file: ' . $file);
            }
        } catch (Exception $e) {
            $this->logger->error('Error loading configuration file: ' . $file . ', reason: ' . $e->getMessage());
        }
    }

    public function getConfig($key, $default = null) {
        if (!isset($this->config[$this->env][$key])) {
            return $default;
        }
        return $this->cache->get('config_' . $key);
    }

    public function setConfig($key, $value) {
        $this->config[$this->env][$key] = $value;
        $this->cache->set('config_' . $key, $value);
    }

    public function getLogger() {
        return $this->logger;
    }
}

class Logger {
    private $logLevel;

    public function __construct() {
        $this->logLevel = 'INFO';
    }

    public function log($level, $message) {
        if ($level >= constant('self::' . strtoupper($this->logLevel))) {
            // Implement Splunk integration here
            echo date('Y-m-d H:i:s') . ': ' . $message . "\n";
        }
    }
}

class APCache {
    public function get($key) {
        return apc_fetch($key);
    }

    public function set($key, $value) {
        apc_store($key, $value);
    }
}

