```
use reqwest::{RequestBuilder, blocking};
use tokio::time;
use std::sync::Arc;
use std::collections::HashSet;

async fn http_client(
    url: String,
    disable_cert_validation: bool,
    custom_headers: Option<HashSet<String>>,
    timeout_ms: u64,
) -> Result<Arc<reqwest::blocking::Client>, reqwest::Error> {
    let mut client = Arc::new(reqwest::blocking::ClientBuilder::new())
        .timeout(time::Duration::from_millis(timeout_ms))
        .build()
        .unwrap();

    if disable_cert_validation {
        client = client.add_root_certificate(Arc::new(Pkcs12::from_pem(include_bytes!("path/to/untrusted_cert.pem"), "").unwrap()));
    }

    let mut request_builder = client.get(url.clone()).timeout(timeout_ms);

    if let Some(headers) = custom_headers {
        for header in headers {
            request_builder.header(header, "");
        }
    }

    Ok(client)
}

async fn make_request(
    client: Arc<reqwest::blocking::Client>,
    url: String,
) -> Result<String, reqwest::Error> {
    let mut response = client.get(url.clone()).send().await?;

    if !response.status().is_success() {
        let max_retries = 3;
        for _ in 0..max_retries {
            match response.error_for_status_ref().clone().unwrap_or_else(|| panic!("Unexpected status code: {}", response.status())) {
                reqwest::StatusCode::TOO_MANY_REQUESTS => {
                    println!("Rate limit exceeded, retrying...");
                    tokio::time::sleep(time::Duration::from_millis(1000)).await;
                    continue;
                }
                _ => return Err(response.error_for_status_ref().unwrap().to_string()),
            }
        }
    }

    Ok(response.text().await.unwrap())
}

// Example usage:
let client = http_client(
    "https://example.com".to_string(),
    false,
    Some(hashset!["X-Custom-Header" => "custom-value"]),
    5000
).unwrap();

let response = make_request(client.clone(), "https://example.com/path").await.unwrap();
println!("{}", response);
