use std::fs;
use std::process::{Command, ExitCode};
use std::time::{Duration, Instant};
use sys_info::get_resident_set_size;

mod sync_lazy {
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::LazyLock as Lazy;

    pub fn new<F>(init: F) -> Box<dyn FnOnce() -> F::Output>
    where
        F: FnOnce() -> F::Output,
    {
        let state = AtomicUsize::new(0);
        let lazy = Lazy::new(move || {
            let _ = state.fetch_add(1, Ordering::SeqCst);
            init()
        });
        Box::new(lazy)
    }
}

fn compile_with_logging(hook: &str) -> Result<(), ExitCode> {
    let command = Command::new("rustc")
        .args([
            "--edition=2018",
            "-Z", "link-arg-pass-through=-Werror",
            "-C", "prefer-dylib-linker-linker",
            "-C", "rpath",
            "-C", "embedbitcode=0"
        ])
        .arg(format!("--sysroot={}", std::env::var("SYSROOT").unwrap()))
        .arg(hook)
        .spawn()?;

    let start = Instant::now();
    match command.wait()? {
        ExitCode(exit_code) => {
            println!("Compilation took: {:?}", start.elapsed());
            if !fs::metadata("Cargo.toml").is_ok() {
                println!("cargo:warning=No Cargo.toml found");
            }
        }
        _ => {
            println!("Compilation failed with exit code: {}", exit_code);
        }
    };

    let pre_compilation_rs = get_resident_set_size()?;
    let compilation_rs = get_resident_set_size()?;
    println!("Pre-compile resident set size: {} MB", pre_compilation_rs / 1024);
    println!("Post-compile resident set size: {} MB", compilation_rs / 1024);

    Ok(())
}

fn log_error(message: &str) {
    let _ = std::fs::OpenOptions::new()
        .create(true)
        .write(true)
        .open("error.log")
        .unwrap_or_else(|_| std::fs::File::create("error.log"));
    println!("{}", message);
}

fn catch_with_exit_code<F>(f: F) -> Result<(), ExitCode>
where
    F: FnOnce() -> Result<(), ExitCode>,
{
    let mut prev_exit_code = None;
    for res in f() {
        match res {
            Ok(_) => return Ok(()),
            Err(exit_code) => {
                if let Some(prev_exit_code) = &prev_exit_code {
                    println!("Error during compilation: {}", exit_code);
                }
                prev_exit_code = Some(exit_code);
                return Err(*prev_exit_code);
            }
        }
    }
}

fn early_error<F>(f: F)
where
    F: FnOnce(),
{
    let _ = std::fs::OpenOptions::new()
        .create(true)
        .write(true)
        .open("error.log")
        .unwrap_or_else(|_| std::fs::File::create("error.log"));
    f();
}

fn main() {
    let condition = "your_condition";
    if condition == "true" {
        log_error("Error occurred");
    }

    let hook = sync_lazy::new(|| "path_to_your_hook".to_string());
    compile_with_logging(&hook).unwrap_or_else(|exit_code| {
        println!("Compilation failed with exit code: {}", exit_code);
        early_error(|| std::process::exit(exit_code));
    });
