from sqlalchemy import create_engine, text
from sqlalchemy.orm import sessionmaker
from functools import wraps
import logging
import redis
from flask_caching import Cache

app = Flask(__name__)
app.config["CACHE_TYPE"] = "Redis"
app.config["CACHE_REDIS_URL"] = "redis://localhost:6379/0"
cache = Cache(app)

logging.basicConfig(filename='app.log', level=logging.INFO)

def cache_response(ttl=3600):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            cache.set(f'{func.__name__}{args}', result, timeout=ttl)
            return result
        return wrapper
    return decorator

def get_customer_details(country, city):
    engine = create_engine('sqlite:///database.db')
    Session = sessionmaker(bind=engine)
    session = Session()

    try:
        query = text("SELECT * FROM Customers WHERE Country=:country AND City=:city")
        result = session.execute(query, {"country": country, "city": city}).fetchone()
        if result:
            return result
        else:
            return None
    except Exception as e:
        logging.error(f"Error: {e}")
        return None

    finally:
        session.close()

@app.route('/customer_details', methods=['GET'])
@cache_response(ttl=3600)
def get_customer_details_api(country, city):
    result = get_customer_details(country, city)
    if result:
        return jsonify(result)
    else:
        return jsonify({"message": "No customer details found"}), 404

if __name__ == '__main__':
    app.run(debug=True)']

