function fetchOAuthRequest(oauthRequest) {
  const privatePemUrl = oauthRequest.privateKeyEndpoint;
  const certificatePemUrl = oauthRequest.certificateEndpoint;

  async function getPEMFile(url) {
    return await fetch(url)
      .then(response => response.text())
      .catch(error => {
        console.error(`Error fetching ${url}:`, error);
        throw error;
      });
  }

  async function combinePrivateAndCertificatePems(privatePem, certificatePem) {
    const combinedPem = `${privatePem}\n${certificatePem}`;
    return combinedPem;
  }

  try {
    const privatePem = await getPEMFile(privatePemUrl);
    const certificatePem = await getPEMFile(certificatePemUrl);

    const combinedPem = await combinePrivateAndCertificatePems(privatePem, certificatePem);
    return combinedPem;
  } catch (error) {
    if (error.name === 'TimeoutError') {
      console.error('Request timed out. Trying again...');
      await new Promise(resolve => setTimeout(resolve, 2000));
      return fetchOAuthRequest(oauthRequest);
    }
    throw error;
  }
}
