StateList* createStateList(int* states, int numStates, FSA* fsa, int lastState) {
    // Calculate memory required for each state node.
    size_t memSize = sizeof(StateNode);

    // Allocate memory for the state list.
    StateList* stateList = (StateList*)malloc((numStates + 1) * memSize);
    if (!stateList) {
        return NULL;
    }

    // Initialize the state list.
    for (int i = 0; i <= lastState; i++) {
        stateList[i].id = states[i];
    }

    // Update the 'next' pointer of the last state in the list.
    stateList[lastState].next = NULL;

    return stateList;
}

