    bool hasCooldown = false;
    for (auto& [attack, usage] : attackUsage) {
        if (usage > 3 && globalCooldown < 15) { // 15 seconds
            std::this_thread::sleep_for(std::chrono::seconds(15));
            hasCooldown = true;
            break;
        }
    }

