        int selectedAttack = dis(gen);
        attackUsage[selectedAttack]++;

        // Print the selected attack number to the console
        std::cout << "Selected Attack: " << selectedAttack << std::endl;

        // Update the global cooldown counter
        globalCooldown = 9; // 9 seconds

        // Reset the attack usage counters after the cooldown period
        std::this_thread::sleep_for(std::chrono::seconds(9));
        for (auto& [attack, usage] : attackUsage) {
