function customReduce(array, initialValue, callback) {
    return new Promise((resolve, reject) => {
        const result = initialValue;
        const len = array.length;

        if (len === 0) {
            resolve(result);
            return;
        }

        const iterate = (index) => {
            if (index >= len) {
                resolve(result);
                return;
            }

            try {
                result = callback(result, array[index]);
                if (result === 0 && array[index] !== 0) {
                    reject(new Error('Division by zero'));
                }
                iterate(index + 1);
            } catch (error) {
                reject(error);
            }
        };

        iterate(0);
    });
}

