typedef struct {
    char* key;
    int value;
    int timeout;
} Setting;

Setting* read_settings(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    Setting* settings = (Setting*)malloc(0 * sizeof(Setting));
    size_t total_size = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Ignore comments
        char* comment_start = strchr(line, '#');
        if (comment_start) *comment_start = '\0';

        Setting* setting = (Setting*)realloc(settings, ++total_size * sizeof(Setting));
        setting->key = strdup(strtok(line, " "));
        setting->value = atoi(strtok(NULL, " "));
