#include <stdio.h>
#include <string.h>

void modify_filename(const char *input_filename, char *output_filename) {
    const char *dot = strrchr(input_filename, '.');
    int count = 0;
    if (dot != NULL) {
        dot++;
        while (*dot >= '0' && *dot <= '9') {
            count++;
            dot++;
        }
    }

    char buffer[257]; // Initialize buffer with a size of 257
    memset(buffer, '\0', sizeof(buffer));

    sprintf(buffer, "%.*s_%d.%s", (int)(strlen(input_filename) - (dot == NULL ? strlen(input_filename) : strlen(dot)) + count), input_filename, count, strrchr(input_filename, '.') ? strrchr(input_filename, '.') : "");

    strcat(output_filename, buffer);

    // Reset the buffer for safety
    memset(buffer, '\0', sizeof(buffer));
}
