AES_CTX* init_aes_cipher(const char* password) {
    // Initialize the EVP context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the IV length to 16 bytes and the key length to 32 bytes
    unsigned char iv[AES_BLOCK_SIZE] = {0};
    unsigned char key[AES_KEY_LENGTH] = {0};

    // Derive the encryption key from the password using SHA-1 hash function
    SHA_CTX sha_ctx;
    SHA_Init(&sha_ctx);
    SHA_Update(&sha_ctx, (const unsigned char*)password, strlen(password));
    SHA_Final(&sha_ctx);

    // Get the derived key
    SHA1 *hash = malloc(EVP_MAX_MD_SIZE);
    SHA1_Update(hash, &sha_ctx.md_data[0], sha_ctx.message_digest_length);
    int key_len = EVP_BytesToKey(ctx, EVP_sha1(), NULL, hash, 20, 32, key, NULL);

    // Initialize the AES-256-CBC cipher
    if (AES_cbc_encrypt(NULL, NULL, NULL, ctx) != 1) {
        ERR_error(ERR_ERROR);
        return NULL;
    }

    // Enable the cipher
    AES_set_defaults(ctx);

    // Free resources when no longer needed
    EVP_CIPHER_CTX_free(ctx);

    // Initialize theme cache management
    unsigned char* theme_bitmap = malloc(AES_BLOCK_SIZE);
    if (theme_bitmap == NULL) {
        ERR_error(ERR_ERROR);
        return NULL;
    }

    // Check if a theme bitmap is recycled and recycle it if necessary
    if (/* check recycling condition */) {
        free(theme_bitmap);
        theme_bitmap = NULL;
    }

    // Set the default theme directory if not set
    char* default_theme_dir = "/path/to/default/theme/dir";
    if (*default_theme_dir == '\0') {
        *default_theme_dir = "/path/to/actual/default/theme/dir";
    }

    // Parse a PNG file from the cache root directory and put it in a theme cache
    FILE* png_file = fopen("/path/to/cache/root/png/file.png", "rb");
    if (png_file == NULL) {
        ERR_error(ERR_ERROR);
        return NULL;
    }
    fseek(png_file, 0L, SEEK_END);
    size_t file_size = ftell(png_file);
    rewind(png_file);

    unsigned char* png_data = malloc(file_size + 1);
    fread(png_data, 1, file_size, png_file);
    png_data[file_size] = '\0';

    fclose(png_file);
    free(png_data);

    // Return a pointer to the cipher context
    return ctx;
}
