#include <string.h>

#define MAX_CONCURRENT_PROCESSES 10
#define HEARTBEAT_INTERVAL 300 // 5 minutes in seconds

// Function to handle signal for parent process
void sig_handler(int signum) {
    printf("Signal received: %d\n", signum);
    raise(signum); // Re-raise the signal
}

// Structure to represent a background command
typedef struct {
    char* command;
    int timeout; // Timeout in seconds
} BackgroundCommand;

// Function to run a given command in the background using fork and wait system calls
int run_background_command(char* command, int timeout) {
    pid_t child_pid = fork();

    if (child_pid == 0) { // Child process
        dup2(STDERR_FILENO, STDOUT_FILENO); // Redirect stdout to stderr for logging
        execlp("/bin/sh", "/bin/sh", "-c", command, NULL);
        return 1; // Command execution failed
    } else if (child_pid > 0) { // Parent process
        signal(SIGCHLD, sig_handler); // Set signal handler

        struct timespec timeout_ts = {
            .tv_sec = timeout,
            .tv_nsec = 0
        };

        nanosleep(&timeout_ts, NULL);

        kill(child_pid, SIGKILL); // Send SIGKILL to child process after timeout
    } else { // Error creating child process
        return 0;
    }

    return 1; // Successful command execution
}

int main() {
    int max_concurrent_processes = MAX_CONCURRENT_PROCESSES;
    int current_process_count = 0;

    while (1) {
        printf("Enter a command to run in the background (or 'exit' to quit): ");
        char* command = NULL;
        size_t command_len = 0;

        if (fgets(command, sizeof(char), stdin)) {
            // Trim newline character
            command[strcspn(command, "\n")] = '\0';

            if (strcmp(command, "exit") == 0) {
                break;
            } else {
                BackgroundCommand bg_cmd = {command, 300}; // Default timeout is 5 minutes

                while (current_process_count >= max_concurrent_processes) {
                    printf("Maximum number of concurrent processes reached. Waiting...\n");
                    sleep(1); // Pause for 1 second
                }

                if (run_background_command(bg_cmd.command, bg_cmd.timeout)) {
                    current_process_count++;
                    printf("Command '%s' running in the background.\n", command);
                } else {
                    printf("Error running command '%s'.\n", command);
                }
            }
        } else {
            break;
        }
    }

    return 0;
}

