import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CommandExecutor {
    private static final int TEMP_FILE_SIZE_THRESHOLD = 1024 * 1024; // 1MB
    private static final int BUFFERED_READER_BUFFER_SIZE = 4096;
    private static final int EXECUTION_TIMEOUT_MILLISECONDS = 30000; // 30 seconds

    public static void executeCommand(String command, String[] args) throws IOException {
        File tempFile = createTempFile();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                Runtime.getRuntime().exec(command, args, tempFile.toPath()), BUFFERED_READER_BUFFER_SIZE))) {
            ExecutorService executor = Executors.newSingleThreadExecutor();
            Thread worker = new Thread(() -> {
                StringBuilder output = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                    if (output.length() > TEMP_FILE_SIZE_THRESHOLD) {
                        writeTempFile(output.toString(), tempFile);
                        output.setLength(0);
                    }
                }
                writerThread(output, tempFile);
            });
            executor.submit(worker);

            Thread readerThread = new Thread(() -> {
                String errorLine;
                while ((errorLine = getErrorLine()) != null) {
                    System.out.println("Error: " + errorLine);
                }
            });
            executor.submit(readerThread);

            long start = System.currentTimeMillis();
            while (System.currentTimeMillis() - start < EXECUTION_TIMEOUT_MILLISECONDS) {
                if (!reader.ready()) {
                    try {
                        Thread.sleep(10);
                    } catch (InterruptedException e) {
                        break;
                    }
                }
            }

            writerThread(new StringBuilder(), tempFile).start();

            executor.shutdown();
        }
    }

    private static File createTempFile() throws IOException {
        return Files.createTempFile("command", ".out").toFile();
    }

    private static void writeTempFile(String data, File file) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(file))) {
            writer.write(data);
        }
    }

    private static String getErrorLine() throws IOException {
        return new BufferedReader(new InputStreamReader(
                Runtime.getRuntime().exec("cmd /c type NUL", null, null).getInputStream(), BUFFERED_READER_BUFFER_SIZE))
                .readLine();
    }

    private static void writerThread(StringBuilder output, File tempFile) {
        try {
            Thread.sleep(1000);
            writeTempFile(output.toString(), tempFile);
        } catch (InterruptedException e) {
            // Handle exception
        }
    }
}
