using System.Text;
using System.Net.Http;
using System.Net.Http.Headers;

public string DecryptMessage(string base64EncodedMessage, byte[] key, byte[] iv, string expectedHash)
{
    try
    {
        using (var ms = new MemoryStream(Convert.FromBase64String(base64EncodedMessage)))
        {
            using (var cryptoStream = new CryptoStream(ms, TripleDes.CreateDecryptor(key, iv), CryptoStreamMode.Read))
            {
                using (var sr = new StreamReader(cryptoStream))
                {
                    string decryptedMessage = sr.ReadToEnd();

                    // Validate the integrity of the decrypted message
                    byte[] messageBytes = Encoding.UTF8.GetBytes(decryptedMessage);
                    var sha256 = SHA256.Create();
                    byte[] hashBytes = sha256.ComputeHash(messageBytes);

                    if (!expectedHash.Equals(Encoding.UTF8.GetString(hashBytes)))
                    {
                        throw new Exception("Invalid decryption or tampering detected.");
                    }

                    return decryptedMessage;
                }
            }
        }
    }
    catch (HttpRequestException ex)
    {
        Console.WriteLine($"Error connecting to API: {ex.Message}");
        return null;
