    public static string GetSHA256Hash(string input, OutputFormat format = OutputFormat.Hexadecimal)
    {
        using (var sha256 = SHA256.Create())
        {
            var hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            return format switch
            {
                OutputFormat.Hexadecimal => BitConverter.ToString(hashBytes).Replace("-", "").ToLower(),
                OutputFormat.Base64 => Convert.ToBase64String(hashBytes),
                _ => throw new ArgumentOutOfRangeException(nameof(format), format, null)
            };
        }
    }

