using System.Text;

public class AescbcDecrypter
{
    private readonly string _algorithmName;

    public AescbcDecrypter(string algorithmName)
    {
        _algorithmName = algorithmName;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
    {
        if (encryptionKey.Length < 16 || encryptionKey.Length > 32)
            return ErrorHandling.GenerateError("Invalid key length.");

        if (iv.Length != 16)
            return ErrorHandling.GenerateError("Invalid IV length.");

        try
        {
            using var aes = Aes.Create();
            aes.Key = encryptionKey;
            aes.IV = iv;

            using var cbc = new CbcBlockCipher(aes);
            var decryptor = cbc.CreateDecryptor();

            using var ms = new MemoryStream(ciphertext);
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

            byte[] decryptedBytes = new byte[ciphertext.Length];
            int bytesRead;
            while ((bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length)) > 0)
                ;

            return ms.ToArray();
        }
        catch (CryptographicException e)
        {
            return ErrorHandling.GenerateError("Decryption error: " + e.Message);
        }
        catch (IOException e)
        {
            return ErrorHandling.GenerateError("I/O error: " + e.Message);
        }
    }

    public byte[] DecryptWithPadding(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
    {
        if (!ValidatePadding(ciphertext))
            return ErrorHandling.GenerateError("Invalid padding.");

        return Decrypt(ciphertext, encryptionKey, iv);
    }

    private bool ValidatePadding(byte[] ciphertext)
    {
        int blockSize = 16;
        for (int i = ciphertext.Length - 1; i >= 0; i--)
        {
            if (ciphertext[i] != blockSize)
                return false;
            blockSize--;
        }
        return true;
    }
}
