    private static readonly object _syncLock = new object();
    private static Cache<FileInfo, byte[]> _cache;

    public static void LoadAndDeserialize(FileInfo file, CompressionMethod method)
    {
        using (var stream = File.OpenRead(file.FullName))
        {
            if (_cache == null) _cache = new Cache<FileInfo, byte[]>();
            var cacheKey = stream.Name;
            lock (_syncLock)
            {
                if (_cache.TryGetValue(cacheKey, out byte[] data))
                {
                    // Load from cache
                    return Deserialize(data);
                }
            }

            using (var compressedStream = GetCompressedStream(stream, method))
            {
                int bufferLength = 1024 * 1024; // Adjust to your desired buffer size
                byte[] buffer = new byte[bufferLength];
                int bytesRead;
                while ((bytesRead = compressedStream.Read(buffer, 0, bufferLength)) > 0)
                {
                    if (_cache == null) _cache = new Cache<FileInfo, byte[]>();
                    var cachedData = _cache.GetOrAdd(cacheKey, _ => new byte[buffer.Length]);
                    Array.Copy(buffer, 0, cachedData, 0, bytesRead);
                }
            }

            return Deserialize(cachedData);
        }
    }

    private static Stream GetCompressedStream(Stream stream, CompressionMethod method)
    {
        switch (method)
        {
            case CompressionMethod.GZip:
                return new GZipStream(stream, CompressionMode.Decompress);
            case CompressionMethod.Deflate:
                return new DeflateStream(stream, CompressionMode.Decompress);
            default:
                throw new ArgumentException("Unsupported compression method");
        }
    }

    private static CustomDataStructure Deserialize(byte[] data)
    {
        using (var memoryStream = new MemoryStream(data))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            return (CustomDataStructure)formatter.Deserialize(memoryStream);
        }
    }
}

public enum CompressionMethod
{
    GZip,
    Deflate
}
