function streamShellCommand(command, options = {}) {
  if (!window && !global) throw new Error('Cannot run in browser');
  const { pauseStream, resumeStream } = options;
  let output = '';
  let isPaused = false;

  function startStream() {
    const shell = require('child_process').spawn(command, [], {
      encoding: 'utf8',
      stdio: 'pipe'
    });

    shell.stdout.on('data', (chunk) => {
      if (!isPaused) {
        output += chunk.toString();
        process.stdout.write(chunk);
      }
    });

    shell.stderr.on('data', (chunk) => {
      output += chunk.toString();
      process.stderr.write(chunk);
    });

    shell.on('close', () => {
      if (!isPaused) {
        process.stdout.write('\n');
      }
    });
  }

  function pauseStream() {
    isPaused = true;
    clearInterval(streamInterval);
  }

  function resumeStream() {
    isPaused = false;
    startStream();
  }

  function getOutput() {
    return output;
  }

  if (pauseStream || resumeStream) {
    startStream();

    const streamInterval = setInterval(() => {
      if (!isPaused && !output.includes('\n')) {
        process.stdout.write(`Streaming... (${command})\n`);
      }
    }, 100);

    return { pauseStream, resumeStream, getOutput };
  } else {
    startStream();
    return { getOutput };
  }
}
