```rust
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::env;
use std::thread;
use std::sync::{Arc, Mutex};
use log::{error, info};

struct DirectoryCreator {
    attempts: Arc<Mutex<u32>>,
}

impl DirectoryCreator {
    fn new() -> Self {
        DirectoryCreator {
            attempts: Arc::new(Mutex::new(0)),
        }
    }

    fn create_directory_and_set_env_var(&self, dir_name: &str) -> Result<String, String> {
        if dir_name.is_empty() || !dir_name.chars().all(|c| c.is_alphanumeric()) {
            return Err("Invalid directory name".to_string());
        }

        let mut attempts = self.attempts.lock().unwrap();
        for _ in 0..5 {
            let path = format!("path/{}", dir_name);
            match fs::create_dir_all(path.clone()) {
                Ok(_) => {
                    *attempts = 0;
                    break;
                }
                Err(err) => {
                    if *attempts >= 5 {
                        return Err(format!("Failed to create directory after 5 attempts: {}", err));
                    }
                    *attempts += 1;
                    thread::sleep(std::time::Duration::from_millis(100));
                }
            }
        }

        let perms = PermissionsExt::set_mode(path.as_path(), 0o755)?;
        env::set_var("MY_DIR", path.to_str().unwrap().to_string());

        Ok(path.clone())
    }
}
