import jsonschema
from concurrent.futures import ThreadPoolExecutor, as_completed
from functools import partial

class SensorDataParser:
    def __init__(self):
        self.registry = {}
        self.lock = threading.Lock()
        self.json_schema_validators = {}

    def add_factory(self, id, factory):
        with self.lock:
            self.registry[id] = factory

    def create_instance(self, id, json_data):
        if id not in self.registry:
            raise KeyError(f"Factory for {id} does not exist")
        with self.lock:
            factory = self.registry[id]
            instance = factory(json.loads(json_data))
            return instance

    def register_json_schema_validator(self, id, schema):
        self.json_schema_validators[id] = jsonschema.Draft7Validator(schema)

    def validate_instance(self, id, instance):
        if id not in self.json_schema_validators:
            raise KeyError(f"Schema for {id} does not exist")
        validator = self.json_schema_validators[id]
        try:
            validator.validate(instance)
        except jsonschema.exceptions.ValidationError as e:
            raise ValueError(f"Invalid instance: {e}")

    def parallel_process_instances(self, instances):
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.create_instance, id, json_data) for id, json_data in instances.items()]
            for future in as_completed(futures):
                yield from (future.result() for _ in range(len(instances)))

    def parallel_validate_instances(self, instances):
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(partial(self.validate_instance, id)) for id, instance in instances.items()]
            for future in as_completed(futures):
                yield from (future.result() for _ in range(len(instances)))
