    if(curl == NULL) {
        fprintf(stderr, "Failed to create curl session.\n");
        res = CURLE_FAILED_INIT;
        curl_global_cleanup();
        return NULL;
    }

    // Set the URL and disable certificate validation as needed
    curl_easy_setopt(curl, CURLOPT_URL, url);
    if(disableCertValidation) {
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
    }

    // Dynamically allocate memory for arrays
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    int* keys = (int*)malloc(numKeys * sizeof(int));

    // Initialize array values
    for(size_t i = 0; i < numOffsets; ++i) {
        offsets[i] = rand();
    }
    for(size_t i = 0; i < numKeys; ++i) {
