    struct Message **messages = (struct Message **)malloc(1000 * sizeof(struct Message *));
    for (int i = 0; i < 1000; i++) {
        messages[i] = (struct Message *)malloc(sizeof(struct Message));
        messages[i]->tag = (rand() % 3) ? WARNING : ERROR;
        messages[i]->priority = rand() % 100 + 1;
    }

    printf("Enter a list of messages, each on a separate line. Type 'stop' to finish.\n");
    int count = 0;
    while (scanf("%d", &messages[count]->tag) == 1) {
        if (feof(stdin)) break; // stop when user types 'stop'
        if (count >= 1000) {
            printf("Error: too many messages. Maximum allowed is 1000.\n");
            break;
        }
        messages[count]->priority = rand() % 100 + 1;
        count++;
    }

    printHighestPriorityMessage(messages, count);

    for (int i = 0; i < count; i++) {
        free(messages[i]);
    }
    free(messages);

    return 0;
}
