// Function to dynamically allocate memory for offset, key, and record arrays
void initialize_arrays(int offset_count, int key_count, int record_count, int min_value, int max_value) {
    // Check for valid input parameters
    if (offset_count <= 0 || key_count <= 0 || record_count <= 0 || min_value > max_value) {
        printf("Invalid input parameters. Please check the counts and values.\n");
        return;
    }

    // Dynamically allocate memory for offset, key, and record arrays
    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));
    Record* records = (Record*)malloc(record_count * sizeof(Record));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed. Exiting.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % ((max_value - min_value) + 1) + min_value;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

// Function to run a command in the background using fork and wait system calls
int run_command(char* command) {
    pid_t pid = fork();

    if (pid < 0) {
        printf("fork failed. Exiting.\n");
        return 0;
    } else if (pid == 0) { // Child process
        execl("/bin/bash", "bash", "-c", command, NULL);
        printf("Command execution failed. Exiting.\n");
        return 0;
    } else { // Parent process
        int status;
        wait(&status);
        if (!WIFEXITED(status)) {
            printf("Command did not complete successfully. Status: %d\n", status);
            return 0;
        }
        return 1;
    }
}
