typedef struct record {
    int key;
} record;

void safe_function(int num_records, int max_key, long max_offset) {
    int *keys = (int *)malloc(sizeof(int) * num_records);
    long *offsets = (long *)malloc(sizeof(long) * num_records);
    record *records = (record *)malloc(sizeof(record) * num_records);

    if (!keys || !offsets || !records) {
        free(keys);
        free(offsets);
        free(records);
        printf("Memory allocation failed. Exiting...\n");
        return;
    }

    srand(time(NULL)); // Initialize random number generator

