// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    // Add necessary fields for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG here
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a doubly linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *prev;
    struct Node *next;
} Node;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_crc_indication_pdu_list(int N) {
    Node *head = NULL; // Initialize the head of the doubly linked list
    Node **tail = &head; // Initialize the tail pointer

    srand(time(NULL)); // Seed random number generator for CRCFLAG values

    for (int i = 0; i < N; i++) {
        Node *node = malloc(sizeof(Node)); // Allocate memory for a new node
        if (!node) {
            printf("Memory allocation failed. Exiting.\n");
            exit(EXIT_FAILURE);
        }

        // Initialize the data structure with random values for RNTI and CRCFLAG
        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) {
            printf("Memory allocation failed. Exiting.\n");
            exit(EXIT_FAILURE);
        }
        data->rnti = rand() % 100000; // Random RNTI value
        data->crcflag = rand() % 2; // Random CRCFLAG (0 or 1)

        node->data = data;
        node->prev = NULL;
        node->next = NULL;

        *tail = node; // Update the tail pointer
        tail = &node->next; // Prepare for next iteration

        if (i > 0) {
            node->prev = *(tail - 1); // Link each new node to its previous one
            (*(tail - 1))->next = node;
        }
    }

    *tail = NULL; // Mark the end of the list

    // Traverse and print the list (for demonstration purposes)
    Node *current = head;
    while (current) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data->rnti, current->data->crcflag);
        current = current->next;
    }

    // Free memory for the list
    Node *curr = head;
    while (curr) {
        free(curr->data);
        Node *next = curr->next;
        free(curr);
        curr = next;
    }
}

int main() {
    int N = 50; // Example size, can be varied from 10 to 100,000
    create_crc_indication_pdu_list(N);
    return 0;
}
