    printf("Running test case: %s\n", label);
    f();
    printf("Test case completed: %s\n", label);
}

int main() {
    int n = 0;
    int* arr = NULL;

    // Read integers from standard input and store them in an array
    while (scanf("%d", &arr[n]) == 1) {
        n++;
    }
    arr = (int*) realloc(arr, sizeof(int) * (n + 1));
    printf("Largest integer: %d\n", max_int(arr, n));

    // Load the shared library at runtime
    void* lib = dlopen((const char*) getenv("TEST_LIBRARY"), RTLD_LAZY);
    if (!lib) {
        fprintf(stderr, "Failed to load shared library: %s\n", dlerror());
        return 1;
    }

    // Define a function pointer for the test cases
    void (*test_functions[])(void) = {0}; // Initialize with null

    // Execute test cases defined in the shared library
    int num_tests = 0;
    *(void**)&num_tests = dlsym(lib, "NUM_TESTS");
    if (!num_tests) {
        fprintf(stderr, "Failed to find NUM_TESTS symbol in shared library\n");
        dlclose(lib);
        return 1;
    }

    for (int i = 0; i < num_tests; i++) {
        void (*test_func)(void) = *(void**)&(test_functions + i);
        run_test(__FUNCTION__, test_func);
    }
    // Reset any state changes made to the library after each test
    dlclose(lib);

    return 0;
}
