typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} ListNode;

// Function to add a new structure to the list
ListNode* addNode(ListNode* head, NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = (ListNode*) malloc(sizeof(ListNode));
    newNode->data = data;
    newNode->next = head;
    return newNode;
}

// Function to remove a node from the list based on RNTI
void removeNode(ListNode** head, int RNTI) {
    if (*head == NULL || (*head)->data.RNTI != RNTI)
        return;

    ListNode* temp = *head;
    *head = (*head)->next;
    free(temp);
}

// Function to iterate through the list and perform operations
void iterateList(ListNode* head, void (*operation)(NFAPI_CRC_INDICATION_PDU_T*)) {
    while (head != NULL) {
        operation(&head->data);
        head = head->next;
    }
}

// Function to find and print the largest integer in an array
