typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[12];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

void insert(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return;
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = *head;
    if (*head != NULL) {
        (*head)->prev = &new_node->next;
    }
    *head = new_node;
}

void delete(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* current = *head;
    while (current && current->data != data) {
        current = current->next;
    }
    if (current == NULL) return;

    if (current->prev != NULL)
        current->prev->next = current->next;
    else
        *head = current->next;

    if (current->next != NULL)
        current->next->prev = current->prev;
    free(current);
}

void traverse(Node* head, void (*visit)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = head;
    while (current) {
        visit(current->data);
        current = current->next;
    }
}

int main() {
    int N = 100000; // number of structures to create
    srand(time(NULL)); // for random CRCFLAG values

    Node* head = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) {
            printf("Memory allocation failed\n");
            return -1;
        }
        strcpy(data->RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_" + i);
        data->RNTI = rand() % 1000; // random RNTI value
        for (int j = 0; j < 12; j++) {
            data->CRC_INDICATION_REL8_TAG[j] = '0' + rand() % 2; // set CRCFLAG randomly
        }
        insert(&head, data);
    }

    traverse(head, (void (*)(NFAPI_CRC_INDICATION_PDU_T*))printf);

    delete(&head, head); // deleting all nodes

    free(head); // freeing the head node

    return 0;
}

