            .send()
            .await
        {
            Ok(response) => {
                match response.text().await {
                    Ok(body) => return Ok(body),
                    Err(_) => return Err(reqwest::Error::new(response.status())),
                }
            },
            Err(err) => {
                // Handle failed requests and exponential backoff
                if let reqwest::ErrorKind::Timeout = err.kind() {
                    println!("Timeout: retrying in 1 second");
                    std::thread::sleep(std::time::Duration::from_millis(1000));
                } else if let reqwest::ErrorKind::ConnectionReset = err.kind() {
                    println!("Connection reset: retrying in 2 seconds");
                    std::thread::sleep(std::time::Duration::from_millis(2000));
                } else {
                    println!("Failed request: retrying in 4 seconds");
                    std::thread::sleep(std::time::Duration::from_millis(4000));
                }
            },
        }
    }

    Err(reqwest::Error::new(reqwest::StatusCode::BAD_REQUEST))
}
