using namespace boost::beast;

class SandeshClient {
public:
    SandeshClient(size_t maxConcurrentRequests, size_t maxRetries) 
        : maxConcurrentRequests_(maxConcurrentRequests), maxRetries_(maxRetries) {}

    void sendGetRequest(const std::string& serverUri, const std::string& requestId) {
        auto start = std::chrono::high_resolution_clock::now();

        // Initialize a new request
        http::request<http::string_body> req;
        req.version(11);
        req.method(http::verb::get);
        req.target(serverUri);

        // Send the GET request to multiple servers in parallel
        auto session = std::make_shared<http::async_response_type>(req);
        auto future = http::async_get(session, req, 10s);

        // Wait for the response and log details
        auto res = future.get();
        auto end = std::chrono::high_resolution_clock::now();

        if (res.status != http::status::ok) {
            // Handle failed requests with exponential backoff
            size_t retriesLeft = maxRetries_ - 1;
            while (retriesLeft--) {
                res = future.get();
                if (res.status == http::status::ok)
                    break;

                // Exponential backoff
                std::this_thread::sleep_for(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::seconds(2) * (1 << retriesLeft)));
            }

            if (res.status != http::status::ok) {
                // Maximum number of retries exceeded, log error and maintain statistics
                // ...
            }
        } else {
            // Request was successful, update statistics
            // ...
        }

        // Log detailed information about each request
        std::cout << "Request ID: " << requestId << ", Start Time: " << start.time_since_epoch().count()
                  << ", End Time: " << end.time_since_epoch().count() << ", Status Code: " << res.status.code()
                  << ", Response Content: " << res.body << std::endl;
    }

private:
    size_t maxConcurrentRequests_;
    size_t maxRetries_;
};

int main() {
    SandeshClient client(5, 3); // Create a new Sandesh client with 5 concurrent requests and 3 retries

    // Send GET requests to multiple servers in parallel
    std::vector<std::thread> threads;
    for (auto& thread : threads) {
        client.sendGetRequest("http://example.com/api/data", "request-1");
    }

    return 0;
}
