typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* malloc_or_die(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

FILE* fopen_or_die(const char* filename, const char* mode) {
    FILE* file = fopen(filename, mode);
    if (!file) {
        fprintf(stderr, "File operation failed.\n");
        exit(1);
    }
    return file;
}

void log_info(NFAPI_CRC_INDICATION_PDU_T* p, FILE* file) {
    fprintf(file, "[RNTI: %d, CRCFLAG: %d]\n", p->RNTI, p->CRCFLAG);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int num_structures, int log_level, const char* log_file_path) {
    NFAPI_CRC_INDICATION_PDU_T* crc_list = NULL;
    FILE* log_file = NULL;

    // Initialize random number generator
    srand(time(NULL));

    if (num_structures > 0) {
        crc_list = malloc_or_die(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        for (int i = 0; i < num_structures; i++) {
            NFAPI_CRC_INDICATION_PDU_T* p = &crc_list[i];
            p->RX_UE_INFORMATION_TAG = rand() % 100;
            p->RNTI = rand() % 100;
            p->CRCFLAG = (rand() % 2) ? 1 : 0;

            if (log_level > 0 && log_file_path != NULL) {
                log_file = fopen_or_die(log_file_path, "a");
                log_info(p, log_file);
                fclose(log_file);
            }
        }

        // Log total number of structures created
        if (log_level > 0 && log_file_path != NULL) {
            log_file = fopen_or_die(log_file_path, "a");
            fprintf(log_file, "[Total: %d]\n", num_structures);
            fclose(log_file);
        }
    }

    return crc_list;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* crc_list) {
    if (crc_list != NULL) {
        free(crc_list);
    }
}
