#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct RX_UE_INFORMATION_TAG {
    // Structure implementation details
} RX_UE_INFORMATION_TAG;

typedef enum RNTI {
    // Enum implementation details
} RNTI;

typedef struct CRC_INDICATION_REL8_TAG {
    // Structure implementation details
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Doubly linked list structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) {
        // Handle memory allocation failure
        return NULL;
    }
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = create_node(data);
    if (!node) {
        // Handle memory allocation failure
        return;
    }
    if (*head == NULL) {
        *head = node;
    } else {
        node->next = *head;
        (*head)->prev = node;
        *head = node;
    }
}

void delete_node(Node** head, Node* node) {
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        *head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    }
    free(node);
}

void traverse_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        // Process the data
        printf("%p\n", current->data);
        current = current->next;
    }
}

// Memory pool for frequently used structures
RX_UE_INFORMATION_TAG* rx_ue_info_pool = NULL;
RNTI rnti_pool[1000];
CRC_INDICATION_REL8_TAG crc_indication_rel8_pool[1000];

RX_UE_INFORMATION_TAG* get_rx_ue_info() {
    if (rx_ue_info_pool == NULL) {
        rx_ue_info_pool = (RX_UE_INFORMATION_TAG*) malloc(sizeof(RX_UE_INFORMATION_TAG) * 1000);
    }
    return &rx_ue_info_pool[rand() % 1000];
}

RNTI get_rnti() {
    return rnti_pool[rand() % 1000];
}

CRC_INDICATION_REL8_TAG* get_crc_indication_rel8() {
    return &crc_indication_rel8_pool[rand() % 1000];
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N) {
    Node* head = NULL;
    for (int i = 0; i < N; i++) {
        RX_UE_INFORMATION_TAG* rx_ue_info = get_rx_ue_info();
        RNTI rnti_val = get_rnti();
        CRC_INDICATION_REL8_TAG* crc_indication_rel8 = get_crc_indication_rel8();
        NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) {
            // Handle memory allocation failure
            return NULL;
        }
        data->rx_ue_info = *rx_ue_info;
        data->rnti = rnti_val;
        data->crc_indication_rel8 = *crc_indication_rel8;
        insert_node(&head, data);
    }
    return head;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        delete_node(&head, current);
        current = next;
    }
}
