typedef struct {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int num_structures, int enable_logging) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL;
    }

    for (int i = 0; i < num_structures; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % MAX_UETAGS;
        list[i].RNTI = rand();
        if (enable_logging) {
            printf("Created structure %d with RNTI %d and RX_UE_INFORMATION_TAG %d\n", i, list[i].RNTI, list[i].RX_UE_INFORMATION_TAG);
        }
    }

    for (int i = 0; i < num_structures; i++) {
        list[i].CRCFLAG = rand() & 1;
        if (enable_logging) {
            printf("Set CRCFLAG to %d for structure %d\n", list[i].CRCFLAG, i);
        }
    }

    return list;
}

void destroy_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* list, int num_structures) {
