// Global list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* global_list = NULL;
int global_list_len = 0;
pthread_mutex_t global_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void* create_and_populate_list(int N) {
    int i;
    NFAPI_CRC_INDICATION_PDU_T** temp_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Allocate memory for each structure and populate them with random data
    for(i = 0; i < N; i++) {
        temp_list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set RX_UE_INFORMATION_TAG to a unique string based on RNTI
        sprintf(temp_list[i]->RX_UE_INFORMATION_TAG, "Tag_%d", i);

        // Set RNTI and CRCFLAG randomly
        temp_list[i]->RNTI = rand() % 100;
        temp_list[i]->CRCFLAG = (rand() % 2) ? 0 : 1;
    }

    // Sort the list based on RNTI in ascending order
    qsort(temp_list, N, sizeof(NFAPI_CRC_INDICATION_PDU_T*), compare_RNTI);

    // Update the global list and its length
    pthread_mutex_lock(&global_list_lock);
    if(global_list != NULL) {
        free(global_list);
    }
    global_list = temp_list;
    global_list_len = N;
    pthread_mutex_unlock(&global_list_lock);

    return NULL;
}

// Function to compare two NFAPI_CRC_INDICATION_PDU_T structures based on RNTI
int compare_RNTI(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* struct_a = *(NFAPI_CRC_INDICATION_PDU_T**)a;
    NFAPI_CRC_INDICATION_PDU_T* struct_b = *(NFAPI_CRC_INDICATION_PDU_T**)b;

    if(struct_a->RNTI < struct_b->RNTI) {
        return -1;
    } else if(struct_a->RNTI > struct_b->RNTI) {
        return 1;
    }

    return 0;
}

// Function to update the global list
void update_global_list(int N, int start, int end) {
    pthread_mutex_lock(&global_list_lock);

    // Update the portion of the list between 'start' and 'end'
    for(int i = start; i < end; i++) {
        global_list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set RX_UE_INFORMATION_TAG to a unique string based on RNTI
        sprintf(global_list[i]->RX_UE_INFORMATION_TAG, "Tag_%d", i);

        // Set RNTI and CRCFLAG randomly
        global_list[i]->RNTI = rand() % 100;
        global_list[i]->CRCFLAG = (rand() % 2) ? 0 : 1;
    }

    pthread_mutex_unlock(&global_list_lock);
}

// Function to query the current state of the list
void query_global_list(int start, int end) {
    pthread_mutex_lock(&global_list_lock);

    // Iterate over the portion of the list between 'start' and 'end'
    for(int i = start; i < end; i++) {
        printf("RNTI: %d, RX_UE_INFORMATION_TAG: %s, CRCFLAG: %d\n", global_list[i]->RNTI, global_list[i]->RX_UE_INFORMATION_TAG, global_list[i]->CRCFLAG);
    }

    pthread_mutex_unlock(&global_list_lock);
}
