#include <time.h>

struct LTE_PHY_MEASUREMENTS {
    int ue_index;
    struct {
        long timestamp;
        int rsrp;
        float sinr;
    } *phr_list;
};

void populate_phy_measurements(struct LTE_PHY_MEASUREMENTS **phy_measurements, int num_measurements) {
    for (int i = 0; i < num_measurements; i++) {
        (*phy_measurements)->ue_index = i;

        // Initialize PHR list
        (*phy_measurements)->phr_list = (struct {
            long timestamp;
            int rsrp;
            float sinr;
        }*)malloc(sizeof(struct {
            long timestamp;
            int rsrp;
            float sinr;
        }));

        for (int j = 0; j < i + 1; j++) { // Each UE measurement has PHR list of increasing size
            (*phy_measurements)->phr_list->timestamp = clock(); // Monotonically increasing timestamps

            // Ensure RSRP and SINR values are within realistic ranges
            (*phy_measurements)->phr_list->rsrp = (rand() % 100) - 50; // Randomly generated integer value between -50 and 50
            (*phy_measurements)->phr_list->sinr = (float)(rand() / (RAND_MAX + 1.0)); // Randomly generated floating point value between 0 and 1

            (*phy_measurements)->phr_list++; // Move to next PHR measurement in the list
        }
    }
}
