#define MAX_BUFFER_SIZE 1024
#define MAX_SDUS 10

typedef struct {
    uint16_t dst_addr;
    uint16_t src_addr;
    uint8_t protocol_id;
    uint8_t hdrlen;
} mac_header_t;

typedef struct {
    mac_header_t header;
    unsigned char* payload;
    size_t len;
} sdus_t;

void create_mac_pdu_list(int num_pdus, int max_sdus_per_pdu, size_t max_sdu_len) {
    srand(time(NULL));

    // Create the list of PDUs
    sdus_t* pdu_list = (sdus_t*)malloc(num_pdus * sizeof(sdus_t));

    for (int i = 0; i < num_pdus; i++) {
        mac_header_t header;
        header.dst_addr = rand() % 65536;
        header.src_addr = rand() % 65536;
        header.protocol_id = rand() % 256;
        header.hdrlen = sizeof(mac_header_t) / sizeof(uint8_t);

        // Calculate the size of each SDU
        int sdu_count = rand() % max_sdus_per_pdu + 1;
        int total_sdu_len = 0;

        for (int j = 0; j < sdu_count; j++) {
            sdus_t sdu;
            sdu.header = header;
            sdu.payload = malloc(rand() % max_sdu_len + 1);
            size_t len = rand() % max_sdu_len;
            sdu.len = len;
            total_sdu_len += len;

            // Check if the total SDU length exceeds the buffer size
            if (total_sdu_len > MAX_BUFFER_SIZE) {
                free(sdu.payload);
                j--;
                continue;
            }

            pdu_list[i].len = sizeof(mac_header_t) + total_sdu_len;
            pdu_list[i].header = header;
            pdu_list[i].payload = malloc(pdu_list[i].len);

            // Copy the SDUs to the PDU
            size_t offset = 0;
            for (int k = 0; k < sdu_count; k++) {
                memcpy((pdu_list[i].payload + offset), &sdu, sizeof(sdus_t));
                offset += sizeof(sdus_t) + sdu.len;
            }

            break;
        }
    }
}
