NFAPI_CRC_INDICATION_PDU_T* generate_nfcrc_indication_pdu(int N) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

