        strcpy(pdu_list[i].RX_UE_INFORMATION_TAG, "TAG");
        pdu_list[i].RNTI = rand() % 100;
        pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        // Simulate delay or failure in accessing external data source
        if (i % 10 == 0) {
            sleep(1);
        }
    }

    return pdu_list;
}

char* encrypt_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, const char* key, const char* iv) {
    DES_key_schedule des_key;
    DES_set_key(&des_key, (const unsigned char*)key, strlen(key));
    DES_cblock des_iv = {(unsigned char)atoi(iv), 0};
    DES_set_ivec(&des_iv);

    char* encrypted_pdu = (char*)malloc((sizeof(NFAPI_CRC_INDICATION_PDU_T) + 8) * sizeof(char));

    for (int i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        unsigned char byte;
        DES_ecb_encrypt(&pdu[i].RX_UE_INFORMATION_TAG[i], &byte, &des_key, &des_iv);
        sprintf(encrypted_pdu + i * sizeof(char), "%02x", byte);

        if (i % 2 == 0) {
            encrypted_pdu[i] = '\0';
