int create_crc_indication_pdu_list(json_object *config, size_t *count) {
    json_object *rx_channels = json_object_object_get(config, "rx_channels");
    json_object *ue_ids = json_object_object_get(config, "ue_ids");
    json_object *crc_flags = json_object_object_get(config, "crc_flags");

