        printf("Invalid configuration: missing required field\n");
        return 0;
    }

    size_t len = json_object_array_length(rx_channels);
    if (len != json_object_array_length(ue_ids) || len != json_object_array_length(crc_flags)) {
        printf("Invalid configuration: arrays must have the same length\n");
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(len * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Memory allocation failed\n");
        return 0;
    }

    for (size_t i = 0; i < len; i++) {
        json_object *rx_channel = json_object_array_get_idx(rx_channels, i);
        json_object *ue_id = json_object_array_get_idx(ue_ids, i);
        json_object *crc_flag = json_object_array_get_idx(crc_flags, i);

        if (!rx_channel || !ue_id || !crc_flag) {
            printf("Invalid configuration: missing value at index %zu\n", i);
