use reqwest;

async fn create_http_client(url: &str, disable_cert_validation: bool) -> reqwest::blocking::RequestBuilder {
    let mut client = match reqwest::blocking::Client::new() {
        Ok(client) => client,
        Err(e) => return Err(format!("Failed to create HTTP client: {}", e)),
    };

    if disable_cert_validation {
        client = client.badger().badger_tls(false);
    }

    client.get(url).attach_header("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3")
}
