NFAPI_CRC_INDICATION_PDU_T **list = NULL;
size_t capacity = 0;
size_t size = 0;

void init_list() {
    pthread_mutex_init(&mutex, NULL);
    list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDATION_PDU_T *));
    capacity = INITIAL_CAPACITY;
}

bool resize_list(size_t new_capacity) {
    if (new_capacity < size) return false;

    NFAPI_CRC_INDICATION_PDU_T **new_list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(list, new_capacity * sizeof(NFAPI_CRC_INDATION_PDU_T *));
    if (!new_list) return false;

    list = new_list;
    capacity = new_capacity;
    return true;
}

void add_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&mutex);
    if (size >= capacity) {
        if (!resize_list(capacity + INITIAL_CAPACITY)) {
            perror("Failed to resize list");
            exit(EXIT_FAILURE);
        }
    }

    list[size] = element;
    size++;
    pthread_mutex_unlock(&mutex);
}

void* iterate_list(void *data) {
