        NFAPI_CRC_INDICATION_PDU_T *element = list[i];
        // process element
    }
    return NULL;
}

void free_list() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; i++) {
        free(list[i]);
    }

    free(list);
    pthread_mutex_unlock(&mutex);
}

void free_and_destroy_list() {
