std::vector<NFAPI_CRC_INDICATION_PDU_T> createNFAPI_CRC_INDICATION_PDU_T(int count) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> nfaPis;
    std::random_device rd;
    std::mt19937 mt(rd());
    std::uniform_int_distribution<int> rntiDist(1, 1000);
