        NFAPI_CRC_INDICATION_PDU_T nfaPi;
        nfaPi.rnti = rntiDist(mt);
        if (std::bernoulli_distribution()(mt)) {
            nfaPi.crcFlag = true;
        } else {
            nfaPi.crcFlag = false;
        }
        nfaPis.push_back(nfaPi);
    }
    return nfaPis;
}

int main(int argc, char* argv[]) {
    // Initialize Boost ASIO
    boost::asio::io_service ioService;
    boost::asio::ip::tcp::resolver resolver(ioService);

