            boost::asio::connect(socket, resolver.resolve(url));
            boost::asio::write(socket, "GET / HTTP/1.0\r\nHost: " + url + "\r\n\r\n");

            // Handle potential network latency and server availability issues
            boost::asio::deadline_timer timer(ioService);
            timer.expires_from_now(boost::posix_time::millis(500));
            if (!boost::this_thread::interruption_point()) {
                timer.wait();
            }

            // Read the response from the server
            boost::array<char, 512> buffer;
            boost::asio::read(socket, boost::asio::buffer(buffer));

            // Verify that the response matches expected values based on configurable thresholds
            std::cout << "Received response: " << buffer.data() << std::endl;

        } catch (const boost::system::system_error& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }

    return 0;
}

