typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[1];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t len;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T create_list() {
    NFAPI_CRC_INDICATION_LIST_T list = (NFAPI_CRC_INDICATION_LIST_T)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    list->len = 0;
    list->data = NULL;
    return list;
}

void free_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list) {
        pthread_mutex_destroy(&((*list)->lock));
        free((*list)->data);
        free(list);
    }
}

void add_to_list(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDINATION_PDU_T data) {
    pthread_mutex_lock(&(*list)->lock);
    (*list)->data = realloc((*list)->data, ((*list)->len + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(&((*list)->data)[(*list)->len], &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*list)->len++;
    pthread_mutex_unlock(&(*list)->lock);
}

int sort_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&(*list)->lock);
    qsort((*list)->data, (*list)->len, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare);
    pthread_mutex_unlock(&(*list)->lock);
    return 0;
}

int serialize_list(NFAPI_CRC_INDICATION_LIST_T* list, FILE* file) {
    pthread_mutex_lock(&(*list)->lock);
    fwrite((*list)->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), (*list)->len, file);
    pthread_mutex_unlock(&(*list)->lock);
    return 0;
}

int deserialize_list(NFAPI_CRC_INDICATION_LIST_T* list, FILE* file) {
    pthread_mutex_lock(&(*list)->lock);
    fseek(file, 0, SEEK_SET);
    size_t len = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fread((*list)->data, len, (*list)->len, file);
    pthread_mutex_unlock(&(*list)->lock);
    return 0;
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T list = create_list();

    // Add data to the list
    for (size_t i = 0; i < 100000; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {i, i};
        add_to_list(&list, data);
    }

    // Sort the list by RNTI in ascending order
    sort_list(&list);

    // Serialize the list to a file for later use or deserialization back into memory
    FILE* file = fopen("output.txt", "wb");
    if (file) {
        serialize_list(&list, file);
        fclose(file);
    }

    // Free the list when done
    free_list(&list);

    return 0;
}
