        if (strlen(cache_root) == 0)
            strcpy(cache_root, DEFAULT_AUDIO_DIR);

        // Parse MP3 files from cache root directory without causing excessive I/O operations
        DIR *dir;
        struct dirent *ent;

        if ((dir = opendir(cache_root)) != NULL) {
            while ((ent = readdir(dir)) != NULL) {
                if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                    continue;

                // Implement caching mechanism for audio files
                int file_size;
                FILE *file = fopen(cache_root + "/" + ent->d_name, "rb");
                if (file) {
                    fseek(file, 0L, SEEK_END);
                    file_size = ftell(file);
                    rewind(file);

                    // Check if file is already cached
                    if (file_size <= MAX_CACHE_SIZE)
                        printf("File %s is already cached\n", ent->d_name);
                    else
                        printf("File %s exceeds cache size limit\n", ent->d_name);

                    fclose(file);
