#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* initializeRecords(int n) {
    record *records = malloc(sizeof(record) * n);
    if (records == NULL) {
        return NULL; // memory allocation failed
    }

    for (int i = 0; i < n; i++) {
        records[i].value = rand() % 100; // random value between 0 and 99
    }

    return records;
}

void freeMemory(record* offsets, int *keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    const int n = 10;

    long *offsets = malloc(sizeof(long) * n);
    if (offsets == NULL) {
        printf("Memory allocation failed for offsets.\n");
        return -1;
    }

    int *keys = malloc(sizeof(int) * n);
    if (keys == NULL) {
        printf("Memory allocation failed for keys.\n");
        free(offsets); // clean up partially allocated memory
        return -1;
    }

    record *records = initializeRecords(n);

