            return -1;
        }

        pdu->RX_UE_INFORMATION_TAG = (your valid RX_UE_INFORMATION_TAG logic);
        pdu->RNTI = (your RNTI value logic);
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // randomly set CRCFLAG

        if (pdu_list == NULL) {
            pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            used = capacity;
        } else if (used == capacity) {
            size_t new_capacity = capacity * 2 + 1;
            NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_list == NULL) {
                printf("Memory allocation failed\n");
                return -1;
            }
            pdu_list = new_list;
            capacity = new_capacity;
        }

        int j;
        for (j = 0; j < used; j++) {
            if (pdu->RNTI == pdu_list[j].RNTI) {
                free(pdu);
                printf("Duplicate RNTI found\n");
                return -1;
            }
        }

        pdu_list[used] = *pdu;
        used++;
    }

    // periodically check for duplicate RNTI values within the list
    int k;
    for (k = 0; k < used; k++) {
        int l;
        for (l = k + 1; l < used; l++) {
            if (pdu_list[k].RNTI == pdu_list[l].RNTI) {
                // remove duplicate RNTI
                memmove(&pdu_list[l], &pdu_list[l + 1], (used - l - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                used--;
                k--; // recheck for duplicates starting from k again
            }
        }
    }

    return 0;
}
