    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((size_t)capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) return NULL;

    for (int i = 0; i < capacity; ++i)
        list[i] = NULL;

    return list;
}

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T** list, int* capacity, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) return;

    new_pdu->ue_info = ue_info;
    new_pdu->rnti = rnti;
    int crcflag = rand() % 2;
    new_pdu->crc_tag = (CRC_INDICATION_REL8_TAG){.crcflag = crcflag};

    if (!validate_ue_info(ue_info)) {
        free(new_pdu);
        return;
    }

    for (int i = 0; i < *capacity; ++i) {
        if (list[i] && list[i]->rnti == rnti) {
            free(list[i]);
            break;
        }
    }

    int found_duplicate = 0;
    for (int i = 0; i < *capacity; ++i) {
        if (list[i] && list[i]->rnti == rnti) {
            found_duplicate = 1;
            free(new_pdu);
            return;
        }
    }

    if (!found_duplicate) {
        int idx = *capacity;
        while (idx > 0) {
            --idx;
            if (!list[idx]) {
                list[idx] = new_pdu;
                break;
            } else if (idx == 1) {
                printf("List is full. Cannot add more elements.\n");
                free(new_pdu);
                return;
            }
        }

        if (idx < *capacity) {
            ++(*capacity);
            NFAPI_CRC_INDICATION_PDU_T** temp_list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, (size_t)*capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            list = temp_list;
        }
    }

    free(new_pdu);
}

int save_crc_indications(NFAPI_CRC_INDICATION_PDU_T** list, int capacity) {
    FILE* file = fopen("crc_indications.txt", "wb");
    if (!file) return 1;

    for (int i = 0; i < capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = list[i];
        if (pdu) {
            fwrite(&pdu->ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
            fwrite(&pdu->rnti, sizeof(RNTI), 1, file);
            fwrite(&pdu->crc_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);

            // Perform checksum on saved data
            uint32_t checksum = calculate_checksum(file);
            fwrite(&checksum, sizeof(uint32_t), 1, file);
        }
    }

    fclose(file);
    return 0;
}

