        return NULL; // Return error code or a special value indicating an error.
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_list[i];
        UE_INFO ue_info;

        // Generate unique RX_UE_INFORMATION_TAG and RNTI
        ue_info.RX_UE_INFORMATION_TAG = rand() % 100;
        ue_info.RNTI = rand() % 100;

        pdu->RX_UE_INFORMATION_TAG = ue_info.RX_UE_INFORMATION_TAG;
        pdu->RNTI = ue_info.RNTI;

        // Generate random CRCFLAG for the CRC_INDICATION_REL8_TAG
        pdu->CRCFLAG = rand() % 2; // 0 or 1

        LOG_WARNING("Processing structure %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d", i + 1,
                    pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
    }

    // Sort the list of structures based on RNTI in ascending order
    qsort(crc_list, num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_RNTI);

    return crc_list;
}

// Compare function for sorting NFAPI_CRC_INDICATION_PDU_T structures by RNTI
int compare_RNTI(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;

    if (pdu_a->RNTI < pdu_b->RNTI) {
        return -1; // a comes before b
    } else if (pdu_a->RNTI > pdu_b->RNTI) {
        return 1; // a comes after b
    }
    return 0; // a and b have the same RNTI
}
