    RRC_ConfigurationUpdate_t rrcConfig;
    AdditionalInfo_t additionalInfo;
} LTE_RRC_ConfigurationUpdateItem_t;

// Function to create and populate a list of LTE_RRC_ConfigurationUpdateItem_t structures
LTE_RRC_ConfigurationUpdateItem_t** createConfigurationUpdateList(int maxSize) {
    // Initialize the list with a null pointer as the first element
    LTE_RRC_ConfigurationUpdateItem_t** list = (LTE_RRC_ConfigurationUpdateItem_t**)malloc((maxSize + 1) * sizeof(LTE_RRC_ConfigurationUpdateItem_t*));
    if (!list) return NULL;

    // Set the first element to null
    list[0] = NULL;

    int count = 0;
    for (int i = 0; i < maxSize && i < 1000; i++) {
        UE_Identity_t ueId;
        RRC_ConfigurationUpdate_t rrcConfig;
        AdditionalInfo_t additionalInfo;

        // Generate random data
        srand(time(NULL));
        ueId.ueId = rand() % 10000;
        strcpy(rrcConfig.configUpdate, "Randomly generated config update");
        additionalInfo.additionalInfo = (rand() & 1) ? true : false;

        // Dynamically allocate memory for the new item
        LTE_RRC_ConfigurationUpdateItem_t* newItem = (LTE_RRC_ConfigurationUpdateItem_t*)malloc(sizeof(LTE_RRC_ConfigurationUpdateItem_t));
        if (!newItem) {
            free(list);
            return NULL;
        }

        // Initialize the new item with the generated data
        newItem->ueId = ueId;
        strcpy(newItem->rrcConfig.configUpdate, rrcConfig.configUpdate);
        newItem->additionalInfo = additionalInfo;

        // Add the new item to the list and increment the count
        list[++count] = newItem;
    }

    return list;
}

// Free dynamically allocated memory for the list
void freeConfigurationUpdateList(LTE_RRC_ConfigurationUpdateItem_t** list) {
    int i;
    for (i = 1; i <= *(int*)(&list[0]); i++) {
        if (list[i]) free(list[i]);
    }
    free(list);
}

// Example usage:
int main() {
    LTE_RRC_ConfigurationUpdateItem_t** configurationList = createConfigurationUpdateList(1000);
    // Use the list...
    freeConfigurationUpdateList(configurationList);
    return 0;
}
