#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_N 1000
#define LOG_LEVEL 1

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu(int N) {
    pthread_mutex_lock();
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        printf("Error allocating memory.\n");
        free(pdu_array);
        pthread_mutex_unlock();
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_array[i].RNTI = rand() % 1000;
        pdu_array[i].CRCFLAG = (rand() & 1);
        printf("Created structure index: %d, RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", i,
               pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI, pdu_array[i].CRCFLAG);

    }

    if (pdu_array) {
        for (int i = 0; i < N; i++) {
            free(pdu_array);
        }
        pthread_mutex_unlock();
        return NULL;
    }

    pthread_mutex_unlock();

    return pdu_array;
}

void log_stats(int total_created) {
    printf("Total created: %d\n", total_created);

    // Simulate periodic logging for tracking system usage patterns
    if (LOG_LEVEL > 1) {
        time_t now = time(NULL);
        char* ctime_str = ctime(&now);
        printf("Log stats at: %s\n", ctime_str);
    }
}

int main() {
    int N;
    printf("Enter the number of structures to create: ");
    scanf("%d", &N);

    if (N < 1 || N > MAX_N) {
        printf("Invalid input. Number must be between 1 and %d.\n", MAX_N);
        return -1;
    }

    int total_created = 0;

    while (N <= MAX_N) {
        pthread_mutex_lock();
        NFAPI_CRC_INDICATION_PDU_T *pdu_array = create_crc_indication_pdu(N);
        if (!pdu_array) {
            break;
        }
        free(pdu_array);
        total_created += N;
        log_stats(total_created);
        pthread_mutex_unlock();

    }

    return 0;
}

