LTE_RRC_ConfigurationUpdateItem_t* create_list(int initial_size) {
    LTE_RRC_ConfigurationUpdateItem_t* list = (LTE_RRC_ConfigurationUpdateItem_t*)malloc(initial_size * sizeof(LTE_RRC_ConfigurationUpdateItem_t));
    return list;
}

void populate_list(LTE_RRC_ConfigurationUpdateItem_t** list, int* size, FILE* csv_file) {
    // Initialize variables
    json_object *json_obj = NULL;
    json_object *ue_id_obj = NULL;
    json_object *identity_obj = NULL;
    json_object *is_valid_obj = NULL;

    // Read CSV file in chunks
    fseek(csv_file, 0L, SEEK_END);
    long sizeOfFile = ftell(csv_file);
    rewind(csv_file);

    int chunk_size = 10000; // Adjust the chunk size as needed based on performance considerations

    for (int i = 0; i < sizeOfFile / chunk_size + 1; i++) {
        fseek(csv_file, i * chunk_size, SEEK_SET);

        char line[chunk_size];
        fgets(line, sizeof(line), csv_file);

        json_obj = json_object_from_json(line);

        if (json_obj == NULL) {
            continue;
        }

        ue_id_obj = json_object_object_get(json_obj, "UE_ID");
        identity_obj = json_object_object_get(json_obj, "Identity");

        if (ue_id_obj && identity_obj) {
            LTE_RRC_ConfigurationUpdateItem_t* item = (*list + i % *size];

            // Populate the structure
            item->ue_identity.ue_id = json_object_get_int(ue_id_obj);
            strncpy(item->ue_identity.identity, json_object_get_string(identity_obj), sizeof(item->ue_identity.identity));
            item->additional_info.is_valid = TRUE; // Randomly set boolean value

            (*size)++;
        }

        json_object_free(json_obj);
    }
}

void log_operations(int successful_updates, int failed_updates) {
    FILE* log_file = fopen("log.json", "a");
    if (log_file != NULL) {
        fprintf(log_file, "{\"successful_updates\": %d, \"failed_updates\": %d}\n", successful_updates, failed_updates);
        fclose(log_file);
    }
}

int main() {
    // Initialize variables
    int list_size = 0;
    LTE_RRC_ConfigurationUpdateItem_t* list = create_list(10);

    FILE* csv_file = fopen("ue_identities.csv", "r");
    if (csv_file != NULL) {
        populate_list(&list, &list_size, csv_file);
        fclose(csv_file);

        // Perform concurrent updates from different threads
        pthread_t thread1;
        pthread_t thread2;

        pthread_create(&thread1, NULL, update_list_concurrently, (void*)list);
        pthread_create(&thread2, NULL, update_list_concurrently, (void*)list);

        pthread_join(thread1);
        pthread_join(thread2);

        log_operations(list_size, 0);
    } else {
        printf("Error opening CSV file.\n");
        list_size = 0;
    }

    return 0;
}

