// Define the structure for UE context
typedef struct {
    int ue_id;
    int cell_id;
    struct {
        double signal_strength;
        int frequency;
        time_t timestamp;
    } measurement_reports[10]; // assuming a maximum of 10 reports per UE
} UeContext;

// Define the list of UE contexts and its size
typedef struct {
    UeContext *contexts;
    int size;
    pthread_mutex_t lock; // for thread safety
} UeContextList;

// Function to initialize and populate the list of UE contexts
UeContextList* init_ue_context_list(int initial_size) {
    UeContextList* ue_ctx_list = (UeContextList*)malloc(sizeof(UeContextList));
    ue_ctx_list->contexts = (UeContext*)calloc(initial_size, sizeof(UeContext));
    ue_ctx_list->size = initial_size;
    pthread_mutex_init(&ue_ctx_list->lock, NULL);
    return ue_ctx_list;
}

// Function to add a new UE context to the list
void add_ue_context(UeContextList* ue_ctx_list, int ue_id, int cell_id) {
    UeContext new_ctx;
    new_ctx.ue_id = ue_id;
    new_ctx.cell_id = cell_id;
    // populate measurement reports...
    pthread_mutex_lock(&ue_ctx_list->lock);
    if (ue_ctx_list->size == 0) {
        ue_ctx_list->contexts = (UeContext*)realloc(ue_ctx_list->contexts, sizeof(UeContext));
        ue_ctx_list->size++;
    }
    memcpy(&ue_ctx_list->contexts[ue_ctx_list->size-1], &new_ctx, sizeof(UeContext));
    pthread_mutex_unlock(&ue_ctx_list->lock);
}

// Function to free the list of UE contexts
void free_ue_context_list(UeContextList* ue_ctx_list) {
    if (ue_ctx_list != NULL) {
        for (int i = 0; i < ue_ctx_list->size; i++) {
            free(&ue_ctx_list->contexts[i]);
        }
        free(ue_ctx_list->contexts);
        pthread_mutex_destroy(&ue_ctx_list->lock);
        free(ue_ctx_list);
    }
}
