    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    struct {
        unsigned CRCFLAG:1;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indication_pdu_list(int max_size, NFAPI_CRC_INDICATION_PDU_T **list) {
    int i, num_elements = 0;
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) return -1;

    srand(time(NULL));

    for (i = 0; i < max_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(*list)[i];
        strcpy(pdu->RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
        pdu->RNTI = rand() % 100 + 1;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (num_elements > 0) {
            int j;
            for (j = 0; j < num_elements; j++) {
                if ((*list)[j].RNTI == pdu->RNTI) return -1;
            }
        }

        num_elements++;
    }

    qsort(*list, num_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), cmp);

    for (i = 0; i < num_elements - 1; i++) {
        if ((*list)[i].RNTI >= (*list)[i+1].RNTI) return -1;
    }

    return 0;
}

int cmp(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T* pdum = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pduf = (NFAPI_CRC_INDICATION_PDU_T*)b;

    if (pdum->RNTI < pduf->RNTI) return -1;
    else if (pdum->RNTI > pduf->RNTI) return 1;
    else return 0;
}

void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* list, int num_elements) {
    free(list);
}
