    pthread_mutex_t lock; // for thread safety
    time_t last_updated[MAX_ENTRIES];
} List;

List* list_create(int initial_capacity) {
    List* new_list = (List*)malloc(sizeof(List));
    if (!new_list) return NULL;

    new_list->size = 0;
    new_list->capacity = initial_capacity;
    new_list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(new_list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_init(&new_list->lock, NULL);

    return new_list;
}

void list_free(List* lst) {
    if (!lst) return;

    free(lst->entries);
    pthread_mutex_destroy(&lst->lock);

    free(lst);
}

int list_add_entry(List* lst, NFAPI_CRC_INDICATION_PDU_T entry) {
    // handle overflows
    if (lst->size >= lst->capacity) {
        int new_capacity = lst->capacity * 2;
        lst->entries = realloc(lst->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
