        lst->capacity = new_capacity;
    }

    // add entry
    lst->entries[lst->size++] = entry;

    for (int i = 0; i < lst->size; ++i)
        lst->last_updated[i] = time(NULL);

    return 0;
}

void list_remove_expired_entries(List* lst) {
    int i, j = 0;
    for (i = 0; i < lst->size; ++i) {
        if ((time(NULL) - lst->last_updated[i]) > TTL_DEFAULT) {
            // expired entry
            continue;
        }
        lst->entries[j++] = lst->entries[i];
    }

    lst->size = j;

    // shrink capacity if necessary
    while (lst->size < (int)(0.25 * lst->capacity)) {
        int new_capacity = (int)(0.5 * lst->capacity);
        if (new_capacity > 10) break; // don't go too small

        lst->entries = realloc(lst->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!lst->entries) return; // memory allocation failure

        lst->capacity = new_capacity;
    }
}

void list_serialize(List* lst, FILE* file) {
