}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    NFAPI_CRC_INDICATION_PDU_T *current = list;
    NFAPI_CRC_INDICATION_PDU_T *next = NULL;
    while (current != NULL) {
        next = current->next; // store the next element before freeing
        free(current);
        current = next;
    }
}

void restructure_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t num_elements, NFAPI_CRC_INDICATION_PDU_T *chunk) {
