int structure_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void init_log_file(int level) {
    pthread_mutex_lock(&lock);
    if (!log_file) {
        log_file = fopen("nfaapi_crc_indication.log", "w");
        if (!log_file) {
            printf("Error opening log file!\n");
            exit(1);
        }
        // Set logging level
        switch (level) {
            case 0: // Debug
                fprintf(log_file, "[DEBUG] ");
                break;
            case 1: // Info
                fprintf(log_file, "[INFO] ");
                break;
            case 2: // Error
                fprintf(log_file, "[ERROR] ");
                break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void log_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (log_file && structure) {
        pthread_mutex_lock(&lock);
        fprintf(log_file, "RNTI: %d, CRCFLAG: %u\n", structure->rnti, structure->crc_indication.crcflag);
        pthread_mutex_unlock(&lock);
    }
}

NFAPI_CRC_INDICATION_PDU_T *create_structures(int n) {
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    int i;

    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure) {
            printf("Error allocating memory!\n");
            return NULL;
        }
        structure->rx_ue_info = (RX_UE_INFORMATION_TAG){.tag = 1, .reserved = 0};
        structure->rnti = rand() % 100;
        structure->crc_indication.crcflag = rand() & 0x1F;
        log_structure(structure);
        if (!structures) {
            structures = structure;
        } else {
            structure_count++;
            structures[structure_count - 1] = structure;
        }
    }

    return structures;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T *structures, int count) {
    for (int i = 0; i < count; i++) {
        if (structures[i]) {
            free(structures[i]);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T *get_structure(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *structure;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < structure_count; i++) {
        if (structures[i]->rnti == rnti) {
            structure = structures[i];
            break;
        }
    }
    pthread_mutex_unlock(&lock);

    return structure;
}

void close_log_file() {
    pthread_mutex_lock(&lock);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
