// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T **create_and_populate_list(int num_structures) {
    // Initialize a pointer to the head of the list
    NFAPI_CRC_INDICATION_PDU_T **list = NULL;

    // Calculate the total number of bytes required for the list
    int total_bytes = sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (num_structures + 1);

    // Allocate memory for the list
    if (!(list = malloc(total_bytes))) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the head of the list
    *list = NULL;

    // Iterate over the range [0, num_structures)
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = NULL;

        // Allocate memory for the current structure
        if (!(structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Populate the current structure with random values
        structure->RX_UE_INFORMATION_TAG = rand();
        structure->RNTI = rand();
        structure->CRCFLAG = rand() % 2;

        // Add the current structure to the list
        if (*list) {
            NFAPI_CRC_INDICATION_PDU_T **last_structure = *list;
            while (*last_structure) last_structure = *last_structure;
            *last_structure = &structure;
        } else {
            *list = &structure;
        }
    }

    return list;
}

