#define MAX_MEASUREMENTS 1000
#define MAX_PHR_LIST_SIZE 5

struct LTE_PHY_MEASUREMENTS {
    int ue_index;
    struct {
        long timestamp;
        int rsrp;
        float sinr;
    } phr_list[MAX_PHR_LIST_SIZE];
};

void populate_phy_measurements(int num_measurements, struct LTE_PHY_MEASUREMENTS *measurements) {
    for (int i = 0; i < num_measurements; i++) {
        measurements->ue_index = i + 1;
        for (int j = 0; j < MAX_PHR_LIST_SIZE; j++) {
            measurements->phr_list[j].timestamp = time(NULL);
            measurements->phr_list[j].rsrp = rand() % 100 - 50;
            measurements->phr_list[j].sinr = (float)rand() / RAND_MAX;
        }
    }
}

int resolve_hostname(const char *hostname, u_char *ip_address) {
    int fd;
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM; // TCP
    hints.ai_protocol = 0; // Any protocol
    hints.ai_flags = AI_CANONNAME | AI_NUMERICHOST;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        printf("Error resolving hostname: %s\n", gai_strerror(errno));
        return -1;
    }

    fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) {
        printf("Failed to create socket\n");
        return -2;
    }

    inet_ntop(AF_INET, &((struct sockaddr_in*)res->ai_addr)->sin_addr, ip_address, INET6_ADDRSTRLEN);
    close(fd);

    freeaddrinfo(res);
    return 0;
}
