void manageThemeCache(char **themeBitmap, char *defaultThemeDir) {
    // Check if a theme bitmap is recycled
    if (*themeBitmap != NULL) {
        free(*themeBitmap);
        *themeBitmap = NULL;
    }

    // Set default theme directory if not set
    if (strlen(defaultThemeDir) == 0) {
        strcpy(defaultThemeDir, "/path/to/default/theme");
    }
}

void parsePNGFile(char *cacheRootDir, char **themeBitmap) {
    // Parse PNG file from cache root directory and put it in the theme cache
    FILE *file = fopen(cacheRootDir, "rb");

    if (file == NULL) {
        printf("Error opening file. Exiting.\n");
        exit(1);
    }

    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);

    char *buffer = (char *)malloc(fileSize + 1);
    rewind(file);

    fread(buffer, sizeof(char), fileSize, file);
    buffer[fileSize] = '\0';

    fclose(file);

    free(*themeBitmap);
    *themeBitmap = buffer;
}

void deriveEncryptionKeyFromPassword(const unsigned char *password, unsigned char **derivedKey) {
    SHA_CTX shaCtx;
    unsigned char derivedKeyBuff[SHA_DIGEST_LENGTH];

    SHA1_Init(&shaCtx);
    SHA1_Update(&shaCtx, password, strlen((char *)password));
    SHA1_Final(derivedKeyBuff, &shaCtx);

    *derivedKey = (unsigned char *)malloc(SHA_DIGEST_LENGTH);
    memcpy(*derivedKey, derivedKeyBuff, SHA_DIGEST_LENGTH);
}

void enableAES256CBCCipher(const unsigned char *derivedKey, const unsigned char *iv, AES_KEY *aesKey) {
    AES_set_encrypt_key(derivedKey, 32, aesKey);
    AES_set_iv(iv, 16);
}
