#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEAF_NODES 1000
#define DATA_CAPACITY 1024

typedef struct {
    int rnti;
    char crcflag[1];
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* children[8];
};

NFAPI_CRC_INDICATION_PDU_T** createOctree(size_t featureSize, size_t numLeafNodes) {
    size_t depth = (size_t)log2(featureSize);
    struct Node* root = (struct Node*)malloc(sizeof(struct Node));
    root->capacity = 0;
    root->count = 0;
    root->data = NULL;
    for(int i=0; i<8; i++) {
        root->children[i] = NULL;
    }

    // Calculate the number of nodes at each level
    size_t* numNodesAtEachLevel = (size_t*)malloc((depth + 1) * sizeof(size_t));
    for(size_t i = 0; i < depth; i++) {
        numNodesAtEachLevel[i] = (1 << (i+1));
    }
    numNodesAtEachLevel[depth] = 1;

    // Populate the octree
    populateOctree(root, numLeafNodes, dataCapacity, &numNodesAtEachLevel);

    return NULL;
}

void populateOctree(struct Node* node, size_t numNodes, size_t dataCapacity, size_t** numNodesAtEachLevel) {
    if(node->count >= node->capacity) {
        // If the node is full, create a new one
        struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
        newNode->capacity = 0;
        newNode->count = 0;
        newNode->data = NULL;
        for(int i=0; i<8; i++) {
            newNode->children[i] = NULL;
        }

        // Calculate the position of the new node in the octree
        size_t* numNodesAtLevel = (size_t*)malloc((node->count + 1) * sizeof(size_t));
        for(size_t i = 0; i < node->count; i++) {
            numNodesAtLevel[i] = i;
        }
        numNodesAtLevel[node->count] = numNodes - node->count;

        // Recursively populate the new node
        populateOctree(newNode, numNodesAtLevel[1], dataCapacity, &numNodesAtEachLevel);

        // Free the old node
        free(node->data);
        for(int i=0; i<8; i++) {
            if(node->children[i]) {
                free(node->children[i]);
            }
        }
        free(node);
    } else {
        // If the node is not full, fill it with data
        NFAPI_CRC_INDICATION_PDU_T** data = (NFAPI_CRC_INDICATION_PDU_T**)malloc((node->capacity + numNodes) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        for(size_t i = 0; i < node->count; i++) {
            data[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Fill the data structure with random values
            data[i]->rnti = rand();
            strcpy(data[i]->crcflag, "random value");
        }
        for(size_t i = node->count; i < (node->count + numNodes); i++) {
            data[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Fill the data structure with random values
            data[i]->rnti = rand();
            strcpy(data[i]->crcflag, "random value");
        }

        node->data = data;
    }

    // If this is a leaf node, stop here
    if(node->count >= numNodes) {
        return;
    }

    // Otherwise, recursively populate the children
    for(int i=0; i<8; i++) {
        if(numNodesAtEachLevel[node->count + 1] > 1) {
            struct Node* child = (struct Node*)malloc(sizeof(struct Node));
            child->capacity = 0;
            child->count = 0;
            child->data = NULL;
            for(int j=0; j<8; j++) {
                child->children[j] = NULL;
            }

            // Calculate the number of nodes at this level
            numNodesAtLevel[node->count + 1]--;
            size_t* newNumNodesAtEachLevel = (size_t*)malloc((node->count + 2) * sizeof(size_t));
            for(size_t j = 0; j < node->count + 1; j++) {
                newNumNodesAtEachLevel[j] = numNodesAtLevel[j];
            }
            newNumNodesAtEachLevel[node->count + 1] = 1;

            // Recursively populate the child
            populateOctree(child, newNumNodesAtEachLevel[1], dataCapacity, &newNumNodesAtEachLevel);

            node->children[i] = child;
        }
    }
}
