#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

void initialize_list(Node** head) {
    *head = NULL;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL || (*head)->next == NULL) {
        *head = new_node;
        return;
    }
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    new_node->prev = current;
}

void delete_node(Node** head, Node* node_to_delete) {
    if (node_to_delete->prev == NULL)
        (*head) = node_to_delete->next;
    else
        node_to_delete->prev->next = node_to_delete->next;

    if (node_to_delete->next != NULL)
        node_to_delete->next->prev = node_to_delete->prev;

    free(node_to_delete);
}

void display_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", 
               current->data->RX_UE_INFORMATION_TAG, current->data->RNTI, 
               current->data->CRC_INDICATION_REL8_TAG, current->data->CRCFLAG);
        current = current->next;
    }
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

#include <stdlib.h>
#include <stdio.h>

int main() {
    int N = 100000; // or any other desired size
    Node* head = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->RX_UE_INFORMATION_TAG = rand();
        data->RNTI = rand();
        data->CRC_INDICATION_REL8_TAG = rand();
        data->CRCFLAG = rand() % 2;

        Node* new_node = create_node(data);
        if (new_node == NULL)
            continue;

        insert_node(&head, new_node);

        // Check memory usage
        unsigned long mem_usage = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
        double total_memory_in_bytes = mem_usage;
        double allocated_memory_in_bytes = 0;

        if (getrusage(RUSAGE_SELF, &ru)) {
            // Get the allocated memory in bytes
            allocated_memory_in_bytes = ru.ru_maxrss;
        }

        if ((double)allocated_memory_in_bytes / total_memory_in_bytes > 0.9) {
            printf("Memory usage has exceeded 90% of available system memory.\n");
        }
    }

    display_list(head);
    free_list(&head);

    return 0;
}

