#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Doubly Linked List Node Structure
typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
} node_t;

node_t* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* newNode = (node_t*) malloc(sizeof(node_t));
    if (!newNode) return NULL; // Memory allocation failed
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void freeList(node_t** headRef) {
    node_t* current = *headRef;
    node_t* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *headRef = NULL; // Reset the head
}

void insertNode(node_t** headRef, NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* newNode = createNode(data);
    if (*headRef == NULL || (*headRef)->data.RX_UE_INFORMATION_TAG < newNode->data.RX_UE_INFORMATION_TAG)
        *headRef = newNode;
    else {
        node_t* current = *headRef;
        while (current != NULL && current->next != NULL && current->next->data.RX_UE_INFORMATION_TAG >= newNode->data.RX_UE_INFORMATION_TAG) {
            current = current->next;
        }
        newNode->prev = current;
        newNode->next = current->next;
        if (newNode->next != NULL)
            newNode->next->prev = newNode;
        else
            current->next = newNode;
        if (*headRef == current)
            *headRef = newNode;
    }
}

void deleteNode(node_t** headRef, int RX_UE_INFORMATION_TAG) {
    node_t* current = *headRef;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        current = current->next;
    }
    if (current == NULL || current->prev == NULL || current->next == NULL) return; // Node not found
    if (current->prev != NULL)
        current->prev->next = current->next;
    else
        *headRef = current->next;
    if (current->next != NULL)
        current->next->prev = current->prev;
    free(current);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    int N; // Input size (10 to 100,000)
    printf("Enter the input size (10 to 100,000): ");
    scanf("%d", &N);

    node_t* head = NULL;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {
            rand() % 10000, // RX_UE_INFORMATION_TAG
            rand() % 10000, // RNTI
            rand() % 10000, // CRC_INDICATION_REL8_TAG
            rand() & 1 ? 0 : 1 // CRCFLAG (randomly set)
        };
        insertNode(&head, data);
    }

    // Traversal and processing of the list goes here...

    freeList(&head);

    return 0;
}
