#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000
#define RETRY_INTERVAL 100 // in milliseconds

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[256];
    int RNTI;
    struct NFAPI_CRC_INDICATION_REL8_TAG {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_LIST {
    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    int capacity;
} NFAPI_CRC_INDICATION_PDU_LIST;

NFAPI_CRC_INDICATION_PDU_LIST* create_list(int num_elements, int retry_interval) {
    NFAPI_CRC_INDICATION_PDU_LIST* list = (NFAPI_CRC_INDICATION_PDU_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    if (!list) {
        return NULL;
    }

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = num_elements;

    // Set up external data source
    srand(time(NULL));

    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = &list->data[i];
        // Retrieve UE tag and RNTI from external data source
        char* ue_tag = get_ue_tag();
        int rnti = get_rnti();

        if (!ue_tag || !rnti) {
            // Data retrieval failed; retry after a delay
            sleep(retry_interval / 1000.0); // convert milliseconds to seconds
            i--; // Try again with the same index
            continue;
        }

        strcpy(element->RX_UE_INFORMATION_TAG, ue_tag);
        element->RNTI = rnti;

        // Randomly set CRCFLAG for each element
        element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0xFF;

        free(ue_tag); // Free retrieved data

        if (i >= list->size) {
            // Reuse previously allocated memory when possible to optimize memory usage
            if (list->size + 1 > list->capacity) {
                int new_capacity = list->size * 2;
                NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!new_data) {
                    free(list);
                    return NULL;
                }

                list->capacity = new_capacity;
                list->data = new_data;
            }
        }

        list->size++;
    }

    return list;
}

void destroy_list(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    if (list) {
        free(list->data);
        free(list);
    }
}
