#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int ue_id;
    char nas_message[513]; // 512 characters + null-terminator
    uint32_t snti;
} LTE_NAS_Message_PDU;

typedef struct {
    LTE_NAS_Message_PDU* messages;
    size_t capacity;
    size_t size;
} LTE_NAS_Message_List;

LTE_NAS_Message_List* lte_nas_message_list_create(size_t initial_capacity) {
    LTE_NAS_Message_List* list = (LTE_NAS_Message_List*)malloc(sizeof(LTE_NAS_Message_List));
    if (!list) return NULL; // handle memory allocation failure

    list->messages = (LTE_NAS_Message_PDU*)calloc(initial_capacity, sizeof(LTE_NAS_Message_PDU));
    if (!list->messages) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;

    return list;
}

void lte_nas_message_list_delete(LTE_NAS_Message_List* list) {
    if (list) {
        for (size_t i = 0; i < list->size; ++i) {
            free(&list->messages[i]);
        }
        free(list->messages);
        free(list);
    }
}

void lte_nas_message_list_insert(LTE_NAS_Message_List* list, LTE_NAS_Message_PDU message) {
    if (list->size == list->capacity) {
        // dynamic resizing
        list->capacity *= 2;
        list->messages = (LTE_NAS_Message_PDU*)realloc(list->messages, list->capacity * sizeof(LTE_NAS_Message_PDU));
    }

    list->messages[list->size] = message;
    ++list->size;
}

void lte_nas_message_list_sort(LTE_NAS_Message_List* list, int order) {
    LTE_NAS_Message_PDU temp;
    for (size_t i = 0; i < list->size - 1; ++i) {
        for (size_t j = 0; j < list->size - i - 1; ++j) {
            if ((order == 1 && list->messages[j].ue_id > list->messages[j + 1].ue_id) ||
                (order == -1 && list->messages[j].ue_id < list->messages[j + 1].ue_id)) {
                temp = list->messages[j];
                list->messages[j] = list->messages[j + 1];
                list->messages[j + 1] = temp;
            }
        }
    }
}

int main() {
    // usage example
    LTE_NAS_Message_List* list = lte_nas_message_list_create(10);

    for (int i = 0; i < 1000; ++i) {
        LTE_NAS_Message_PDU message;
        message.ue_id = i + 1;
        strcpy(message.nas_message, "Hello");
        message.snti = rand() % (1 << 32);
        lte_nas_message_list_insert(list, message);
    }

    // sorting example
    lte_nas_message_list_sort(list, 1); // sort in ascending order

    // deletion and memory deallocation
