```python
import json

class JSONParser:
    def __init__(self):
        self.registry = {}

    def add_factory_function(self, id, factory_func):
        self.registry[id] = factory_func

    def from_json(self, json_str):
        obj = json.loads(json_str)
        return self.create_instance(obj)

    def to_json(self, instance):
        obj = vars(instance).copy()
        return json.dumps(obj)

    def create_instance(self, obj):
        id = obj['id']
        factory_func = self.registry.get(id)
        if not factory_func:
            raise ValueError(f"No factory function found for ID {id}")
        return factory_func(**obj)

class FactoryRegistry:
    registry = {}

    @classmethod
    def add_factory_function(cls, id, factory_func):
        cls.registry[id] = factory_func

    @classmethod
    def create_instance(cls, obj):
        id = obj['id']
        factory_func = cls.registry.get(id)
        if not factory_func:
            raise ValueError(f"No factory function found for ID {id}")
        return factory_func(**obj)

# Example usage:
factory_registry = FactoryRegistry()
json_parser = JSONParser()

def create_user(**kwargs):
    return User(**kwargs)

class User:
    def __init__(self, name, age):
        self.name = name
        self.age = age

factory_registry.add_factory_function('user', create_user)
instance = json_parser.from_json('{"id": "user", "name": "John", "age": 30}')
print(instance.name)  # John
```

