int validate_input(LTE_PHY_RACH_INDICATION_T* new_indication) {
    // simple validation for demonstration purposes
    if (!new_indication || new_indication->UE_ID < 0 || new_indication->PreambleIndex < 0 ||
        new_indication->TimeSlot < 0 || new_indication->Subframe < 0) {
        return -1; // invalid input
    }
    return 0;
}

int create_rach_indications(int count) {
    if (count > max_size) {
        fprintf(stderr, "Exceeding maximum size limit!\n");
        return -1; // error
    }

    for (int i = 0; i < count; i++) {
        LTE_PHY_RACH_INDICATION_T* new_indication = allocate_memory(sizeof(LTE_PHY_RACH_INDICATION_T));

        if (!new_indication) continue;

        int UE_ID = rand() % 100000;
        int PreambleIndex = rand() % 8;
        int TimeSlot = rand() % 10;
        int Subframe = rand() % 20;
        int CRC_flag = rand() % 2;

        new_indication->UE_ID = UE_ID;
        new_indication->PreambleIndex = PreambleIndex;
        new_indication->TimeSlot = TimeSlot;
        new_indication->Subframe = Subframe;
        new_indication->CRC_flag = CRC_flag;

        if (list_size >= max_size) {
            // overwrite the oldest entries in a FIFO manner
            free_memory(rach_indications);
            rach_indications = allocate_memory(sizeof(LTE_PHY_RACH_INDICATION_T) * count);
            list_size = count;
        } else {
            rach_indications[list_size++] = *new_indication;
        }
    }

    return 0; // success
}

void log_operation(char* operation, int result) {
    if (DEBUG) {
        printf("Operation '%s' resulted in %d.\n", operation, result);
    }
}

int main() {
    pthread_mutex_init(NULL, NULL); // threading support

    if (create_rach_indications(100)) return 1; // error creating list
    log_operation("List creation", 0);

    sem_destroy(&semaphore); // semaphore for concurrent access

    return 0;
}
