        *error = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        *error = -2;
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < num_pdus; i++) {
        pdus[i].rnti = rand() % 1000; // Generate random RNTI
        strcpy(pdus[i].rx_ue_information_tag, "RX UE INFORMATION TAG"); // Fill RX UE information tag with default value

        // Randomly set CRCFLAG for CRC_INDICATION_REL8_TAG
        int crcflag = rand() % 2;
        pdus[i].crc_indication_rel8_tag.crcflag = crcflag;

        if (i > 0) {
            // Handle concurrency by using a lock-free mechanism or locking critical sections
            pthread_mutex_lock(&pdus_mutex);
            pdus[i-1].next = &pdus[i];
            pthread_mutex_unlock(&pdus_mutex);
        }
    }

    return pdus;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdus, int num_pdus) {
    for (int i = 0; i < num_pdus; i++) {
        // Free each pdu and its contents
        free(pdus[i].rx_ue_information_tag);
        free(&pdus[i]);
    }
    free(pdus);
}

