typedef struct record {
    int value;
} Record;

Record* init_records(int n) {
    Record* records = (Record*)malloc(n * sizeof(Record));
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % 1000; // Set random values within range [0, 1000)
    }
    return records;
}

void init_offsets(int* offsets, int n) {
    for (int i = 0; i < n; i++) {
        offsets[i] = i * 12345; // Initialize with some offset value
    }
}

void init_keys(int* keys, int n) {
    for (int i = 0; i < n; i++) {
        keys[i] = rand() % 100; // Set random values within range [0, 100)
    }
}

typedef struct DisjointSet {
    Record** records;
    int* parent;
    int* rank;
} DisjointSet;

DisjointSet* init_disjoint_set(Record** records, int n) {
    DisjointSet* disjoint_set = (DisjointSet*)malloc(sizeof(DisjointSet));
    disjoint_set->records = records;
    disjoint_set->parent = (int*)malloc(n * sizeof(int));
    disjoint_set->rank = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        disjoint_set->parent[i] = i;
        disjoint_set->rank[i] = 0;
    }
    return disjoint_set;
}

void union_find(DisjointSet* disjoint_set, int a, int b) {
    int root_a = find(disjoint_set, a);
    int root_b = find(disjoint_set, b);

    if (root_a == root_b)
        return;

    if (disjoint_set->rank[root_a] < disjoint_set->rank[root_b]) {
        disjoint_set->parent[root_a] = root_b;
    } else if (disjoint_set->rank[root_a] > disjoint_set->rank[root_b]) {
        disjoint_set->parent[root_b] = root_a;
    } else {
        disjoint_set->parent[root_b] = root_a;
        disjoint_set->rank[root_a]++;
    }
}

int find(DisjointSet* disjoint_set, int x) {
    if (disjoint_set->parent[x] != x)
        disjoint_set->parent[x] = find(disjoint_set, disjoint_set->parent[x]);
    return disjoint_set->parent[x];
}

void print_time_taken(int start_time) {
    int end_time = clock();
    double time_taken = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("Time taken: %.3f ms\n", time_taken * 1000);
}

int main() {
    const int NUM_RECORDS = 100000;
    const int MAX_OFFSETS = 1000000;
    const int MAX_KEYS = 500000;

    int* offsets = (int*)malloc(MAX_OFFSETS * sizeof(int));
    init_offsets(offsets, MAX_OFFSETS);

    int* keys = (int*)malloc(MAX_KEYS * sizeof(int));
    init_keys(keys, MAX_KEYS);

    Record** records = (Record**)malloc(NUM_RECORDS * sizeof(Record));
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i] = init_records(1);
    }

    DisjointSet* disjoint_set = init_disjoint_set(records, NUM_RECORDS);

    int start_time = clock();

    // Perform Union-Find operations...
    for (int i = 0; i < NUM_RECORDS; i++) {
        union_find(disjoint_set, i, rand() % NUM_RECORDS);
    }

    print_time_taken(start_time);

    return 0;
}
