#define CRC_FLAG_SIZE sizeof(unsigned char) // Size of CRC flag

// Define callback function type
typedef void (*callback_func)(void *);

// Structure to represent an LTE MAC PDU
typedef struct {
    unsigned int timestamp;
    unsigned char crc_flag;
    callback_func callback;
    char mac_ie[IE_LENGTH];
} pdu_t;

// Function to create and populate a list of LTE MAC PDUs
pdu_t **create_pdu_list(int max_size, callback_func callback) {
    pdu_t **list = (pdu_t **)malloc(sizeof(pdu_t *) * max_size);
    int size = 0;

    for (int i = 0; i < max_size; i++) {
        list[i] = (pdu_t *)malloc(sizeof(pdu_t));
        list[i]->timestamp = time(NULL);
        // Set CRC flag randomly
        list[i]->crc_flag = rand() % 2;
        list[i]->callback = callback;

        // Generate MAC IE data from external data source
        // ...

        size++;
    }

    return list;
}

// Function to add a PDU to the list and overwrite if full
void add_pdu(pdu_t **list, int max_size, callback_func callback) {
    if (size >= max_size) {
        free(list[0]);
        memmove(list, list + 1, sizeof(pdu_t *) * size);
    }

    // Add new PDU to the end of the list
    list[size] = (pdu_t *)malloc(sizeof(pdu_t));
    list[size]->timestamp = time(NULL);
    // Set CRC flag randomly
    list[size]->crc_flag = rand() % 2;
    list[size]->callback = callback;

    size++;
}

// Function to flush the list and reset internal state
void flush_pdu_list(pdu_t **list, int max_size) {
    for (int i = 0; i < size; i++) {
        free(list[i]);
    }
    memset(list, 0, sizeof(pdu_t *) * max_size);
    size = 0;
}

// Example callback function
void example_callback(void *) {
    printf("Received PDU with timestamp: %d and CRC flag: %d\n", ...);
}
