data_entry** allocateArrays(int size) {
    double* doubles = (double*)malloc(size * sizeof(double));
    char* chars = (char*)malloc(size * sizeof(char));
    data_entry* entries = (data_entry*)malloc(size * sizeof(data_entry));

    for (int i = 0; i < size; i++) {
        entries[i].value = rand() % 100;
        int strLen = sprintf(buffer, "entry_%d", i) + 1;
        entries[i].str = malloc(strLen);
        strcpy(entries[i].str, buffer);
    }

    free(buffer);

    return &entries;
}

void freeArrays(data_entry** arrays) {
    for (int i = 0; i < size; i++) {
        free((double*)arrays->doubles + i * sizeof(double));
        free(arrays->chars + i * sizeof(char));
        free(&((*arrays)[i]));
    }
    free((double*)arrays->doubles);
    free(arrays->chars);
    free(*arrays);
}

int main() {
