    srand(seed);
    int list_size = 0;
    NFAPI_CRC_INDICATION_PDU_T** list = NULL;

    while (list_size < max_limit) {
        // Dynamically allocate memory for new structure
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            printf("Memory allocation failed. Terminating.\n");
            return NULL;
        }

        // Generate unique RX_UE_INFORMATION_TAG and RNTI
        pdu->RX_UE_INFORMATION_TAG = rand() % (max_limit * 2 - 1) + 1;
        pdu->RNTI = rand() % max_limit;

        // Set CRCFLAG randomly
        pdu->CRCFLAG = rand() % 2;

        // Resize the list and add the new structure
        if (!list) {
            list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * 1);
        } else {
            NFAPI_CRC_INDICATION_PDU_T** temp = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list_size + 2));
            list = temp;
        }
        list[list_size] = pdu;
        list_size++;
    }

    return list;
}
