UE_Context* create_ue_context(int ue_id, int radio_link) {
    UE_Context* context = (UE_Context*) malloc(sizeof(UE_Context));
    if (!context) return NULL;

    context->ue_id = ue_id;
    context->radio_link = radio_link;
    for (int i = 0; i < 10; i++) {
        context->report[i].signal_strength = (double) rand() / RAND_MAX;
        context->report[i].noise_level = (double) rand() / RAND_MAX;
    }

    return context;
}

void free_ue_context(UE_Context* context) {
    if (!context) return;

    free(context);
}

int create_ue_contexts(int num_contexts, sqlite3_stmt* stmt) {
    for (int i = 0; i < num_contexts; i++) {
        int ue_id = rand();
        int radio_link = rand();

        UE_Context* context = create_ue_context(ue_id, radio_link);

        if (!context) return -1;

        sqlite3_bind_int(stmt, 1, ue_id);
        sqlite3_bind_int(stmt, 2, radio_link);

        for (int j = 0; j < 10; j++) {
