            sqlite3_bind_double(stmt, 3 + i * 20, signal_strength);
            sqlite3_bind_double(stmt, 14 + i * 20, noise_level);
        }

        int rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            printf("Error inserting UE context: %s\n", sqlite3_errmsg(NULL));
            return -1;
        }

        free_ue_context(context);
    }

    return 0;
}

int main() {
    srand(time(NULL));

    sqlite3_stmt* stmt = NULL;

    int rc = sqlite3_prepare_v2(NULL, "INSERT INTO ue_contexts (ue_id, radio_link, signal_strength, noise_level) VALUES (?, ?, ?, ?)", -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing SQL statement: %s\n", sqlite3_errmsg(NULL));
        return 1;
    }

    int num_contexts = 1000;

    rc = create_ue_contexts(num_contexts, stmt);
    if (rc < 0) return 1;

    sqlite3_finalize(stmt);

    return 0;
}
