#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 1000
#define MAX_MEASUREMENT_REPORTS 10
#define DELAY 1 // seconds

typedef struct {
    int id;
    int radio_links;
} UEContext;

typedef struct {
    int timestamp;
    float signal_strength;
    float noise_level;
} MeasurementReport;

typedef struct {
    pthread_mutex_t mutex;
    int count;
    UEContext* ue_contexts;
    MeasurementReport** measurement_reports;
} LTEUEContextList;

void init_lte_ue_context_list(LTEUEContextList* list) {
    list->count = 0;
    list->ue_contexts = (UEContext*)calloc(MAX_UE_CONTEXTS, sizeof(UEContext));
    list->measurement_reports = (MeasurementReport**)calloc(MAX_MEASUREMENT_REPORTS, sizeof(MeasurementReport*));
}

void add_ue_context(LTEUEContextList* list, int id, int radio_links) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_UE_CONTEXTS) {
        printf("Error: Maximum number of UE contexts reached.\n");
        return;
    }
    list->ue_contexts[list->count].id = id;
    list->ue_contexts[list->count].radio_links = radio_links;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void add_measurement_report(LTEUEContextList* list, int ue_id, float signal_strength, float noise_level) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->ue_contexts[i].id == ue_id) {
            MeasurementReport* report = (MeasurementReport*)malloc(sizeof(MeasurementReport));
            report->timestamp = time(NULL);
            report->signal_strength = signal_strength;
            report->noise_level = noise_level;
            list->measurement_reports[list->count] = report;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_lte_ue_context_list(LTEUEContextList* list) {
    for (int i = 0; i < list->count; i++) {
        free(list->measurement_reports[i]);
    }
    free(list->ue_contexts);
    free(list->measurement_reports);
}

int main() {
    LTEUEContextList lte_ue_context_list;
    init_lte_ue_context_list(&lte_ue_context_list);

    // Add UE contexts
    add_ue_context(&lte_ue_context_list, 1, 2);
    add_ue_context(&lte_ue_context_list, 3, 4);
    sleep(DELAY); // simulate data transmission delay

    // Add measurement reports
    add_measurement_report(&lte_ue_context_list, 1, 10.5, 0.8);
    add_measurement_report(&lte_ue_context_list, 1, 11.2, 0.9);
    add_measurement_report(&lte_ue_context_list, 3, 9.7, 1.2);

    // Free the list
    free_lte_ue_context_list(&lte_ue_context_list);

    return 0;
