int main() {
    const size_t MAX_SIZE = 1000;
    int *array = NULL;
    NFAPI_CRC_INDICATION_PDU_T *nfaPis = NULL;

    // Read integers from standard input
    FILE *fp = stdin;
    char buffer[1024];
    fgets(buffer, sizeof(buffer), fp);
    size_t size = 1;
    while (fgets(buffer, sizeof(buffer), fp)) {
        char *token = strtok(buffer, " ");
        if (!token) break; // empty line or end of file
        int value = atoi(token);
        // Validate input integer
        if (value < 0 || value > 65535) continue;
        array = realloc(array, (size + 1) * sizeof(int));
        array[size++] = value;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error reading from standard input.\n");
        return 1;
    }
    fclose(fp);

    // Preallocate memory for the array of integers
    int *largest_array = malloc(MAX_SIZE * sizeof(int));
    memcpy(largest_array, array, size * sizeof(int));

    // Find and print the largest integer in the array
    find_largest_integer(largest_array, MAX_SIZE);

    // Create and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
    nfaPis = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < size; ++i) {
