    int crc_flag;
} lte_mac_pdu;

// Function to create and populate a list of LTE MAC PDU structures
lte_mac_pdu** create_and_populate_pdu_list(int num_pdus) {
    lte_mac_pdu** pdu_list = (lte_mac_pdu**)malloc((num_pdus + 1) * sizeof(lte_mac_pdu*));
    for (int i = 0; i < num_pdus; i++) {
        pdu_list[i] = (lte_mac_pdu*)malloc(sizeof(lte_mac_pdu));
        pdu_list[i]->mac_ie = rand() % 100;
        pdu_list[i]->timestamp = time(NULL);
        pdu_list[i]->crc_flag = rand() % 2;
    }
    return pdu_list;
}

