}

// Function to serialize the list of PDUs to a binary file
int serialize_pdu_list(lte_mac_pdu** pdu_list, int num_pdus, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return 0; // error opening file

    for (int i = 0; i < num_pdus; i++) {
        fwrite(&pdu_list[i]->mac_ie, sizeof(int), 1, file);
        fwrite(&pdu_list[i]->timestamp, sizeof(time_t), 1, file);
        fwrite(&pdu_list[i]->crc_flag, sizeof(int), 1, file);
    }

    fclose(file);
    return 1; // successful serialization
}

// Function to deserialize the list of PDUs from a binary file
int deserialize_pdu_list(lte_mac_pdu** pdu_list, int num_pdus, char* filename) {
