    LTE_PHY_SCH_DATA data[];
} LTE_PHY_PDU_T;

void create_and_populate_pdu(int num_pdus, LTE_PHY_PDU_T ***pdus) {
    srand(time(NULL)); // seed random number generator
    *pdus = (LTE_PHY_PDU_T **)malloc(num_pdus * sizeof(LTE_PHY_PDU_T *));
    for (int i = 0; i < num_pdus; i++) {
        (*pdus)[i] = (LTE_PHY_PDU_T *)malloc(sizeof(LTE_PHY_PDU_T) + (5 * sizeof(LTE_PHY_SCH_DATA)));
        LTE_PHY_PDU_HEADER header;
        header.crc = rand() % 65536;
        header.rlc = rand() % 256;
        header.tai = rand() % 256;
        (*pdus)[i]->header = header;
        for (int j = 0; j < 5; j++) {
            LTE_PHY_SCH_DATA data;
            for (int k = 0; k < 8; k++) {
                data.data[k] = rand() % 256;
            }
            (*pdus)[i]->data[j] = data;
        }
    }
}

void free_pdus(LTE_PHY_PDU_T **pdus, int num_pdus) {
    for (int i = 0; i < num_pdus; i++) {
        if ((*pdus)[i]) {
            free((*pdus)[i]);
        }
    }
    free(pdus);
}

