#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a record structure
typedef struct {
    int value;
} Record;

// Hash table structure using chaining with linked list
typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
} HashTable;

void init_hash_table(HashTable* table) {
    table->head = NULL;
    table->size = 0;
}

// Initialize a new hash node
Node* create_node(int key, Record* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    node->record = record;
    node->next = NULL;
    return node;
}

// Insert a new hash node
void insert_hash_node(HashTable* table, int key, Record* record) {
    Node* node = create_node(key, record);
    if (table->head == NULL || key < table->head->record->value) {
        node->next = table->head;
        table->head = node;
    } else {
        Node* current = table->head;
        while (current->next && current->next->record->value > key)
            current = current->next;
        node->next = current->next;
        current->next = node;
    }
    table->size++;
}

// Find a hash node by key
Node* find_hash_node(HashTable* table, int key) {
    Node* current = table->head;
    while (current) {
        if (key == current->record->value)
            return current;
        current = current->next;
    }
    return NULL;
}

// Free hash table memory
void free_hash_table(HashTable* table) {
    Node* current = table->head;
    Node* next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    table->head = NULL;
    table->size = 0;
}

// Function to dynamically allocate memory for and initialize arrays
void dynamic_allocation(int num_offsets, int num_keys, int range_min, int range_max) {
    srand(time(NULL)); // Initialize random number generator

    // Allocate memory for offset array
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Allocate memory for key array
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets); // Free previously allocated offset array
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Initialize offset and key arrays with external data source values (if provided)
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = ...; // Replace with your code to populate the offset array
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = ...; // Replace with your code to populate the key array
    }

    // Allocate memory for record array and initialize with random values within range
    Record* records = (Record*)malloc(num_offsets * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys); // Free previously allocated arrays
        printf("Memory allocation failed!\n");
        exit(1);
    }
    for (int i = 0; i < num_offsets; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // Initialize hash table
    HashTable hash_table;
    init_hash_table(&hash_table);

    // Map keys to record indices using hash table and linear probing for collisions
    for (int i = 0; i < num_keys; i++) {
        int key = keys[i];
        Record* record = &records[key]; // Use the provided key to find the corresponding record
        insert_hash_node(&hash_table, key, record);
    }

    // Free all allocated memory before returning
    free(offsets);
    free(keys);
    free(records);
    free_hash_table(&hash_table);
}
