int populateNfapiCrcIndicationList(int maxStructures, size_t maxMemoryUsageBytes, NFAPI_CRC_INDICATION_PDU_T **pduList) {
    size_t totalMemoryUsage = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    int pduCount = 0;

    for (int i = 0; i < maxStructures && totalMemoryUsage <= maxMemoryUsageBytes; i++) {
        pdu = realloc(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (pduCount + 1));
        if (!pdu) {
            printf("Error: Memory allocation failed.\n");
            return -1;
        }

        sprintf(pdu[pduCount].RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_%d", i);
        pdu[pduCount].RNTI = i;

        int crcFlag = rand() % 2; // Randomly set CRCFLAG
        pdu[pduCount].CRCFLAG = crcFlag;
        totalMemoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (totalMemoryUsage > maxMemoryUsageBytes) {
            printf("Warning: Total memory usage exceeded threshold.\n");
            break;
        }

        pduCount++;
    }

    *pduList = pdu;
    return pduCount;
}
