#include <time.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a doubly linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_and_populate_list(int N) {
    // Create the doubly linked list
    Node* head = NULL;
    Node* tail = NULL;

    // Initialize random number generator
    srand(time(NULL));

    // Populate the list
    for (int i = 0; i < N; i++) {
        // Dynamically allocate memory for each structure
        Node* newNode = (Node*) malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory allocation failed!\n");
            return;
        }

        // Initialize the structure with a valid RX_UE_INFORMATION_TAG and RNTI, and a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        NFAPI_CRC_INDICATION_PDU_T* newPdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newPdu) {
            printf("Memory allocation failed!\n");
            return;
        }
        newPdu->RX_UE_INFORMATION_TAG = i % 100; // Randomly set RX_UE_INFORMATION_TAG
        newPdu->RNTI = rand() % 1000; // Randomly set RNTI
        newPdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        // Set the data and next pointers for the new node
        newNode->data = newPdu;
        newNode->prev = NULL;
        newNode->next = NULL;

        // Insert the new node at the end of the list
        if (!head) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    }

    // Print the contents of the list for debugging purposes
    Node* current = head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", current->data->RX_UE_INFORMATION_TAG, current->data->RNTI, current->data->CRCFLAG);
        current = current->next;
    }

    // Perform periodic check for duplicate RNTI values in the list and remove any duplicates found
    Node* temp = head;
    while (temp) {
        Node* next = temp->next;
        while (next) {
            if (temp->data->RNTI == next->data->RNTI) {
                // Remove duplicate RNTI value from the list
                Node* prev = temp->prev;
                Node* nextNode = temp->next;
                if (prev)
                    prev->next = nextNode;
                else
                    head = nextNode;
                if (nextNode)
                    nextNode->prev = prev;
                free(temp);
                temp = next;
                break;
            }
            next = next->next;
        }
        temp = temp->next;
    }

    // Dynamically resize the doubly linked list to handle varying loads
    int resizeFactor = 2;
    while (1) {
        Node* current = head;
        while (current) {
            if (current->data->RNTI % resizeFactor == 0) {
                // Dynamically increase the size of the list
                for (int i = 0; i < N / resizeFactor; i++) {
                    // Dynamically allocate memory for each structure
                    Node* newNode = (Node*) malloc(sizeof(Node));
                    if (!newNode) {
                        printf("Memory allocation failed!\n");
                        return;
                    }

                    // Initialize the structure with a valid RX_UE_INFORMATION_TAG and RNTI, and a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
                    NFAPI_CRC_INDICATION_PDU_T* newPdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                    if (!newPdu) {
                        printf("Memory allocation failed!\n");
                        return;
                    }
                    newPdu->RX_UE_INFORMATION_TAG = i % 100; // Randomly set RX_UE_INFORMATION_TAG
                    newPdu->RNTI = rand() % 1000; // Randomly set RNTI
                    newPdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

                    // Set the data and next pointers for the new node
                    newNode->data = newPdu;
                    newNode->prev = NULL;
                    newNode->next = NULL;

                    // Insert the new node at the end of the list
                    if (!head) {
                        head = newNode;
                        tail = newNode;
                    } else {
                        tail->next = newNode;
                        newNode->prev = tail;
                        tail = newNode;
                    }
                }

                break;
            }
            current = current->next;
        }

        // Dynamically decrease the size of the list
        for (int i = 0; i < N / resizeFactor; i++) {
            Node* temp = head;
            while (temp) {
                if (temp->data->RNTI % resizeFactor == 0) {
                    Node* prev = temp->prev;
                    Node* nextNode = temp->next;
                    if (prev)
                        prev->next = nextNode;
                    else
                        head = nextNode;
                    if (nextNode)
                        nextNode->prev = prev;
                    free(temp);
                    break;
                }
                temp = temp->next;
            }
        }

        // Increment the resize factor for dynamic resizing
        resizeFactor *= 2;

        // Periodically print the contents of the list for debugging purposes
        Node* currentPrint = head;
        while (currentPrint) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", currentPrint->data->RX_UE_INFORMATION_TAG, currentPrint->data->RNTI, currentPrint->data->CRCFLAG);
            currentPrint = currentPrint->next;
        }
    }

    // Free the memory allocated for each structure
    Node* tempFree = head;
    while (tempFree) {
        Node* nextNode = tempFree->next;
        free(tempFree->data);
        free(tempFree);
        tempFree = nextNode;
    }

    return;
}

int main() {
    int N = 100000; // Adjust the size of the list as needed
    create_and_populate_list(N);

    return 0;
}
