#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createList(int n) {
    if (n <= 0) return NULL;
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) return NULL; // Memory allocation failed
    head->data.RNTI = rand();
    for (int i = 1; i < n; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) return NULL; // Memory allocation failed
        newNode->next = head;
        head = newNode;
        head->data.RNTI = rand();
    }
    return head;
}

void freeList(Node* head) {
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int n = 10; // Example list size
    Node* head = createList(n);
    // Use the created list...
    freeList(head);
    return 0;
}
