#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define UE_CONTEXT_MAX 1000
#define DATABASE_TIMEOUT 5000 // in milliseconds

typedef struct {
    int ue_id;
    int cell_id;
    int signal_strength[3]; // measurement reports for three neighboring cells
} LteUeContext;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
LteUeContext* ue_contexts = NULL;
int context_count = 0;

void add_ue_context(int ue_id, int cell_id) {
    pthread_mutex_lock(&lock);
    if (context_count >= UE_CONTEXT_MAX) {
        printf("UE context limit reached. Cannot add new context.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    LteUeContext* new_context = (LteUeContext*)malloc(sizeof(LteUeContext));
    if (!new_context) {
        printf("Memory allocation failed for UE context.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    new_context->ue_id = ue_id;
    new_context->cell_id = cell_id;
    for (int i = 0; i < 3; i++) {
        new_context->signal_strength[i] = rand() % 100 + 1;
    }

    if (!ue_contexts) {
        ue_contexts = (LteUeContext**)malloc(sizeof(LteUeContext*));
        ue_contexts[context_count++] = new_context;
    } else {
        LteUeContext** new_array = (LteUeContext**)realloc(ue_contexts, sizeof(LteUeContext*) * ++context_count);
        if (!new_array) {
            printf("Memory allocation failed for UE context array.\n");
            free(new_context);
            pthread_mutex_unlock(&lock);
            return;
        }
        new_array[context_count - 1] = new_context;
        ue_contexts = new_array;
    }

    // Store the context in the database
    sleep(DATABASE_TIMEOUT / 1000); // simulate a delay for persistence

    pthread_mutex_unlock(&lock);
}

void update_ue_context(int ue_id, int cell_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id && ue_contexts[i]->cell_id == cell_id) {
            // Update the context
            ue_contexts[i]->signal_strength[0] = rand() % 100 + 1;
            ue_contexts[i]->signal_strength[1] = rand() % 100 + 1;
            ue_contexts[i]->signal_strength[2] = rand() % 100 + 1;

            // Store the updated context in the database
            sleep(DATABASE_TIMEOUT / 1000); // simulate a delay for persistence

            pthread_mutex_unlock(&lock);
            return;
        }
    }

    printf("UE context not found for update.\n");
    pthread_mutex_unlock(&lock);
}

void remove_ue_context(int ue_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            // Remove the context
            free(ue_contexts[i]);

            LteUeContext** new_array = (LteUeContext**)realloc(ue_contexts, sizeof(LteUeContext*) * --context_count);
            if (!new_array) {
                printf("Memory allocation failed for UE context array.\n");
                pthread_mutex_unlock(&lock);
                return;
            }
            ue_contexts = new_array;
        }
    }

    // Store the removal in the database
    sleep(DATABASE_TIMEOUT / 1000); // simulate a delay for persistence

    pthread_mutex_unlock(&lock);
}

void dump_ue_contexts() {
    pthread_mutex_lock(&lock);
    printf("UE Contexts:\n");
    for (int i = 0; i < context_count; i++) {
        printf("UE ID: %d, Cell ID: %d, Signal Strength: %d %d %d\n",
               ue_contexts[i]->ue_id, ue_contexts[i]->cell_id,
               ue_contexts[i]->signal_strength[0], ue_contexts[i]->signal_strength[1],
               ue_contexts[i]->signal_strength[2]);
    }
    pthread_mutex_unlock(&lock);
}

