void lte_ue_context_add(LteUeContext** list, size_t capacity) {
    if (*list == NULL || capacity <= *list->size) {
        *list = (LteUeContext**) realloc(*list, sizeof(LteUeContext*) * (capacity + 1));
    }
}

void lte_ue_context_remove(LteUeContext** list, size_t index) {
    if (*list && index < *list->size) {
        memmove(&((*list)[index]), &((*list)[index+1]), sizeof(LteUeContext*) * ((*list).size - (index + 1)));
        (*list)->size--;
    }
}

