#define MAX_STRUCTURE_COUNT 50000
#define NAS_PDU_MAX_LENGTH 256

typedef struct {
    char IMSI[15];
    char S_TMSI[16];
    unsigned char NAS_PDU[NAS_PDU_MAX_LENGTH];
    size_t NAS_PDU_len;
} LTE_NAS_MESSAGE;

// Initialize list and current structure index
static LTE_NAS_MESSAGE* lte_nas_message_list = NULL;
static int current_structure_index = 0;

void create_and_populate_lte_nas_message_list() {
    // Check if the maximum capacity is reached
    if (current_structure_index >= MAX_STRUCTURE_COUNT) {
        printf("Maximum structure count reached. Aborting.\n");
        return;
    }

    LTE_NAS_MESSAGE* new_structure = NULL;
    int random_pdu_length = rand() % NAS_PDU_MAX_LENGTH;

    // Allocate memory for the new structure
    while ((new_structure = (LTE_NAS_MESSAGE*)malloc(sizeof(LTE_NAS_MESSAGE))) == NULL) {
        printf("Error allocating memory. Retrying...\n");
        usleep(1000); // Wait 1ms before retrying
    }

    // Initialize IMSI and S-TMSI randomly
    for (int i = 0; i < 15; i++) {
        new_structure->IMSI[i] = 'X' + rand() % 10;
    }
    for (int i = 0; i < 16; i++) {
        new_structure->S_TMSI[i] = ('A' + rand() % 26) | ((rand() % 2) << 5);
    }

    // Initialize NAS PDU with random length
    for (size_t i = 0; i < random_pdu_length; i++) {
        new_structure->NAS_PDU[i] = rand() % 256;
    }
    new_structure->NAS_PDU_len = random_pdu_length;

    printf("Attempting to add structure %d...\n", current_structure_index);
    if (lte_nas_message_list == NULL) {
        lte_nas_message_list = new_structure;
    } else {
        LTE_NAS_MESSAGE** temp = &lte_nas_message_list;
        while (*temp != NULL && *temp < &new_structure) {
            temp = &(*temp)->NAS_PDU_len;
        }
        *temp = &new_structure->NAS_PDU_len;
    }

    printf("Structure %d added successfully.\n\n", current_structure_index);

    // Increment the current structure index
    current_structure_index++;

    free(new_structure);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < MAX_STRUCTURE_COUNT; i++) {
        create_and_populate_lte_nas_message_list();
    }

    return 0;
}
