void add_ue_transmission_status(UE_Transmission_Status** list, int* size, UE_Transmission_Status* new_entry) {
    if (*size == 0) {
        // dynamically allocate more memory
        *size = *size + initial_size;
        list = (UE_Transmission_Status**)realloc(list, *size * sizeof(UE_Transmission_Status*));

        // check for memory allocation failure
        if (!list) {
            return; // error handling
        }
    }

    // add the new entry to the list
    list[*size - 1] = new_entry;
    (*size)++;
}

void free_ue_transmission_status_list(UE_Transmission_Status** list, int size) {
    for (int i = 0; i < size; i++) {
        free(list[i]);
    }

