int nfaPiCreateList(NFAPI_LIST** list) {
    *list = (NFAPI_LIST*)malloc(sizeof(NFAPI_LIST));
    if (*list == NULL) {
        return -1; // Memory allocation failure
    }

    (*list)->size = 0;
    (*list)->capacity = 10; // Initial capacity
    pthread_mutex_init(&((*list)->lock), NULL);

    return 0;
}

int nfaPiAddEntry(NFAPI_LIST* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->size >= list->capacity) {
        int newCapacity = list->capacity * 2;

        // Resize the list while preserving existing entries
        NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newData == NULL) {
            return -2; // Memory allocation failure during resize
        }

        list->capacity = newCapacity;
        list->data = newData;
    }

    pthread_mutex_lock(&list->lock);

    // Validate the CRCINDICATION_REL8_TAG before adding it to the list
    if (!validateCRCFLAG(entry.CRCFLAG)) {
        return -3; // Validation error
    }

    list->data[list->size] = entry;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

