int list_size = 0;
int list_max_size = 1000; // max size for the list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* error_log_file = NULL;

// Function to initialize and populate the UE transmission status list
UE_Transmission_Status* ue_transmission_status_list_init() {
    ue_transmission_status_list = (UE_Transmission_Status*)malloc(list_max_size * sizeof(UE_Transmission_Status));
    if (ue_transmission_status_list == NULL) {
        fprintf(stderr, "Failed to allocate memory for UE transmission status list\n");
        return NULL;
    }
    memset(ue_transmission_status_list, 0, list_max_size * sizeof(UE_Transmission_Status));
    return ue_transmission_status_list;
}

// Function to add a new entry to the UE transmission status list
int ue_transmission_status_list_add(int UE_ID, int Transmission_Time_Interval_ID, char* Transmission_Type) {
    pthread_mutex_lock(&mutex);

    if (list_size >= list_max_size) {
        // List is full, need to resize it
        UE_Transmission_Status* new_list = (UE_Transmission_Status*)realloc(ue_transmission_status_list, (list_max_size * 2 + 1) * sizeof(UE_Transmission_Status));
        if (new_list == NULL) {
            fprintf(stderr, "Failed to allocate memory for resized UE transmission status list\n");
            pthread_mutex_unlock(&mutex);
            return -1;
        }
        ue_transmission_status_list = new_list;
        list_max_size *= 2;
    }

    UE_Transmission_Status* new_entry = &ue_transmission_status_list[list_size];
    new_entry->UE_ID = UE_ID;
    new_entry->Transmission_Time_Interval_ID = Transmission_Time_Interval_ID;
    strcpy(new_entry->Transmission_Type, Transmission_Type);
    list_size++;

    pthread_mutex_unlock(&mutex);

    return 0;
}

// Function to free the dynamically allocated memory for the UE transmission status list
void ue_transmission_status_list_free() {
    if (ue_transmission_status_list != NULL) {
        free(ue_transmission_status_list);
        ue_transmission_status_list = NULL;
    }
}
