LTE_ue_ctx** create_ue_contexts(int num_ues) {
    // Calculate the required memory for each UE context
    size_t ue_ctx_size = sizeof(LTE_ue_ctx);
    size_t total_ue_ctx_size = ue_ctx_size * num_ues;

    // Allocate memory for the UE context list
    LTE_ue_ctx** ue_ctx_list = (LTE_ue_ctx**)malloc(total_ue_ctx_size);

    if (!ue_ctx_list) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Populate each UE context with random values and statistics
    for (int i = 0; i < num_ues; i++) {
        LTE_ue_ctx* ue_ctx = (LTE_ue_ctx*)malloc(ue_ctx_size);

        if (!ue_ctx) {
            printf("Memory allocation failed!\n");
            return NULL;
        }

        // Initialize UE context with random values and statistics
        ue_ctx->ue_id = rand();
        ue_ctx->mac_stat = rand() % 100 - 50;
        ue_ctx->phy_stat = rand() % 100 - 50;
        ue_ctx->dl_harq_status = (rand() % 2) ? 0 : 1;

        // Add UE context to the list
        ue_ctx_list[i] = ue_ctx;
    }

    return ue_ctx_list;
}

// Function to update UE statistics in a thread-safe manner
void update_ue_statistics(LTE_ue_ctx* ue_ctx, int16_t new_mac_stat, int16_t new_phy_stat) {
    pthread_mutex_lock();
    ue_ctx->mac_stat = new_mac_stat;
    ue_ctx->phy_stat = new_phy_stat;
    pthread_mutex_unlock();
}

// Function to free memory for each UE context
void free_ue_contexts(LTE_ue_ctx** ue_ctx_list, int num_ues) {
    for (int i = 0; i < num_ues; i++) {
        if (ue_ctx_list[i]) {
            free(ue_ctx_list[i]);
        }
    }

    // Free memory for the UE context list
    free(ue_ctx_list);
}
