#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    // MAC statistics
    int mac_stat_rx_packets;
    int mac_stat_tx_packets;
    // PHY statistics
    int phy_stat_rx_bytes;
    int phy_stat_tx_bytes;
    // DL HARQ process status
    int dl_harq_success;
    int dl_harq_failure;
} LTE_ue_context;

typedef struct {
    LTE_ue_context* context;
    struct list_node* next;
    struct list_node* prev;
} list_node;

void initialize_ue_contexts(int max_num_contexts, int* total_bytes_allocated) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    list_node* head = NULL;
    list_node* tail = NULL;
    int num_allocations = 0;

    while (num_allocations < max_num_contexts) {
        LTE_ue_context* new_ue_ctx = malloc(sizeof(LTE_ue_context));
        if (!new_ue_ctx) {
            printf("Memory allocation failed!\n");
            break;
        }

        // Initialize UE context fields with random values
        new_ue_ctx->ue_id = rand();
        new_ue_ctx->mac_stat_rx_packets = rand();
        new_ue_ctx->mac_stat_tx_packets = rand();
        new_ue_ctx->phy_stat_rx_bytes = rand();
        new_ue_ctx->phy_stat_tx_bytes = rand();
        new_ue_ctx->dl_harq_success = (rand() % 2);
        new_ue_ctx->dl_harq_failure = (rand() % 2);

        pthread_mutex_lock(&lock);
        list_node* new_node = malloc(sizeof(list_node));
        if (!new_node) {
            printf("Memory allocation failed!\n");
            free(new_ue_ctx);
            break;
        }

        new_node->context = new_ue_ctx;
        new_node->next = NULL;
        new_node->prev = tail;

        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }

        pthread_mutex_unlock(&lock);
        num_allocations++;
        *total_bytes_allocated += sizeof(LTE_ue_context) + sizeof(list_node);
    }

    if (head == NULL) {
        printf("No UE contexts created!\n");
    } else {
        printf("UE context list created with %d elements.\n", max_num_contexts);
    }
}
