    // Initialize the list with a default capacity
    int capacity = 4;
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * capacity);

    if (!list) {
        *error = ENOMEM; // Set the error code for out-of-memory
        return NULL;
    }

    // Initialize a mutex for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Create and populate NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

