        // Set RX_UE_INFORMATION_TAG and RNTI
        pdu->rxUeInformationTag = 0x12345678; 
        pdu->rnti = i;

        // Set CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        srand(time(NULL));
        int crcFlag = rand() % 2;
        pdu->crcIndicationRel8Tag.crcFlag = crcFlag;

        // Add the structure to the list
        pthread_mutex_lock(&lock);
        if (i >= capacity) {
            capacity *= 2; // Dynamically resize the list when necessary
            void* temp = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * capacity);
            if (!temp) {
                *error = ENOMEM;
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            list = (NFAPI_CRC_INDICATION_PDU_T**)temp;
        }
        list[i] = pdu;
        pthread_mutex_unlock(&lock);
    }

    // Provide a mechanism to free the allocated memory
    void freeList(NFAPI_CRC_INDICATION_PDU_T** list, int n) {
        for (int i = 0; i < n; i++) {
            if (list[i]) {
                free(list[i]);
                list[i] = NULL;
            }
        }
        free(list);
    }

