    // Populate the list with valid UE_ID and cell_ID, and statistics for uplink and downlink traffic
    for (int i = 0; i < num_sessions; i++) {
        session_stats[i].UE_ID = rand() % 65535 + 1;  // Validate UE_ID within range (1 to 65535)
        session_stats[i].cell_ID = rand();
        session_stats[i].uplink_traffic_bytes = rand();
        session_stats[i].downlink_traffic_bytes = rand();
    }

    return (int*)session_stats;
}

// Function to integrate with an external data source for real-time traffic statistics updates
void update_session_stats_list(LTE_UESessionStats* session_stats, int num_sessions) {
    // Simulate retrieving real-time traffic statistics from the external data source
    for (int i = 0; i < num_sessions; i++) {
        session_stats[i].uplink_traffic_bytes += rand();
        session_stats[i].downlink_traffic_bytes += rand();
    }
}

// Function to handle concurrency and ensure thread-safety
void* create_and_update_session_stats_thread(void* arg) {
    int* session_stats_list = (int*)arg;
    LTE_UESessionStats* session_stats = (LTE_UESessionStats*)malloc(1 * sizeof(LTE_UESessionStats));

    // Simulate concurrent access to the list and update statistics
    for (int i = 0; i < *session_stats_list; i++) {
        if (i % 2 == 0) {
            session_stats->UE_ID = rand() % 65535 + 1;
            session_stats->cell_ID = rand();
        } else {
            // Simulate concurrent access and update statistics
            session_stats->uplink_traffic_bytes += rand();
            session_stats->downlink_traffic_bytes += rand();
        }
    }

    free(session_stats);
    return NULL;
}

int main() {
    int num_sessions = 10;  // Number of sessions to create

    int* session_stats_list = create_and_populate_session_stats_list(num_sessions);

    if (session_stats_list == NULL) {
        printf("Error creating and populating the session stats list\n");
        return -1;
    }

    // Simulate concurrent access to the list
    pthread_t threads[num_sessions];
    for (int i = 0; i < num_sessions; i++) {
        int* arg = &session_stats_list[i * sizeof(LTE_UESessionStats)];
        pthread_create(&threads[i], NULL, create_and_update_session_stats_thread, arg);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_sessions; i++) {
        pthread_join(threads[i], NULL);
    }

    free(session_stats_list);
    return 0;
}

