    LTE_ue_context_t** contexts = (LTE_ue_context_t**)malloc(numContexts * sizeof(LTE_ue_context_t*));
    if (!contexts) {
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < numContexts; i++) {
        contexts[i] = (LTE_ue_context_t*)malloc(sizeof(LTE_ue_context_t));
        if (!contexts[i]) {
            free(contexts);
            return NULL;
        }

        contexts[i]->mac_ce = rand() % 256;
        contexts[i]->rnti = rand() % 65536;
        contexts[i]->crc_flag = (rand() % 2) ? 1 : 0;

        if (loggingEnabled) {
            pthread_mutex_lock(&mutex);
            printf("UE Context %d: MAC-CE=%d, RNTI=%d, CRC Flag=%s\n", i, contexts[i]->mac_ce, contexts[i]->rnti, contexts[i]->crc_flag ? "True" : "False");
            pthread_mutex_unlock(&mutex);
        }
    }

    return contexts;
}

void freeUEContexts(LTE_ue_context_t** contexts, int numContexts) {
    for (int i = 0; i < numContexts; i++) {
        free(contexts[i]);
    }
    free(contexts);
}
