#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createList(int n) {
    Node* head = NULL;
    for (int i = 0; i < n; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 1000;
        data.RNTI = rand() % 10000;
        data.CRC_INDICATION_REL8_TAG = rand() % 10000;
        data.CRCFLAG = rand() % 2;

        if (fprintf=fopen("log.txt", "a+")) {
            fprintf(fopen, "RNTI: %d CRCFLAG: %d\n", data.RNTI, data.CRCFLAG);
            fclose(fopen);
        }

        newNode->data = data;
        newNode->next = head;
        head = newNode;
    }
    return head;
}

void freeList(Node* head) {
    Node* curr = head;
    while (curr != NULL) {
        Node* next = curr->next;
        free(curr);
        curr = next;
    }
}
