#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure definition
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[1];
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int* generateNFAPIList(int numElements, char* logFile) {
    // Check for invalid input size
    if (numElements <= 0) {
        return NULL;
    }

    // Initialize array-based list with sufficient capacity
    int* nfaPiList = (int*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaPiList) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    // Populate each structure in the list
    for (int i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* nfaPiElement = &nfaPiList[i];

        // Generate valid RX_UE_INFORMATION_TAG and RNTI values
        nfaPiElement->RX_UE_INFORMATION_TAG = rand() % 65536;
        nfaPiElement->RNTI = rand() % 0x10000;

        // Validate RNTI value to ensure it falls within the valid range
        if (nfaPiElement->RNTI < 1 || nfaPiElement->RNTI > 0xFFFF) {
            fprintf(stderr, "Error: Invalid RNTI value (%d).\n", nfaPiElement->RNTI);
            return NULL;
        }

        // Set CRCFLAG randomly
        nfaPiElement->CRC_INDICATION_REL8_TAG[0] = rand() % 2;

        // Log any errors or warnings to the specified log file
        if (logFile) {
            FILE* log = fopen(logFile, "a");
            if (!log) {
                fprintf(stderr, "Error: Failed to open log file.\n");
                return NULL;
            }
            fprintf(log, "Generated NFAPI structure with RX_UE_INFORMATION_TAG=%d and RNTI=%d.\n", nfaPiElement->RX_UE_INFORMATION_TAG, nfaPiElement->RNTI);
            fclose(log);
        }
    }

    // Free any allocated memory
    free(nfaPiList);

    return NULL; // Indicate successful completion
}

// Example usage:
int main() {
    int numElements = 10;
    char logFile[] = "nfaPiLog.txt";
    generateNFAPIList(numElements, logFile);
    return 0;
}
