pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile = stdout;
bool usePreAllocatedPool = false;
size_t preAllocatedPoolSize = 0;

void initNFAPI CRC Indication PDU T List() {
    nfaPiCrcIndicationPduTList = NULL;
}

int populateNFAPI_CRC_Indication_PDU_T_List(int N, FILE* logFile) {
    if (usePreAllocatedPool && preAllocatedPoolSize < N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Insufficient pre-allocated memory
    }

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pNFAPI CRC Indication PDU T;

        if (!usePreAllocatedPool) {
            pNFAPI CRC Indication PDU T = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pNFAPI CRC Indication PDU T == NULL) {
                return -1; // Memory allocation failed
            }
        } else {
            if (preAllocatedPoolSize < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
                preAllocatedPoolSize -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
                pNFAPI CRC Indication PDU T = (NFAPI_CRC_INDICATION_PDU_T*)malloc(preAllocatedPoolSize);
            } else {
                return -1; // Insufficient pre-allocated memory
            }
        }

        // Initialize the structure
        pNFAPI CRC Indication PDU T->rnti = i;
        pNFAPI CRC Indication PDU T->crcflag = rand() % 2 ? '0' : '1';

        if (!usePreAllocatedPool) {
            pthread_mutex_lock(&lock);
            NFAPI_CRC_INDICATION_PDU_T* oldList = nfaPiCrcIndicationPduTList;
            nfaPiCrcIndicationPduTList = (NFAPI_CRC_INDICATION_PDU_T*)realloc(oldList, (nfaPiCrcIndiationPduTListSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            free(oldList);
            pthread_mutex_unlock(&lock);
        } else {
            if (i == N - 1) {
                preAllocatedPoolSize -= sizeof(NFAPI CRC Indication PDU T);
            }
        }
    }

    return 0;
}

int trackAndLogMemoryUsage() {
    size_t totalMemoryUsed = 0;
    for (int i = 0; i < nfaPiCrcIndicationPduTListSize; i++) {
        totalMemoryUsed += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Write log entry
    fprintf(logFile, "Total memory used: %zu bytes\n", totalMemoryUsed);
    return 0;
}

void freeNFAPI_CRC_Indication_PDU_T_List() {
    for (int i = 0; i < nfaPiCrcIndicationPduTListSize; i++) {
        free(&nfaPiCrcIndicationPduTList[i]);
    }

    free(nfaPiCrcIndicationPduTList);
}

