#include <stdlib.h>
#include <stdio.h>

typedef struct {
    char* element;
    void (*test_func)(char*, void*);
} Element;

void traverse_DOM_tree(char* root, char* selector, void (*test_func)(char*, void*)) {
    Element* elements = NULL;
    int count = 0;
    traverse_elements(root, selector, &elements, &count, test_func);
}

int traverse_elements(char* current, char* selector, Element** elements, int* count, void (*test_func)(char*, void*)) {
    if (*current == '\0') {
        return 1;
    }
    if (strcmp(current, selector) == 0) {
        *elements = realloc(*elements, (*count + 1) * sizeof(Element));
        (*elements)[*count].element = strdup(current);
        (*elements)[*count].test_func = test_func;
        (*count)++;
    }
    int found = traverse_elements(strchr(current, '>'), selector, elements, count, test_func);
    if (found == 0) {
        free((*elements)[(*count - 1)].element);
        (*elements) = realloc(*elements, (*count - 1) * sizeof(Element));
        (*count)--;
    }
    return found;
}
