void async_reduce(int* arr, int initial_value, void (*callback)(int, int)) {
    if (!arr) return;
    int result = initial_value;
    for (int i = 0; i < *(__size_t*)arr; i++) {
        callback(result, *(arr + i));
        result += *(arr + i);
    }
}

