typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    enum { CRCFLAG_OFF, CRCFLAG_ON } CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int numElements = 0;
NFAPI_CRC_INDICATION_PDU_T *nfaPiList = NULL;

void addElement(NFAPI_CRC_INDICATION_PDU_T* elem) {
    if (numElements >= MAX_ELEMS) {
        printf("List is full. Cannot add more elements.\n");
        return;
    }

    nfaPiList[numElements] = *elem;
    numElements++;
}

int searchRNTI(int rnti) {
    for (int i = 0; i < numElements; i++) {
        if (nfaPiList[i].RNTI == rnti) {
            return i;
        }
    }
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* getRandomElement() {
    NFAPI_CRC_INDICATION_PDU_T *elem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    elem->RX_UE_INFORMATION_TAG = rand() % 1000;
    int rnti = rand() % 1000;
    while (searchRNTI(rnti) != -1) {
        rnti = rand() % 1000;
    }
    elem->RNTI = rnti;
    if (rand() % 2 == 0) {
        elem->CRCFLAG = CRCFLAG_ON;
    } else {
        elem->CRCFLAG = CRCFLAG_OFF;
    }

    return elem;
}

void freeList() {
    for (int i = 0; i < numElements; i++) {
        free(&nfaPiList[i]);
    }
    free(nfaPiList);
}

int main() {
    srand(time(NULL));

    nfaPiList = malloc(MAX_ELEMS * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < 100; i++) {
        addElement(getRandomElement());
    }

    freeList();

    return 0;
}
