        if ((list = realloc(list, (current_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*) + sizeof(int))) == NULL || (rnti_values = realloc(rnti_values, current_size * sizeof(int) + (max_size - current_size) * sizeof(int))) == NULL) {
            *error_code = 1; // Out of memory
            return 1;
