        }

        list[current_size] = pdu;
        rnti_values[current_size] = rnti;

        current_size++;
    }

    free(list);
    free(rnti_values);

    if (current_size >= max_size) {
        *error_code = 3; // Maximum size reached
        return 1;
    } else {
        return 0;
    }
}

int is_valid_rnti(int rnti, int* rnti_values, size_t current_size) {
