int populate_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, uint32_t n_rnti, uint32_t num_pdus) {
    int error = 0;
    *list = NULL;
    for (uint32_t i = 0; i < n_rnti && !error; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            error = 1;
            break;
        }
        pdu->RX_UE_INFORMATION_TAG = i % RAND_MAX;
        for (uint32_t j = 0; j < num_pdus; j++) {
            pdu->RNTI = (i * num_pdus + j) % (RAND_MAX - 1);
            if (pdu->RNTI > RAND_MAX / 2) {
                error = 1;
                break;
            }
        }
        pdu->CRC_INDICATION_REL8_TAG = i % 256;
        srand((unsigned int)i);
        pdu->CRCFLAG = rand() % 2;
        NFAPI_CRC_INDICATION_PDU_T **p_list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (i + 1));
        if (!p_list) {
            error = 1;
            free(pdu);
            break;
        }
        *p_list = pdu;
        *list = p_list;
    }
    for (uint32_t i = 0; i < n_rnti && !error; i++) {
        NFAPI_CRC_INDICATION_PDU_T **p = &(*list)[i];
        if (*p) {
            free(*p);
            *p = NULL;
        }
    }
    return error;
