// Define the structure to hold LTE PHY Layer Measurement data
typedef struct {
    char ue_identity[17]; // e.g., IMSI
    time_t measurement_time; // in seconds since the epoch
    double rssi; // Received Signal Strength Indication
    double sinr; // Signal-to-Noise Ratio
} phy_layer_measurement;

// Define a node structure to hold measurement data and pointers for dynamic resizing
typedef struct {
    phy_layer_measurement measurement;
    struct node* next;
} node;

// Initialize the measurement list with a specified capacity
node** init_measurement_list(int initial_capacity) {
    node** measurements = (node**)malloc(initial_capacity * sizeof(node));
    for (int i = 0; i < initial_capacity; i++) {
        measurements[i] = NULL;
    }
    return measurements;
}

// Add a new measurement to the list, handling dynamic resizing if necessary
void add_measurement(node** measurements, phy_layer_measurement* measurement) {
    int capacity = 10; // Initial capacity for the list
    node** temp_measurements = (node**)malloc((capacity + 1) * sizeof(node));
    for (int i = 0; i < capacity; i++) {
        if (i < capacity / 2) { // Copy existing measurements to new array
            temp_measurements[i] = measurements[i];
        } else { // Set the rest of the new array to NULL
            temp_measurements[i] = NULL;
        }
    }

    // Find the correct position for the new measurement
    int i = 0;
    while (i < capacity && measurements[i]) {
        i++;
    }

    // Add the new measurement and update the pointer
    measurements[i] = (node*)malloc(sizeof(node));
    measurements[i]->measurement = *measurement;
    measurements[i]->next = NULL;

    // Update the original array with a pointer to the new measurement
    for (int j = 0; j < capacity - 1; j++) {
        temp_measurements[j + 1] = temp_measurements[j];
    }
    temp_measurements[0] = measurements[i];

    // Free the old array and update the original list
    free(measurements);
    measurements = temp_measurements;
}

// Retrieve a measurement from the list by UE Identity (thread-safe)
phy_layer_measurement* get_measurement(node** measurements, char ue_identity[]) {
    pthread_mutex_lock(&mutex);

    node* current = *measurements;
    while (current) {
        if (strcmp(current->measurement.ue_identity, ue_identity) == 0) {
            phy_layer_measurement* measurement = &current->measurement;
            pthread_mutex_unlock(&mutex);
            return measurement;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
    return NULL; // Measurement not found
}

// Example usage:
int main() {
    node** measurements = init_measurement_list(10);

    phy_layer_measurement measurement1 = {"IMSI123", time(NULL), 5.0, 3.2};
    add_measurement(measurements, &measurement1);

    phy_layer_measurement* measurement = get_measurement(measurements, "IMSI123");
    printf("RSSI: %f\n", measurement->rssi);

    return 0;
}
