// Function to create and populate a list of LTE MAC PDUs
lte_mac_pdu** create_lte_mac_pdus(const char* csv_file, int num_pdus) {
    // Initialize the number of UEs loaded from CSV file to 0
    int ue_count = 0;
    // Initialize an array to store the loaded UE IDs
    uint32_t* ue_ids = NULL;

    // Load UE IDs from CSV file in chunks
    FILE* csv_file_ptr = fopen(csv_file, "r");
    if (csv_file_ptr == NULL) {
        return NULL; // Error handling for file opening failure
    }

    char line[1024];
    while (fgets(line, 1024, csv_file_ptr)) {
        ue_count++;
        uint32_t ue_id;
        sscanf(line, "%lu", &ue_id);
        if (ue_ids == NULL) {
            ue_ids = (uint32_t*)malloc((ue_count + 1) * sizeof(uint32_t));
            if (ue_ids == NULL) {
                fclose(csv_file_ptr);
                return NULL; // Error handling for memory allocation failure
            }
        }
        ue_ids[ue_count - 1] = ue_id;
    }

    fclose(csv_file_ptr);

    // Create and populate a list of LTE MAC PDUs
    lte_mac_pdu** pdus = (lte_mac_pdu**)malloc((num_pdus + 1) * sizeof(lte_mac_pdu*));
    if (pdus == NULL) {
        free(ue_ids);
        return NULL; // Error handling for memory allocation failure
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < num_pdus; i++) {
        pdus[i] = (lte_mac_pdu*)malloc(sizeof(lte_mac_pdu));
        if (pdus[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free(pdus[j]);
            }
            free(ue_ids);
            free(pdus);
            return NULL; // Error handling for memory allocation failure
        }

        pdus[i]->mac_ie = 1; // Set MAC IE to a valid value (e.g., RRC Connection Request)
        if (ue_count > 0) {
            pdus[i]->ue_id = ue_ids[rand() % ue_count];
        } else {
            pdus[i]->ue_id = rand(); // Generate random UE ID
        }
    }

    pdus[num_pdus] = NULL; // Terminate the list of PDUs

    free(ue_ids);

    return pdus;
}
