void create_populate_nfaapi_crc_indication_pdu_list(int n, NFAPI_CRC_INDICATION_PDU_T **list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        perror("Memory allocation failed");
        return;
    }

    int ue_info_fd, crc_flag_fd;

    // Initialize UE information and CRC flags from external sources
    if ((ue_info_fd = open("/path/to/ue_info", O_RDONLY)) < 0) {
        perror("Failed to open UE information file");
        free(*list);
        *list = NULL;
        return;
    }

    if ((crc_flag_fd = open("/path/to/crc_flags", O_RDONLY)) < 0) {
        perror("Failed to open CRC flags file");
        close(ue_info_fd);
        free(*list);
        *list = NULL;
        return;
    }

    // Read UE information and CRC flags from files
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        read(ue_info_fd, &pdu.RX_UE_INFORMATION_TAG, sizeof(int));
        read(ue_info_fd, &pdu.RNTI, sizeof(int));

        // Randomly set CRCFLAG
        int crc_flag = rand() % 2;

        // Populate CRC_INDICATION_REL8_TAG with CRC flag and RNTI
        pdu.CRC_INDICATION_REL8_TAG = crc_flag | (pdu.RNTI << 1);

        (*list)[i] = pdu;
    }

    close(ue_info_fd);
    close(crc_flag_fd);
}
