void parse_png_file(char* file_path, char** theme_cache) {
    // Open the PNG file
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        printf("Failed to open PNG file.\n");
        return;
    }

    // Read the PNG file and store it in the theme cache
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    char* file_data = malloc(file_size + 1);
    fread(file_data, 1, file_size, file);
    fclose(file);

    // Add to the theme cache
    *theme_cache = file_data;
}

