#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[2];
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void* createNFAPIList(int n, int* size) {
    // Initialize the list with a initial capacity of 10
    void** list = (void*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    // Create and populate each structure in the list
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* item = &((NFAPI_CRC_INDICATION_PDU_T*)list)[i];
        item->RX_UE_INFORMATION_TAG = rand() % 100;
        item->RNTI = rand() % 100;
        item->CRC_INDICATION_REL8_TAG[0] = (char)(rand() % 2);
        item->CRC_INDICATION_REL8_TAG[1] = (char)(rand() % 2);
    }

    *size = n;
    return list;
}

// Function to dynamically resize the list
void* resizeNFAPIList(void** list, int oldSize, int newSize) {
    void** newList = (void*)realloc(list, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newList) return NULL;

    // Copy data from old list to new list
    for (int i = 0; i < oldSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T* item = &((NFAPI_CRC_INDICATION_PDU_T*)list)[i];
        item = &((NFAPI_CRC_INDICATION_PDU_T*)newList)[i];
    }

    // Update size and return new list
    free(list);
    *oldSize = newSize;
    return newList;
}

// Function to validate input parameters
int validateInput(int n) {
    if (n <= 0 || n > 100000) {
        printf("Invalid input parameter\n");
        return -1;
    }
    return 0;
}

// Function to manage memory allocation and deallocation
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Failed to allocate memory\n");
        return NULL;
    }
    return ptr;
}

void freeMemory(void* ptr) {
    free(ptr);
}

// Function to dynamically resize the list while managing memory efficiently
void* nfaPiListDynamicResize(int n, int* size) {
    // Validate input parameters
    if (validateInput(n)) return NULL;

    // Initialize the initial capacity of the list
    void** list = (void*)allocateMemory(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;
    *size = n;

    // Dynamically resize the list as needed
    while (n > 100000) {
        int newSize = n / 2;
        void** newList = (void*)resizeNFAPIList(list, n, newSize);
        freeMemory(list);
        list = newList;
        n = newSize;
    }

    return list;
}

int main() {
    // Example usage
    int size;
    NFAPI_CRC_INDICATION_PDU_T* list = nfaPiListDynamicResize(1000, &size);

    if (list) {
        printf("Created a list of size %d\n", size);
        for (int i = 0; i < size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* item = &((NFAPI_CRC_INDICATION_PDU_T*)list)[i];
            printf("%d, %d, {%c, %c}\n", item->RX_UE_INFORMATION_TAG, item->RNTI, item->CRC_INDICATION_REL8_TAG[0], item->CRC_INDICATION_REL8_TAG[1]);
        }
    } else {
        printf("Failed to create the list\n");
    }

    return 0;
}
