void* operator new(size_t size) {
    return calloc(1, size);
}

void operator delete(void* ptr) {
    free(ptr);
}

// Function to create and populate a list of LTE UE Context structures
LTE_Ue_Context** create_ue_list(int num_ues) {
    LTE_Ue_Context** ue_list = (LTE_Ue_Context**)malloc(sizeof(LTE_Ue_Context*) * num_ues);
    for (int i = 0; i < num_ues; i++) {
        LTE_Ue_Context* ue_context = new LTE_Ue_Context();
        ue_context->ue_id = i;
        ue_context->rrc_state = rand() % 2; // Random RRC State
        ue_context->pucch_index = rand() % 10; // Random PUCCH Resource Index
        ue_list[i] = ue_context;
    }
    return ue_list;
}

int main() {
    srand(time(NULL));
    int num_ues = UE_MAX;
    LTE_Ue_Context** ue_list = create_ue_list(num_ues);

    for (int i = 0; i < num_ues; i++) {
        printf("UE %d: RRC State - %d, PUCCH Index - %d\n", 
               ue_list[i]->ue_id, ue_list[i]->rrc_state, ue_list[i]->pucch_index);
    }

    for (int i = 0; i < num_ues; i++) {
        delete ue_list[i];
    }
    free(ue_list);

    return 0;
}
