#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024*1024
#define CRC_ERROR_THRESHOLD 0.1f

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[20];
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indication_pdus(int num_sdus, int max_buffer_size, double crc_error_threshold) {
    pthread_mutex_t pdus_mutex = PTHREAD_MUTEX_INITIALIZER;
    FILE *ue_info_file;
    FILE *crc_ind_file;
    int crc_errors = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_sdus * sizeof(NFAPI_CRC_INDATION_PDU_T));
    if (!pdus) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Populate pdus array
    pthread_mutex_lock(&pdus_mutex);
    for (int i = 0; i < num_sdus; i++) {
        sprintf(pdus[i].RX_UE_INFORMATION_TAG, "RX UE Information Tag %d", i);
        pdus[i].RNTI = i;

        // Get CRC indication from file
        ue_info_file = fopen("ue_info.txt", "r");
        fseek(ue_info_file, (i * 1024), SEEK_SET);
        fread(&pdus[i].RX_UE_INFORMATION_TAG[20], sizeof(char) * 4, 1, ue_info_file);
        fclose(ue_info_file);

        crc_ind_file = fopen("crc_ind.txt", "r");
        fseek(crc_ind_file, (i * 1024), SEEK_SET);
        fread(&pdus[i].RX_UE_INFORMATION_TAG[24], sizeof(char) * 4, 1, crc_ind_file);
        fclose(crc_ind_file);

        if (pdus[i].RX_UE_INFORMATION_TAG[20] != pdus[i].RX_UE_INFORMATION_TAG[24]) {
            crc_errors++;
            printf("CRC error detected for SDU %d.\n", i);
        }
    }

    pthread_mutex_unlock(&pdus_mutex);

    // Filter out SDUs with CRC errors
    int filtered_sdus = 0;
    for (int i = 0; i < num_sdus; i++) {
        if (!pdus[i].RX_UE_INFORMATION_TAG[20] || crc_errors / num_sdus > crc_error_threshold) {
            free(pdus);
            return -1;
        }
        filtered_sdus++;
    }

    printf("Total SDUs: %d, Filtered SDUs: %d\n", num_sdus, filtered_sdus);

    // Log detailed information about each processed PDU
    FILE *log_file = fopen("log.txt", "w");
    for (int i = 0; i < filtered_sdus; i++) {
        fprintf(log_file, "RX UE Information Tag: %s, RNTI: %d\n", pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI);
    }
    fclose(log_file);

    free(pdus);
    return 0;
}

