#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    // RX_UE_INFORMATION_TAG
    char tag[16];
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

void create_and_populate_list(int N, const char* filename, FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    int i, count = 0, total_size = 0;
    time_t last_update = time(NULL);

    // Dynamically allocate the list of PDU structures
    pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Populate the list with valid RX_UE_INFORMATION_TAG and RNTI
    for (i = 0; i < N; i++) {
        pdus[i].tag[15] = 'X';
        pdus[i].RNTI = rand() % 1000;

        // Check if the PDU is valid based on external data source
        char buffer[16];
        fseek(file, ftell(file), SEEK_SET);
        fread(buffer, sizeof(char), 16, file);
        if (buffer[15] != 'X' || buffer[14] == 'E') {
            // If invalid, skip and continue with the next PDU
            i--;
            continue;
        }

        // Update total size of SDUs
        total_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (total_size > MAX_BUFFER_SIZE) {
            free(pdus);
            pdus = NULL;
            break;
        }
    }

    // Periodically compact the list to remove unused entries
    while (time(NULL) - last_update < 60 && i < N) {
        for (i--; i >= 0; i--) {
            if (!strcmp(pdus[i].tag, "X") || pdus[i].RNTI == 0) {
                // Remove the PDU from the list
                memmove(&pdus[i], &pdus[i + 1], (N - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                i--;
                count--;
            } else break;
        }
    }

    if (!pdus) {
        fprintf(stderr, "List creation failed.\n");
        return;
    }

    // Store metadata for each PDU in an external database
    FILE* db_file = fopen(filename, "a+");
    for (i = 0; i < count; i++) {
        fwrite(&pdus[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, db_file);
    }
    fclose(db_file);

    // Log important events and free the list
    FILE* log_file = fopen("log.txt", "a+");
    fprintf(log_file, "List created with %d PDUs.\n", count);
    fclose(log_file);
    free(pdus);
}

int main() {
    int N = 1000;
    const char* filename = "pdus.db";
    FILE* file = fopen("data.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening data file.\n");
        return 1;
    }

    create_and_populate_list(N, filename, file);

    fclose(file);
    return 0;
}
