#define MAX_CSV_ENTRIES 10000
#define MAX_NFAPI_CRC_INDICATION_PDU_T 1000

typedef struct {
    uint16_t rnti;
    uint8_t crcflag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    bool crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void read_csv_file(char **ip_addresses, int *num_entries);
int find_max_port_number(const char *const ip_addresses[], int num_entries);

int main() {
    char *ip_addresses[MAX_CSV_ENTRIES];
    int num_entries = 0;

    read_csv_file(ip_addresses, &num_entries);

    NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(
            MAX_NFAPI_CRC_INDICATION_PDU_T * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    srand(time(NULL)); // For consistent random number generation

    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
        RX_UE_INFORMATION_TAG rx_ue_info_tag;
        rx_ue_info_tag.rnti = rand() % 1000;
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
        crc_indication_rel8_tag.crcflag = (bool)(rand() % 2);

        NFAPI_CRC_INDICATION_PDU_T nfapi_crc_indication;
        nfapi_crc_indication.rx_ue_info_tag = rx_ue_info_tag;
        nfapi_crc_indication.crc_indication_rel8_tag = crc_indication_rel8_tag;

        nfapi_crc_indications[i] = nfapi_crc_indication;
    }

    int max_port_number = find_max_port_number(ip_addresses, num_entries);

    printf("IP address with the highest port number: %s\n", ip_addresses[max_port_number]);

    free(nfapi_crc_indications);
    return 0;
}

void read_csv_file(char **ip_addresses, int *num_entries) {
    FILE *file = fopen("ip_addresses.csv", "r");
    if (file == NULL) {
        printf("Error reading CSV file.\n");
        exit(1);
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        ip_addresses[*num_entries] = strtok(line, ",");
        if (!ip_addresses[*num_entries]) {
            printf("Invalid IP address format in the CSV file.\n");
            fclose(file);
            exit(1);
        }
        (*num_entries)++;
    }

    fclose(file);
}

int find_max_port_number(const char *const ip_addresses[], int num_entries) {
    int max_port_number = 0;

    for (int i = 0; i < num_entries; i++) {
        // Assuming the port number is the last part of the IP address
        const char *port_str = strtok(ip_addresses[i], ".");
        if (port_str) {
            int port = atoi(port_str);
            if (port > max_port_number)
                max_port_number = port;
        }
    }

    return max_port_number;
}
