#include <stdlib.h>
#include <stdio.h>
#include <time.h>

struct Node *create_crc_indication_list(int N) {
    struct Node *head = NULL;
    struct Node *curr = NULL;
    srand(time(NULL)); // seed for random number generation

    if (N <= 0) {
        return NULL; // invalid input
    }

    for (int i = 0; i < N; i++) {
        curr = (struct Node *)malloc(sizeof(struct Node));
        if (!curr) {
            while (head) { // free any allocated memory on error
                struct Node *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL; // allocation failed, return error
        }

        curr->pdu.RX_UE_INFORMATION_TAG = i; // assign valid RX_UE_INFORMATION_TAG
        curr->pdu.RNTI = rand() % 100; // generate random RNTI
        curr->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() & 1) ? CRC_INDICATION_REL8_FLAG_VALID : CRC_INDICATION_REL8_FLAG_INVALID;

        if (!head) { // create head of the list for the first node
            head = curr;
        } else {
            curr->prev = head;
            head->next = curr;
            head = curr; // update head to point to the new node
        }
    }

    return head;
}
