// Structure definitions
typedef struct {
    int RNTI;
    unsigned char RX_UE_INFORMATION_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_crc_indication_pdu_list(int max_entries, bool initialize_with_predefined_structures) {
    // Initialize variables
    int entries = 0;
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_list = NULL;

    // Check if the input parameters are valid
    if (max_entries <= 0 || !initialize_with_predefined_structures) {
        return -1;  // Invalid input parameter
    }

    // Dynamically allocate memory for the list
    crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indication_pdu_list) {
        return -2;  // Memory allocation failure
    }

    // Initialize the list with predefined structures or generate them randomly
    for (int i = 0; i < max_entries; i++) {
        crc_indication_pdu_list[i].RNTI = rand() % 1000;
        if (!initialize_with_predefined_structures) {
            // Generate RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG randomly
            srand(time(NULL));
            for (int j = 0; j < 16; j++) {
                crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG[j] = rand() % 256;
            }
        } else {
            // Initialize RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG with predefined values
            for (int j = 0; j < 16; j++) {
                crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG[j] = 0x12;
            }
        }
    }

    // Return the list
    return 0;
}

// Function to prune old or unused entries from the list
void prune_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_list, int entries) {
    // Check if the input parameters are valid
    if (entries <= 0 || !crc_indication_pdu_list) {
        return;  // Invalid input parameter
    }

    // Calculate the threshold for pruning based on configurable time duration or number of unused entries
    const int THRESHOLD = 10;  // Threshold value

    // Prune old or unused entries from the list
    for (int i = 0; i < entries; i++) {
        if (crc_indication_pdu_list[i].RNTI <= THRESHOLD) {
            // Remove entry from the list
            memmove(&crc_indication_pdu_list[i], &crc_indication_pdu_list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            entries--;
            i--;  // Decrement the index to re-check this entry
        }
    }

    return;
}

int main() {
    int max_entries = 1000;
    bool initialize_with_predefined_structures = true;

    // Create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
    int error_code = create_crc_indication_pdu_list(max_entries, initialize_with_predefined_structures);

    if (error_code != 0) {
        printf("Error: %d\n", error_code);
        return -1;  // Error occurred during list creation
    }

    // Print the created list
    for (int i = 0; i < max_entries; i++) {
        printf("%d, ", crc_indication_pdu_list[i].RNTI);
    }
    printf("\n");

    // Prune old or unused entries from the list
    prune_crc_indication_pdu_list(crc_indication_pdu_list, max_entries);

    return 0;
}

