    struct list_node* prev;
    struct list_node* next;
} list_node;

list_node* list_head = NULL;
list_node* list_tail = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int count = 0;

void log(int type, const char* msg) {
    // Implement logging mechanism here
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = (char*)malloc(100);
    if (!pdu->RX_UE_INFORMATION_TAG) {
        free(pdu);
        return NULL;
    }
    strcpy(pdu->RX_UE_INFORMATION_TAG, "RX_TAG");
    pdu->RNTI = rand() % 1000 + 1;
    pdu->CRC_INDICATION_REL8_TAG = (char*)malloc(20);
    if (!pdu->CRC_INDICATION_REL8_TAG) {
        free(pdu->RX_UE_INFORMATION_TAG);
        free(pdu);
        return NULL;
    }
    strcpy(pdu->CRC_INDICATION_REL8_TAG, "CRC_TAG");
    return pdu;
}

void* list_new(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        log(0, "Memory allocation failed");
        return NULL;
    }
    return ptr;
}

int add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lock);
    list_node* node = (list_node*)malloc(sizeof(list_node));
    if (!node) {
        log(0, "Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    node->data = *pdu;
    node->prev = NULL;
    node->next = list_head;
    if (list_head) {
        list_head->prev = &node->data;
    } else {
        list_tail = &node->data;
    }
    list_head = node;
    pthread_mutex_unlock(&lock);
    log(1, "Structure added to the list");
    return 0;
}

void check_integrity() {
    pthread_mutex_lock(&lock);
    for (list_node* curr = list_head; curr; curr = curr->next) {
        if (!curr->data.RX_UE_INFORMATION_TAG || !curr->data.CRC_INDICATION_REL8_TAG) {
            log(0, "Invalid structure detected");
        }
    }
    pthread_mutex_unlock(&lock);
}

void free_list() {
    list_node* curr = list_head;
    while (curr) {
        list_node* next = curr->next;
        free(curr->data.RX_UE_INFORMATION_TAG);
        free(curr->data.CRC_INDICATION_REL8_TAG);
        free(curr);
        curr = next;
    }
}

void* list_delete() {
    pthread_mutex_lock(&lock);
    if (list_head) {
        void* ptr = list_head;
        list_head = list_head->next;
        if (!list_head) {
            list_tail = NULL;
        } else {
            list_tail = &list_head->data;
        }
        free(ptr);
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    // Create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < 100000; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu();
        if (!pdu) {
            continue;
        }
        int result = add_pdu_to_list(pdu);
        if (result == -1) {
            log(0, "Failed to add structure to the list");
        }
    }

    // Periodically check the integrity of all stored structures
    for (int i = 0; i < 100; i++) {
        check_integrity();
        sleep(1);
    }

    // Release allocated memory and resources
    free_list();

    return 0;
}
