        crc_indications[i].RX_UE_INFORMATION_TAG[0] = (unsigned char) (rnti >> 8);
        crc_indications[i].RX_UE_INFORMATION_TAG[1] = (unsigned char) (rnti >> 4 & 0x0F);
        crc_indications[i].RX_UE_INFORMATION_TAG[2] = (unsigned char) (rnti << 4);
