#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store LTE_RRC_CDRRQ_T information
typedef struct {
    int UE_ID;
    char RRC_connection_request[256];
    int PDCP_SN_SIZE;
} LTE_RRC_CDRRQ_T;

// Define a linked list node for storing LTE_RRC_CDRRQ_T structures
typedef struct Node {
    LTE_RRC_CDRRQ_T data;
    struct Node* next;
} ListNode;

// Function to create and populate the list of LTE_RRC_CDRRQ_T structures
ListNode* create_and_populate_list(int num_elements) {
    ListNode* head = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Create and populate the list dynamically
    for (int i = 0; i < num_elements; i++) {
        ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));

        if (!new_node) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Initialize random UE_ID and RRC connection request information
        int UE_ID = rand() % 1000;
        char RRC_connection_request[256];
        strcpy(RRC_connection_request, "RRC Connection Request");

        // Initialize PDCP_SN_SIZE randomly
        new_node->data.PDCP_SN_SIZE = rand() % 8 + 1;

        new_node->data.UE_ID = UE_ID;
        strcpy(new_node->data.RRC_connection_request, RRC_connection_request);

        // Add the node to the list
        pthread_mutex_lock(&mutex);
        if (!head) {
            head = new_node;
        } else {
            ListNode* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }
        pthread_mutex_unlock(&mutex);
    }

    return head;
}

// Function to remove an element from the list by index
void remove_element_by_index(ListNode** head, int index) {
    if (!*head) {
        printf("List is empty.\n");
        return;
    }

    ListNode* current = *head;
    ListNode* previous = NULL;

    for (int i = 0; i < index && current->next; i++) {
        previous = current;
        current = current->next;
    }

    if (!current) {
        printf("Index out of bounds.\n");
        return;
    }

    if (previous) {
        previous->next = current->next;
    } else {
        *head = current->next;
    }

    free(current);
