    *ue_session_data = (UE_Session_Data_T*)malloc(total_sessions * sizeof(UE_Session_Data_T));

    for (int i = 0; i < total_sessions; i++) {
        json_object *session_config = json_object_get(config, json_object_reject_keys(config, i));

        if (!session_config) {
            printf("Failed to load session configuration.\n");
            exit(1);
        }

        int UE_ID = json_object_get_int(session_config, "UE_ID");
        int RNTI = json_object_get_int(session_config, "RNTI");
        double signal_strength = (double)(rand() % 100) / (RAND_MAX / 100.0);

        (*ue_session_data)[i].UE_ID = UE_ID;
        (*ue_session_data)[i].RNTI = RNTI;
        (*ue_session_data)[i].signal_strength = signal_strength;
