    // Check if the new size is larger than the current list size
    if (new_size > (*list)->len) {
        // Create a new list with the desired size
        NFAPI_CRC_INDICATION_PDU_T* new_list = create_list(new_size);

        // Copy the old list to the new list
        for (int i = 0; i < (*list)->len; i++) {
            new_list[i] = (*list)[i];
        }

        // Free the old list and update the pointer
        free(*list);
        *list = new_list;
    } else {
        // If the new size is smaller, we need to trim the list
        for (int i = 0; i < new_size; i++) {
            (*list)[i] = (*list)[i + (*list)->len - new_size];
        }

        // Update the length of the list
        (*list)->len = new_size;
