void* create_and_populate_list(int num_elements) {
    // Initialize logging level and file path based on environment
    char log_level[] = "INFO";
    char log_file_path[] = "/dev/null";

    // Open the log file
    FILE* log_file = fopen(log_file_path, "a");
    if (!log_file) {
        // Handle file open error
        return NULL;
    }

    // Initialize memory allocation for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        // Handle memory allocation failure
        fclose(log_file);
        return NULL;
    }

    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = &list[i];
        element->RX_UE_INFORMATION_TAG = i;
        element->RNTI = rand() % 10000;

        // Set CRCFLAG randomly
        int crcflag = rand() % 2;

        // Log the creation of each structure
        char log_message[256];
        sprintf(log_message, "Created RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", element->RX_UE_INFORMATION_TAG, element->RNTI, crcflag);
        fprintf(log_file, "[%s] %s", log_level, log_message);

        // Rotate the log file based on date
        time_t current_time = time(NULL);
        if (current_time > (time_t)0 && current_time % 86400 == 0) {
            fclose(log_file);
            log_file = fopen(log_file_path, "w");
        }
