void create_crc_list(int num_elements, NFAPI_CRC_INDICATION_PDU_T** list) {
    if (num_elements <= 0) {
        *list = NULL;
        return;
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        return;
    }

    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* elem = &(*list)[i];

        // Validate input parameters
        if (i >= 1 && elem->rnti > 100) {
            printf("Invalid RNTI value: %d\n", elem->rnti);
            return;
        }

        // Allocate memory for CRC indication rel8 tag
        size_t tag_len = rand() % 10 + 1; // Random length between 1 and 10 bytes
        elem->crc_indication_rel8_tag = (char*)malloc(tag_len * sizeof(char));
        if (!elem->crc_indication_rel8_tag) {
            return;
        }

        for (int j = 0; j < tag_len; j++) {
            elem->crc_indication_rel8_tag[j] = 'a' + rand() % 26; // Generate random ASCII chars
        }
        elem->crc_indication_rel8_tag[tag_len] = '\0';

        // Set CRC flag randomly
        elem->rnti += rand() % 2; // Toggle RNTI every other element

        printf("Created NFAPI_CRC_INDICATION_PDU_T with RNTI: %d, Tag: '%s', CRC flag: %d\n",
               elem->rnti, elem->crc_indication_rel8_tag, (elem->rnti & 1));
    }
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T** list) {
    if (*list == NULL) {
        return;
    }

    for (int i = 0; *list[i].crc_indication_rel8_tag != NULL; i++) {
        free((*list)[i].crc_indication_rel8_tag);
    }
    free(*list);
}

int main() {
    int num_elements = 5;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    create_crc_list(num_elements, &list);

    // Clear the list and free resources
    if (num_elements > 0) {
        for (int i = 0; i < num_elements; i++) {
            free(list[i].crc_indication_rel8_tag);
        }
        free(list);
    }

    return 0;
}
