```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int rnti;
    char tag[16];
} RX_UE_INFORMATION_TAG;

typedef enum {
    ASCENDING,
    DESCENDING
} SORT_ORDER;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    unsigned int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

NFAPI_CRC_LIST* nfaPiCrcListCreate(size_t max_elements) {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL; // handle memory allocation failure

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL; // handle memory allocation failure
    }

    list->capacity = max_elements;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void nfaPiCrcListDestroy(NFAPI_CRC_LIST* list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    free(list->elements);
    free(list);
}

int nfaPiCrcListAdd(NFAPI_CRC_LIST* list, RX_UE_INFORMATION_TAG* rx_ue_info, unsigned int crcflag) {
    if (!list || !rx_ue_info) return -1; // handle invalid input

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        // handle capacity exceeded
        printf("Error: NFAPI_CRC_LIST overflow\n");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
        printf("Error: memory allocation failure\n");
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    new_element->rx_ue_info = *rx_ue_info;
    new_element->crcflag = crcflag;

    list->elements[list->size] = *new_element;
    list->size++;

    free(new_element);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void nfaPiCrcListPrint(NFAPI_CRC_LIST* list) {
    if (!list) return; // handle invalid input

    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        printf("RNTI: %d, Tag: %s, CRCFLAG: 0x%x\n", 
            list->elements[i].rx_ue_info.rnti, 
            list->elements[i].rx_ue_info.tag,
            list->elements[i].crcflag);
    }

    pthread_mutex_unlock(&list->lock);
}

void nfaPiCrcListSort(NFAPI_CRC_LIST* list, SORT_ORDER order) {
    if (!list) return; // handle invalid input

    NFAPI_CRC_INDICATION_PDU_T* temp;
    int i, j;

    pthread_mutex_lock(&list->lock);

    for (i = 0; i < list->size - 1; i++) {
        for (j = 0; j < list->size - i - 1; j++) {
            if ((order == ASCENDING && list->elements[j].rx_ue_info.rnti > list->elements[j + 1].rx_ue_info.rnti) || 
                (order == DESCENDING && list->elements[j].rx_ue_info.rnti < list->elements[j + 1].rx_ue_info.rnti)) {
                temp = list->elements[j];
                list->elements[j] = list->elements[j + 1];
                list->elements[j + 1] = temp;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void nfaPiCrcListExport(NFAPI_CRC_LIST* list, char* filename) {
    if (!list || !filename) return; // handle invalid input

    FILE* file = fopen(filename, "w");
    if (!file) return; // handle file opening failure

    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        fprintf(file, "%d,\"%s\",0x%x\n", 
            list->elements[i].rx_ue_info.rnti,
            list->elements[i].rx_ue_info.tag,
            list->elements[i].crcflag);
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}
