NFAPI_CRC_INDICATION_PDU_T** create_crc_indication_pdu_list(int N) {
    srand(time(NULL)); // seed random number generator

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDATION_PDU_T**)malloc((N+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) return NULL; // memory allocation failed

    for (int i = 0; i < N; i++) {
        int RNTI = rand() % INT_MAX;
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) return NULL; // memory allocation failed

        list[i]->RX_UE_INFORMATION_TAG = i;
        list[i]->RNTI = RNTI;
        list[i]->CRCFLAG = rand() % 2;

        for (int j = i-1; j >= 0; j--) {
            if (list[j]->RNTI == RNTI) {
                free(list[i]);
                i--; // increment loop to re-generate a new RNTI
                break;
            }
        }
    }

    list[N] = NULL; // sentinel value

    return list;
}
