function copyData(chunks, numBytes) {
    let buffer = new Buffer(numBytes);
    for (let i = 0; i < chunks.length; i++) {
        const chunk = chunks[i];
        if (i * Buffer.byteLength(chunk) + numBytes > chunk.length) {
            break;
        }
        buffer.copy(chunk, 0, 0, numBytes);
    }
    return buffer.slice(0, numBytes);
}
