// Function to create and populate list of LTE UE context structures
void populate_lte_ue_context_list(int num_ue, int num_active_bearers_per_ue) {
    // Seed random number generator for reproducibility
    srand(time(NULL));

    // Create list of UE contexts
    LteUeContext* ue_contexts = (LteUeContext*)malloc(num_ue * sizeof(LteUeContext));

    if (!ue_contexts) {
        printf("Memory allocation failed for UE context list.\n");
        return;
    }

    // Initialize UE context structures
    for (int i = 0; i < num_ue; i++) {
        ue_contexts[i].ue_id = rand() % 10000 + 1;
        strcpy(ue_contexts[i].mac_addr, "00:11:22:33:44:55"); // Hardcode MAC address
        ue_contexts[i].num_active_bearers = num_active_bearers_per_ue;

        for (int j = 0; j < num_active_bearers_per_ue; j++) {
            ue_contexts[i].bearers[j].qos_parameter = rand() % 100 + 1;
            ue_contexts[i].bearers[j].transport_layer_info = rand() % 256;
        }
    }

    // Create list of NFAPI CRC indication PDUs
    int num_crc_pdu = num_ue * 2; // Each UE has one PDU per active bearer (two for two-sided transmission)
    NfapiCrcIndicationPdu* crc_indications = (NfapiCrcIndicationPdu*)malloc(num_crc_pdu * sizeof(NfapiCrcIndicationPdu));

    if (!crc_indications) {
        printf("Memory allocation failed for CRC indication list.\n");
        free(ue_contexts);
        return;
    }

    // Initialize NFAPI CRC indication PDUs
    int rnti_count = 0;
    for (int i = 0; i < num_ue; i++) {
        for (int j = 0; j < num_active_bearers_per_ue; j++) {
            crc_indications[rnti_count].rx_ue_information_tag = rand() % 10000 + 1;
            crc_indications[rnti_count].rnti = rnti_count++;
            crc_indications[rnti_count].crc_flag = rand() % 2;

            // Ensure no two structures have the same RNTI
            while (find_structure_with_same_rnti(crc_indications, rnti_count) != -1) {
                crc_indications[rnti_count].rnti = rnti_count++;
            }
        }
    }

    printf("LTE UE context list populated.\n");
}

// Function to find structure with same RNTI
int find_structure_with_same_rnti(NfapiCrcIndicationPdu* crc_indications, int target_rnti) {
    for (int i = 0; i < sizeof(crc_indications) / sizeof(NfapiCrcIndicationPdu); i++) {
        if (crc_indications[i].rnti == target_rnti) {
            return i;
        }
    }

    return -1; // Not found
}

int main() {
    int num_ue = 100;
    int num_active_bearers_per_ue = 3;

    populate_lte_ue_context_list(num_ue, num_active_bearers_per_ue);

    return 0;
}
