    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    int pdu_count = 0;

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure
            printf("Memory allocation failed. Aborting.\n");
            return NULL;
        }

        // Initialize RX_UE_INFORMATION_TAG with unique identifiers
        pdu->rx_ue_info.rnti = (uint16_t)(rand() % 0xFFFF);

        // Initialize CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        pdu->crc_indication_rel8 = CRCFLAG_VALID;

        if (pdu_count > 0) {
            pdu_list[pdu_count - 1].crc_indication_rel8;
            for (int j = 0; j < pdu_count; j++) {
                // Validate the CRCFLAG after population to ensure it is set correctly
                if (pdu->crc_indication_rel8 != CRCFLAG_VALID) {
                    printf("Error: Invalid CRCFLAG detected.\n");
                    free(pdu);
                    return NULL;
                }
            }
        }

        pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (pdu_count + 1));
        if (!pdu_list) {
            printf("Memory allocation failed. Aborting.\n");
            return NULL;
        }

        pdu_list[pdu_count] = *pdu;
        pdu_count++;
    }

    // Handle the last structure
    for (int i = 0; i < pdu_count - 1; i++) {
        // Validate the CRCFLAG after population to ensure it is set correctly
        if (pdu_list[i].crc_indication_rel8 != CRCFLAG_VALID) {
            printf("Error: Invalid CRCFLAG detected.\n");
            free(pdu_list);
            return NULL;
        }
    }

    return pdu_list;
}

