void* populate_list(int N) {
    // Initialize random number generation
    srand(time(NULL));

    // Measure time taken to populate the list and resident set size before population
    clock_t start_time = clock();
    int RSSIZE = sysconf(_SC_PAGESIZE);

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    void* list_memory = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list_memory) {
        return NULL;
    }

    sem_t* semaphore = sem_open("/semaphore", O_CREAT, 0644, 1);
    if (semaphore == SEM_FAILED) {
        // Handle error
        free(list_memory);
        return NULL;
    }

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)list_memory + i;

        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 256;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 16;

        // Check for errors during population
        if (sem_getvalue(semaphore, &i) == -1) {
            // Handle error
            free(list_memory);
            sem_close(semaphore);
            return NULL;
        }
    }

    // Measure time taken to populate the list and resident set size after population
    clock_t end_time = clock();
    int total_time_taken = (end_time - start_time) * 1000.0 / CLOCKS_PER_SEC;

    RSSIZE = sysconf(_SC_PAGESIZE);

