void populate_ue_contexts(UERegistrationList *list, size_t num_ues) {
    for (size_t i = 0; i < num_ues; i++) {
        LTE_UEREGISTRATION_CONTEXT_T *ue_ctx = malloc(sizeof(LTE_UEREGISTRATION_CONTEXT_T));
        ue_ctx->ue_id = i;
        ue_ctx->measurement_report.signal_strength = rand() % 100 + 1;
        time(&ue_ctx->measurement_report.timestamp);
        pthread_mutex_lock(&list->mutex);
        list->ue_contexts[list->size] = ue_ctx;
        list->size++;
        pthread_mutex_unlock(&list->mutex);
    }
}

void serialize_ue_contexts(UERegistrationList *list, const char *filename) {
    json_object *jobj = json_object_new_object();
    for (size_t i = 0; i < list->size; i++) {
        LTE_UEREGISTRATION_CONTEXT_T *ue_ctx = list->ue_contexts[i];
        json_object *sub_obj = json_object_new_object();
        json_object_object_add(sub_obj, "ue_id", json_object_new_int(ue_ctx->ue_id));
        json_object_object_add(sub_obj, "signal_strength", json_object_new_int(ue_ctx->measurement_report.signal_strength));
        json_object_object_add(sub_obj, "timestamp", json_object_new_double((double)ue_ctx->measurement_report.timestamp));
        json_object_object_add(jobj, "ue_contexts", sub_obj);
    }
    FILE *file = fopen(filename, "w");
    if (file != NULL) {
        json_object_to_file_name(jobj, file, FALSE);
        fclose(file);
    } else {
        printf("Error opening file for writing.\n");
    }
    json_decref(jobj);
}

void deserialize_ue_contexts(UERegistrationList *list, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file != NULL) {
        json_object *jobj = json_object_from_file_name(file);
        for (json_object_iter iter = json_object_iterate(jobj); iter; ) {
            json_object *sub_obj = json_object_get(iter.value);
            LTE_UEREGISTRATION_CONTEXT_T *ue_ctx = malloc(sizeof(LTE_UEREGISTRATION_CONTEXT_T));
            ue_ctx->ue_id = json_object_get_int(sub_obj, "ue_id");
            ue_ctx->measurement_report.signal_strength = json_object_get_int(sub_obj, "signal_strength");
            time_t timestamp;
            if (json_object_get_double(sub_obj, "timestamp") > 0) {
                timestamp = (time_t)(double)json_object_get_double(sub_obj, "timestamp");
            } else {
                timestamp = time(NULL);
            }
            ue_ctx->measurement_report.timestamp = timestamp;
            pthread_mutex_lock(&list->mutex);
            list->ue_contexts[list->size] = ue_ctx;
            list->size++;
            pthread_mutex_unlock(&list->mutex);
        }
        fclose(file);
    } else {
        printf("Error opening file for reading.\n");
    }
}

void remove_stale_ue_contexts(UERegistrationList *list, time_t threshold) {
    for (int i = 0; i < list->size; i++) {
        LTE_UEREGISTRATION_CONTEXT_T *ue_ctx = list->ue_contexts[i];
        if ((time(NULL) - ue_ctx->measurement_report.timestamp) > threshold) {
            pthread_mutex_lock(&list->mutex);
            free(ue_ctx);
            for (int j = i; j < list->size - 1; j++) {
                list->ue_contexts[j] = list->ue_contexts[j + 1];
            }
            list->size--;
            pthread_mutex_unlock(&list->mutex);
        }
    }
}

void log_ue_context_operation(UERegistrationList *list, const char *operation) {
    FILE *log_file = fopen("ue_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: UE Context List - Size: %zu\n", operation, list->size);
        fclose(log_file);
    } else {
        printf("Error opening log file.\n");
    }
}

