from typing import Dict, Any

class NetworkConfigManager:
    _registry: Dict[str, Any]
    _factory_registry: Dict[str, Any]

    def __init__(self):
        self._registry = {}
        self._factory_registry = {}

    def add_factory_function(self, factory_id: str, factory_func: Any) -> None:
        self._factory_registry[factory_id] = factory_func

    def create_instance(self, factory_id: str, data: Dict[str, Any]) -> Any:
