    private static final int MAX_THREADS = 5;

    private static Map<String, UEInfo> bufferMap = new HashMap<>();
    private static Map<String, Integer> threadCountMap = new HashMap<>();

    private static Logger logger = Logger.getLogger(UEInfoManager.class.getName());

    public static void main(String[] args) {
        // Initialize configuration
        int bufferCapacity = 100;
        if (System.getProperty("buffer.size") != null) {
            bufferCapacity = Integer.parseInt(System.getProperty("buffer.size"));
        }
        int maxThreads = 5;
        if (System.getProperty("max.threads") != null) {
            maxThreads = Integer.parseInt(System.getProperty("max.threads"));
        }

        // Start log rotation
        File logFile = new File("ue_info.log");
        LogRotator logRotator = new LogRotator(logFile, 1000 * 60 * 5); // Rotate after 5 minutes

        try {
            // Start UE info service
            UEInfoService ueInfoService = new UEInfoService();

            while (true) {
                // Fetch UE information from external data source
                UEInfo[] ueInfos = ueInfoService.fetchUEInformation();

                // Process UE information
                for (UEInfo ueInfo : ueInfos) {
                    if (!processUEInfo(ueInfo)) {
                        logger.log(Level.SEVERE, "Error processing UE info: {0}", ueInfo);
                    }
                }

                // Rotate log file
                logRotator.rotate();
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error starting UE info service: {0}", e.getMessage());
        }
    }

    private static boolean processUEInfo(UEInfo ueInfo) {
        // Validate JSON data
        if (!validateJSONData(ueInfo)) {
            return false;
        }

        // Create UE structure
        UEStructure ueStruct = createUEStructure(ueInfo);

        // Add UE structure to buffer
        addUEStructureToBuffer(ueStruct);

        return true;
    }

    private static boolean validateJSONData(UEInfo ueInfo) {
        try {
            JSONObject json = new JSONObject(new String(ueInfo.getJSONData()));
            if (!json.has("ue_id") || !json.has("location")) {
                logger.log(Level.SEVERE, "Invalid JSON data: {0}", ueInfo);
                return false;
            }
        } catch (JSONException e) {
            logger.log(Level.SEVERE, "Error parsing JSON data: {0}", ueInfo);
            return false;
        }

        return true;
    }

    private static UEStructure createUEStructure(UEInfo ueInfo) {
        // Create UE structure
        UEStructure ueStruct = new UEStructure();
        ueStruct.setUEId(ueInfo.getUEId());
        ueStruct.setLocation(ueInfo.getLocation());

        return ueStruct;
    }

    private static void addUEStructureToBuffer(UEStructure ueStruct) {
        // Add UE structure to buffer
        String bufferKey = getBufferKey(ueStruct);
        if (!bufferMap.containsKey(bufferKey)) {
            bufferMap.put(bufferKey, new ArrayList<UEStructure>());
        }
        ((ArrayList<UEStructure>) bufferMap.get(bufferKey)).add(ueStruct);

        // Update thread count
        synchronized (threadCountMap) {
            int currentThreadCount = threadCountMap.getOrDefault(bufferKey, 0);
            threadCountMap.put(bufferKey, currentThreadCount + 1);
        }
    }

    private static String getBufferKey(UEStructure ueStruct) {
        return ueStruct.getUEId().toString();
    }
}

