#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    uint32_t ue_id;
    char mac_address[18];
} LTE_UE_CONTEXT_T;

typedef struct {
    uint32_t sequence_number;
    size_t payload_size;
} RLC_PDU_T;

typedef struct {
    LTE_UE_CONTEXT_T context;
    RLC_PDU_T *pdus;
    size_t pdu_count;
} UE_CONTEXT_LIST_T;

void create_ue_context_list(UE_CONTEXT_LIST_T *list, size_t num_ues, size_t num_pdus) {
    *list = (UE_CONTEXT_LIST_T)malloc(sizeof(UE_CONTEXT_LIST_T));

    if (!*list)
        return; // Return immediately if memory allocation fails

    (*list)->pdu_count = 0;

    for (size_t i = 0; i < num_ues; ++i) {
        LTE_UE_CONTEXT_T ue_context;
        srand(time(NULL) + i); // Initialize random seed
        ue_context.ue_id = rand() % UINT32_MAX;

        // Generate MAC address
        for (int j = 0; j < 18; ++j) {
            if (j == 17)
                ue_context.mac_address[j] = '\0';
            else
                ue_context.mac_address[j] = (rand() % 2 ? 'A' : 'a');
        }

        (*list)->context = ue_context;

        for (size_t j = 0; j < num_pdus; ++j) {
            RLC_PDU_T pdu;
            srand(time(NULL) + i + j); // Initialize random seed
            pdu.sequence_number = rand() % UINT32_MAX;
            pdu.payload_size = rand() % SIZE_MAX;

            (*list)->pdus = (RLC_PDU_T *)realloc((*list)->pdus, (++(*list)->pdu_count) * sizeof(RLC_PDU_T));

            if (!(*list)->pdus)
                return; // Return immediately if memory allocation fails

            (*list)->pdus[(*list)->pdu_count - 1] = pdu;
        }
    }
}
