    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    int rand_num = rand() % 2; // Randomly set CRCFLAG
    pdu->CRCFLAG = (rand_num == 0) ? CRCFLAG_ON : CRCFLAG_OFF;
    return pdu;
}

int insert_pdu(node** head, node** tail, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return -1; // Invalid input
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return -2; // Memory allocation failed
    new_node->data = pdu;
    new_node->prev = NULL;
    new_node->next = (*head);
    if (*head) {
        (*head)->prev = &new_node;
        *head = new_node;
    } else {
        *tail = new_node;
    }
    return 0; // Success
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return; // Invalid input
    free(pdu);
}

int delete_pdu(node** head, node** tail, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return -1; // Invalid input
    node* curr = *head;
    while (curr && curr->data != pdu) {
        curr = curr->next;
    }
    if (!curr) return -2; // PDU not found in the list
    if (curr == *head) {
        *head = curr->next;
    } else if (curr == *tail) {
        *tail = curr->prev;
    }
    curr->prev->next = curr->next;
    curr->next->prev = curr->prev;
    free_pdu(curr->data);
    free(curr);
    return 0; // Success
}

int list_size(node* head) {
    int count = 0;
    node* curr = head;
    while (curr) {
        count++;
        curr = curr->next;
    }
    return count;
}

int limit_max_count(int max_count_input) {
