    while (curr) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %s\n", curr->data->RX_UE_INFORMATION_TAG, curr->data->RNTI, curr->data->CRCFLAG == CRCFLAG_ON ? "ON" : "OFF");
        curr = curr->next;
    }
}

int main() {
    int num_pdus = 5; // Number of PDUs to create
    init_list();
    for (int i = 0; i < num_pdus; i++) {
