// Dynamic list of UE contexts
struct UE_Context_List {
    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    pthread_mutex_t lock;
};

// Function to create a new UE context list
UE_Context_List* ue_context_list_create() {
    UE_Context_List* list = (UE_Context_List*)malloc(sizeof(UE_Context_List));
    if (!list) return NULL;

    list->data = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to add a new UE context
int ue_context_list_add(UE_Context_List* list, NFAPI_CRC_INDICATION_PDU_T* ctx) {
    if (!list || !ctx) return -1;

    pthread_mutex_lock(&list->lock);
    int i;
    for (i = 0; i < list->size; i++) {
        if (!strcmp(ctx->CRC_INDICATION_REL8_TAG, list->data[i].CRC_INDICATION_REL8_TAG)) {
            pthread_mutex_unlock(&list->lock);
            return -1; // UE context already exists
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newData) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    list->data = newData;
    list->data[list->size] = *ctx;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to update an existing UE context
int ue_context_list_update(UE_Context_List* list, NFAPI_CRC_INDICATION_PDU_T* ctx) {
    if (!list || !ctx) return -1;

    pthread_mutex_lock(&list->lock);
    int i;
    for (i = 0; i < list->size; i++) {
        if (!strcmp(ctx->CRC_INDICATION_REL8_TAG, list->data[i].CRC_INDICATION_REL8_TAG)) {
            memcpy(&list->data[i], ctx, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return -1; // UE context not found
}

// Function to remove a UE context
int ue_context_list_remove(UE_Context_List* list, NFAPI_CRC_INDICATION_PDU_T* ctx) {
    if (!list || !ctx) return -1;

    pthread_mutex_lock(&list->lock);
    int i;
    for (i = 0; i < list->size; i++) {
        if (!strcmp(ctx->CRC_INDICATION_REL8_TAG, list->data[i].CRC_INDICATION_REL8_TAG)) {
            memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;

            if (i < list->size) {
                NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!newData) {
                    pthread_mutex_unlock(&list->lock);
                    return -2; // Memory allocation failed
                }

                list->data = newData;
            } else {
                free(list->data); // Remove the last UE context
                list->data = NULL;
            }

            pthread_mutex_unlock(&list->lock);

            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return -1; // UE context not found
}

