NFAPI_CRC_INDICATION_PDU_T* ue_contexts[MAX_UE_CONTEXTS];
int num_ue_contexts = 0;

void add_ue_context(NFAPI_CRC_INDICATION_PDU_T* new_context) {
    pthread_rwlock_wrlock(&context_lock);
    if (num_ue_contexts < MAX_UE_CONTEXTS) {
        ue_contexts[num_ue_contexts] = new_context;
        num_ue_contexts++;
    } else {
        // Handle overflow
        printf("Error: Maximum number of UE contexts reached.\n");
    }
    pthread_rwlock_unlock(&context_lock);
}

void update_ue_context(int rnti, uint8_t crcflag) {
    pthread_mutex_lock(&update_lock);
    for (int i = 0; i < num_ue_contexts; i++) {
        if (ue_contexts[i]->RNTI == rnti) {
            ue_contexts[i]->CRCFLAG = crcflag;
            break;
        }
    }
    pthread_mutex_unlock(&update_lock);
}

void remove_ue_context(int rnti) {
    pthread_rwlock_wrlock(&context_lock);
    for (int i = 0; i < num_ue_contexts; i++) {
        if (ue_contexts[i]->RNTI == rnti) {
            memmove(ue_contexts + i, ue_contexts + i + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (num_ue_contexts - i));
            num_ue_contexts--;
            break;
        }
    }
    pthread_rwlock_unlock(&context_lock);
}

