#define MAX_N 1000

typedef struct {
    int rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int N, char* json_file) {
    if (N > MAX_N || N <= 0) {
        return NULL; // invalid input
    }

    // Load configuration from JSON file
    json_object *config = json_load_file(json_file, JSON_LOAD_FLAG_NONE);
    if (!config) {
        printf("Error: cannot load configuration file\n");
        return NULL;
    }

    int rnti_range = json_object_get_int(config, "rnti_range");
    if (rnti_range < 1 || rnti_range > 65535) {
        json_object_free(config);
        printf("Error: invalid RNTI range in configuration file\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(*indications));
    if (!indications) {
        json_object_free(config);
        printf("Error: cannot allocate memory for indications\n");
        return NULL;
    }

    srand(time(NULL)); // initialize random number generator
    for (int i = 0; i < N; i++) {
        int rnti = rand() % rnti_range + 1;
        uint8_t crcflag = (uint8_t)(rand() & 0xFF); // random CRC flag
        indications[i].rnti = rnti;
        indications[i].crcflag = crcflag;
    }

    json_object_free(config);
    return indications;
}

int main() {
    int N = 500; // example usage
    char* json_file = "config.json"; // example file name

    NFAPI_CRC_INDICATION_PDU_T* indications = create_crc_indications(N, json_file);

    if (!indications) {
        printf("Error: unable to create CRC indications\n");
    } else {
        printf("Created %d CRC indications successfully\n", N);
    }

    // Free memory
    free(indications);

    return 0;
}
