Here is the C function that runs a given command in the background using the fork and wait system calls, and returns 1 if successful, 0 otherwise:

```c
#include <sys/types.h>
#include <unistd.h>
#include <stdio.h>

int run_command_in_background(char* command) {
    pid_t pid = fork();

    if (pid == -1) {
        printf("Error forking process.\n");
        return 0;
    } else if (pid > 0) {
        // Parent process
        int status;
        wait(&status);
        return WEXITSTATUS(status);
    } else {
        // Child process
        execlp(command, NULL);
        printf("Command execution failed.\n");
        return 1;
    }
}
