            // Handle data fetch failure or network latency issue
            printf("Error fetching cell config for UE %d\n", i);
            continue;
        }

        context->ue_id = i;
        context->cell_id = cell_config->cell_id;
        context->num_measurements = rand() % MAX_MEASUREMENTS + 1; // generate random number of measurements

        for (int j = 0; j < context->num_measurements; j++) {
            measurement_report* report = &context->measurements[j];

            report->frequency = rand() % ((cell_config->max_frequency - cell_config->min_frequency) / 2) + cell_config->min_frequency; // ensure frequency is within valid range

            do {
                report->signal_strength = (float)rand() / RAND_MAX * (MAX_SIGNAL_STRENGTH - MIN_SIGNAL_STRENGTH) + MIN_SIGNAL_STRENGTH;

                if (!validate_signal_strength(report->signal_strength)) {
                    printf("Error: signal strength out of range for UE %d\n", i);
                    break; // restart loop
                }
            } while (0); // ensure valid signal strength

        }
    }

    return ue_contexts;
}

int main() {
    srand(time(NULL)); // seed random number generator

    int num_ues = MAX_UES;
    lte_ue_context* ue_contexts = create_ue_contexts(num_ues);

    for (int i = 0; i < num_ues; i++) {
        printf("UE %d: Cell ID %d, UE ID %d\n", i, ue_contexts[i].cell_id, ue_contexts[i].ue_id);

        for (int j = 0; j < ue_contexts[i].num_measurements; j++) {
