NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu(int num_entries) {
    NFAPI_CRC_INDICATION_PDU_T* puds = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!puds) return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_entries; i++) {
        pthread_mutex_lock(&lock);
        RX_UE_INFORMATION_TAG tag;
        tag.rnti = (uint16_t)((rand() % 0xFFFF) + 1); // Validate RNTI within valid range
        int crcflag = rand() % 2; // Randomly set CRCFLAG
