        pdu.rx_ue_info = tag;
        pdu.crc_indication_rel8[0] = (uint8_t)(crcflag & 0xFF);
        pdu.crc_indication_rel8[1] = (uint8_t)((crcflag >> 8) & 0xFF);
        pdu.crc_indication_rel8[2] = (uint8_t)((crcflag >> 16) & 0xFF);
        pdu.crc_indication_rel8[3] = (uint8_t)((crcflag >> 24) & 0xFF);
        puds[i] = pdu;
        pthread_mutex_unlock(&lock);
