typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure to hold the list and its metadata
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_LIST_T* nfaapi_crc_list_create(int num_elements) {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->size = 0;
    list->capacity = num_elements;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

// Function to add an element to the list
int nfaapi_crc_list_add(NFAPI_CRC_LIST_T* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (RNTI < 0x0001 || RNTI > 0xFFFF) {
        // Log error: invalid RNTI value
        fprintf(stderr, "Invalid RNTI value %d\n", RNTI);
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        // Dynamically resize the array if it's full
        int new_capacity = list->capacity * 2 + 1;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            // Log error: memory allocation failed
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->capacity = new_capacity;
        list->elements = new_elements;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_element = &list->elements[list->size];
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    int crcflag = rand() % 2; // Randomly set CRCFLAG
    new_element->CRCFLAG = crcflag;

    list->size++;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Function to remove an element from the list
int nfaapi_crc_list_remove(NFAPI_CRC_LIST_T* list, int RNTI) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size; i++) {
        if (list->elements[i].RNTI == RNTI) {
            // Shift elements to fill the gap
            memmove(&list->elements[i], &list->elements[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            list->size--;

            if (i >= list->capacity / 2) {
                // Dynamically resize the array if it's getting too small
                int new_capacity = list->capacity / 2 + 1;
                NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!new_elements) {
                    // Log error: memory allocation failed
                    fprintf(stderr, "Memory allocation failed\n");
                    pthread_mutex_unlock(&list->mutex);
                    return -1;
                }
                list->capacity = new_capacity;
                list->elements = new_elements;
            }

            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Function to print the list
void nfaapi_crc_list_print(NFAPI_CRC_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", list->elements[i].RX_UE_INFORMATION_TAG, list->elements[i].RNTI, list->elements[i].CRC_INDICATION_REL8_TAG, list->elements[i].CRCFLAG);
    }

    pthread_mutex_unlock(&list->mutex);
}

int main() {
    NFAPI_CRC_LIST_T* list = nfaapi_crc_list_create(10000);

    for (int i = 0; i < 10; i++) {
        nfaapi_crc_list_add(list, i, i * 2 + 1, i * 3 + 4);
    }

    printf("Initial list:\n");
    nfaapi_crc_list_print(list);

    // Add or remove elements as needed

    return 0;
}
