NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n, int max_structures) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    int allocated = 0;
    int remaining = max_structures;

    if (remaining > 0) {
        pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * remaining);

        if (!pdu_list) {
            printf("Error: Failed to allocate memory for PDU list.\n");
            return NULL;
        }
    }

    for (int i = 0; i < n && allocated < max_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[allocated];

        if (!pdu) {
            printf("Error: Failed to allocate memory for PDU.\n");
            free(pdu_list);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rand() % 1000 + 1;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;

        allocated++;
    }

    if (pdu_list && remaining > allocated) {
        free(pdu_list);
    }

    return pdu_list;
}

