                   (pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG ? "Enabled" : "Disabled"));
        }

        free(pdu_list);
    } else {
        printf("Failed to create PDU list.\n");
    }

    return 0;
}
