    json_object *config_json = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int retry_count = 0;
    int max_retries = 5;
    double backoff_time = 1.0;

    while (1) {
        config_json = json_object_from_file("config.json");
        if (!config_json) {
            if (retry_count < max_retries) {
                printf("Failed to load configuration, retrying in %f seconds...\n", backoff_time);
                sleep((int)backoff_time);
                backoff_time *= 2.0;
                retry_count++;
            } else {
                json_object_put(config_json);
                return NULL;
            }
        }

        if (json_object_get_type(config_json, "rx_channels") != json_type_array || 
            json_object_get_type(config_json, "ue_ids") != json_type_array || 
            json_object_get_type(config_json, "crc_flags") != json_type_array) {
            printf("Invalid configuration format. Aborting.\n");
            json_object_put(config_json);
            return NULL;
        }

        int n_crc_indications = 0;
