typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST;

NFAPI_CRC_INDICATION_LIST* create_crc_indication_list(int initial_capacity) {
    NFAPI_CRC_INDICATION_LIST* list = (NFAPI_CRC_INDICATION_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!list) return NULL;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void crc_indication_list_free(NFAPI_CRC_INDICATION_LIST* list) {
    if (!list) return;
    for (int i = 0; i < list->size; ++i) free((void*)(&list->data[i].RX_UE_INFORMATION_TAG));
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* crc_indication_list_get(NFAPI_CRC_INDICATION_LIST* list, int index) {
    if (index < 0 || index >= list->size) return NULL;
    return &list->data[index];
}

int crc_indication_list_add(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!element) return -1;
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        list->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, (list->capacity * 2 + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity *= 2;
    }
    list->data[list->size] = *element;
    ++list->size;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST* list, int index) {
    if (index < 0 || index >= list->size) return -1;
    pthread_mutex_lock(&list->mutex);
    for (int i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }
    --list->size;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void crc_indication_list_print(NFAPI_CRC_INDICATION_LIST* list) {
    for (int i = 0; i < list->size; ++i) {
        printf("RX_UE_INFORMATION_TAG: %02x, RNTI: %d, CRCFLAG: %02x\n",
            list->data[i].RX_UE_INFORMATION_TAG,
            list->data[i].RNTI,
            list->data[i].CRC_INDICATION_REL8_TAG[0]);
    }
}
