#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    int RNTI;
    CRC_INDICATION_REL8_TAG rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

struct list {
    int size;
    struct list_node* head;
    pthread_mutex_t mutex;
};

NFAPI_CRC_INDICATION_PDU_T* nfa_list_create() {
    struct list* list = (struct list*)malloc(sizeof(struct list));
    if (!list) return NULL;

    list->size = 0;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void nfa_list_destroy(struct list* list) {
    struct list_node* current = list->head;
    while (current) {
        struct list_node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int nfa_list_add_element(struct list* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }

    struct list_node* new_node = (struct list_node*)malloc(sizeof(struct list_node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Out of memory
    }
    new_node->data = *element;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfa_list_get_element(struct list* list, int index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size || index < 0) {
        pthread_mutex_unlock(&list->mutex);
        return NULL; // Index out of bounds
    }

    struct list_node* current = list->head;
    for (int i = 0; i < index; i++) {
        if (!current) break;
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->mutex);
        return NULL; // Index out of bounds
    }

    NFAPI_CRC_INDICATION_PDU_T* result = &current->data;
    pthread_mutex_unlock(&list->mutex);

    return result;
}

int nfa_list_delete_element(struct list* list, int index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size || index < 0) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Index out of bounds
    }

    struct list_node* current = list->head;
    for (int i = 0; i < index; i++) {
        if (!current) break;
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Index out of bounds
    }

    struct list_node* temp = current;
    current = current->next;
    free(temp);

    list->size--;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int nfa_list_sort_by_RNTI(struct list* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is empty
    }

    struct list_node* current = list->head;
    while (current) {
        struct list_node* next = current->next;
        int RNTI1 = current->data.RNTI;
        int RNTI2 = 0;
        struct list_node* temp = current;
        current = next;
        while (current) {
            if (current->data.RNTI < RNTI1) {
                RNTI1 = current->data.RNTI;
                temp = current;
            }
            current = current->next;
        }

        NFAPI_CRC_INDICATION_PDU_T swap_temp = temp->data;
        temp->data = list->head->data;
        list->head->data = swap_temp;

        pthread_mutex_unlock(&list->mutex);
    }

    return 0;
}
