int get_employee_info(int supervisor_id, char **employee_name, char **city, char **address) {
    // Open database connection
    int db_connection = 0;

    // Prepare query
    char *query = "SELECT employee_name, city, address FROM Employees WHERE supervisor_id = ?";
    sqlite3_stmt *stmt;

    // Execute query
    if(sqlite3_prepare_v2(db_connection, query, strlen(query), &stmt, NULL) != SQLITE_OK)
        return -1;

    // Bind parameter
    sqlite3_bind_int(stmt, 1, supervisor_id);

    // Fetch and retrieve data
    int rows = sqlite3_step(stmt);
    if(rows == SQLITE_ROW) {
        *employee_name = (char *)sqlite3_column_text(stmt, 0);
        *city = (char *)sqlite3_column_text(stmt, 1);
        *address = (char *)sqlite3_column_text(stmt, 2);
    }

    // Release resources
    sqlite3_finalize(stmt);
    sqlite3_close(db_connection);

    return 0;
}
