NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_ts(int n, pthread_mutex_t *mutex) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
