} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t len;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }
    list->len = 0;
    list->data = NULL;
    return list;
}

void free_list(List* list) {
    for (size_t i = 0; i < list->len; i++) {
        free(list->data[i].RX_UE_INFORMATION_TAG);
    }
    free(list->data);
    free(list);
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!list) {
        fprintf(stderr, "Error: List is NULL.\n");
        return -1;
    }

    size_t new_len = list->len + 1;
    NFAPI_CRC_INDICATION_PDU_T** new_data = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_len);
    if (!new_data) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }
    for (size_t i = list->len; i < new_len; i++) {
        new_data[i] = NULL;
    }
    for (size_t i = 0; i < list->len; i++) {
        new_data[i] = list->data[i];
    }
    new_data[list->len] = element;
    free(list->data);
    list->data = new_data;
    list->len = new_len;
    return 0;
}

int insert_element(List* list, size_t pos, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!list) {
        fprintf(stderr, "Error: List is NULL.\n");
        return -1;
    }

    size_t new_len = list->len + 1;
    NFAPI_CRC_INDICATION_PDU_T** new_data = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_len);
    if (!new_data) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }
    for (size_t i = list->len; i < new_len; i++) {
        new_data[i] = NULL;
    }
    size_t j;
    for (j = 0; j < pos; j++) {
        new_data[j] = list->data[j];
    }
    new_data[j] = element;
    for (; j < list->len; j++) {
        new_data[j + 1] = list->data[j];
    }
    free(list->data);
    list->data = new_data;
    list->len = new_len;
    return 0;
}

int remove_element(List* list, size_t pos) {
    if (!list || pos >= list->len) {
        fprintf(stderr, "Error: Out of bounds.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T** new_data = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * --list->len);
    if (!new_data) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }
    for (size_t i = 0; i < pos; i++) {
        new_data[i] = list->data[i];
    }
    for (; i < list->len; i++) {
        new_data[i] = list->data[i + 1];
    }
    free(list->data);
    list->data = new_data;
    return 0;
}

int update_element(List* list, size_t pos, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!list || pos >= list->len) {
        fprintf(stderr, "Error: Out of bounds.\n");
        return -1;
    }

    list->data[pos]->RX_UE_INFORMATION_TAG = strcpy(list->data[pos]->RX_UE_INFORMATION_TAG, element->RX_UE_INFORMATION_TAG);
    list->data[pos]->RNTI = element->RNTI;
    list->data[pos]->CRCFLAG = element->CRCFLAG;
    return 0;
}

