#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <randlib.h>

typedef struct {
    uint32_t ue_id;
    int rrc_stat;
    uint8_t mac_sched_algo;
} MAC_Statistics_T;

typedef struct {
    MAC_Statistics_T* stats;
    size_t len;
    size_t capacity;
} MAC_List_T;

void mac_list_init(MAC_List_T* list) {
    list->stats = NULL;
    list->len = 0;
    list->capacity = 10; // Start with a small initial capacity
}

int mac_list_insert(MAC_List_T* list, uint32_t ue_id, int rrc_stat, uint8_t mac_sched_algo) {
    if (list->len >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        MAC_Statistics_T* new_stats = realloc(list->stats, sizeof(MAC_Statistics_T) * new_capacity);
        if (!new_stats) return -1; // Memory allocation failed
        list->stats = new_stats;
        list->capacity = new_capacity;
    }
    MAC_Statistics_T stat;
    stat.ue_id = ue_id;
    stat.rrc_stat = rrc_stat;
    stat.mac_sched_algo = mac_sched_algo;
    list->stats[list->len] = stat;
    list->len++;
    return 0; // Success
}

size_t mac_list_size(const MAC_List_T* list) {
    return list->len;
}

void mac_list_free(MAC_List_T* list) {
    if (list->stats) free(list->stats);
    list->stats = NULL;
    list->len = 0;
    list->capacity = 0;
}
