void lte_phy_pdu_list_init(LTE_PHY_PDU_T** list, size_t initial_size) {
    *list = (LTE_PHY_PDU_T*)malloc(initial_size * sizeof(LTE_PHY_PDU_T));
}

void lte_phy_pdu_list_append(LTE_PHY_PDU_T* list, size_t* size, int RNTI, char* CRC_INDICATION_TAG) {
    if (*size == 0) {
        *size = 1;
    } else {
        *size *= 2;
    }

    LTE_PHY_PDU_T* new_list = (LTE_PHY_PDU_T*)realloc(list, *size * sizeof(LTE_PHY_PDU_T));

    new_list[*size - 1].RNTI = RNTI;
    new_list[*size - 1].CRC_INDICATION_TAG = CRC_INDICATION_TAG;
}

void lte_phy_pdu_list_remove(LTE_PHY_PDU_T** list, size_t* size) {
    *size /= 2;

    LTE_PHY_PDU_T* new_list = (LTE_PHY_PDU_T*)malloc(*size * sizeof(LTE_PHY_PDU_T));

    for (int i = 0; i < *size; i++) {
        new_list[i] = (*list)[i];
    }

    free(*list);
    *list = new_list;
}

void lte_phy_pdu_free(LTE_PHY_PDU_T* list, size_t size) {
    for (int i = 0; i < size; i++) {
        if (list[i].CRC_INDICATION_TAG != NULL) {
            free(list[i].CRC_INDICATION_TAG);
        }
    }

    free(list);
}

