    // simulate fetching RNTI values from an external data source
    *rntis = (int*)malloc(count * sizeof(int));

    for (size_t i = 0; i < count; i++) {
        (*rntis)[i] = rand() % 10000;
    }

    return NULL;
}

void generate_lte_phy_pdu_list(size_t size, int** rntis) {
    LTE_PHY_PDU_T* list = NULL;
    size_t list_size = 0;

    lte_phy_pdu_list_init(&list, size);

    for (size_t i = 0; i < size; i++) {
        int RNTI = (*rntis)[i];

        char* CRC_INDICATION_TAG = (char*)malloc(32 * sizeof(char));
        sprintf(CRC_INDICATION_TAG, "CRCFLAG_%d", rand() % 2);

        lte_phy_pdu_list_append(list, &list_size, RNTI, CRC_INDICATION_TAG);
    }

    // handle potential delay or failure in fetching RNTI values
    fetch_rnti_values(size, rntis);

    for (size_t i = 0; i < size; i++) {
        lte_phy_pdu_list_remove(&list, &list_size);
    }

    lte_phy_pdu_free(list, list_size);
