#include <pthread.h>

#define MAX_PDU 1000
#define VERBOSE_LEVEL DEBUG

typedef struct {
    int phy_rx_frame_tag;
    int rnti;
    int crc_indication_tag;
} LTE_PHY_PDU_T;

void* create_pdu_list(int max_pdu, int* pdu_count) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    LTE_PHY_PDU_T** pdu_list = (LTE_PHY_PDU_T**)malloc((max_pdu + 1) * sizeof(LTE_PHY_PDU_T*));
    for (int i = 0; i <= max_pdu; i++) {
        pdu_list[i] = (LTE_PHY_PDU_T*)malloc(sizeof(LTE_PHY_PDU_T));
        if (!pdu_list[i]) {
            pthread_mutex_unlock(&lock);
            fprintf(stderr, "Failed to allocate PDU structure at index %d\n", i);
            return NULL;
        }
    }

    for (int i = 0; i < max_pdu; i++) {
        pdu_list[i]->phy_rx_frame_tag = rand();
        pdu_list[i]->rnti = rand();
        pdu_list[i]->crc_indication_tag = rand();
        pthread_mutex_unlock(&lock);
        // Handle potential delays or interruptions in data input
    }

    *pdu_count = max_pdu;
    return (void*)pdu_list;
}

int free_pdu_list(void* pdu_list, int count) {
    if (!pdu_list) {
        return -1; // List is already freed
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < count; i++) {
        pthread_mutex_lock(&lock);
        free(((LTE_PHY_PDU_T**)pdu_list)[i]);
        pthread_mutex_unlock(&lock);
    }

    free(pdu_list);
    return 0;
}

void log_error(int level, const char* message) {
    if (level >= VERBOSE_LEVEL) {
        fprintf(stderr, "Error: %s\n", message);
    }
}

int main() {
    int pdu_count = 0;
    void* pdu_list = create_pdu_list(MAX_PDU, &pdu_count);

    // Use the PDU list...

    free_pdu_list(pdu_list, pdu_count);

    return 0;
}
