#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// TCP Packet structure with IP address, port number, payload size, and CRC indication
typedef struct {
    char ip[16];
    int port;
    int payload_size;
    bool crc_indication;
} TcpPacket;

// List of TCP Packets with dynamic memory allocation and thread safety
typedef struct {
    TcpPacket* packets;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} PacketList;

// Function to create a new packet list with the given initial capacity
PacketList* packet_list_create(int initial_capacity) {
    PacketList* list = (PacketList*)malloc(sizeof(PacketList));
    if (!list) return NULL; // Handle memory allocation failure

    list->capacity = initial_capacity;
    list->size = 0;

    list->packets = (TcpPacket*)calloc(initial_capacity, sizeof(TcpPacket));
    if (!list->packets) {
        free(list);
        return NULL; // Handle memory allocation failure
    }

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

// Function to append a new packet to the packet list
void packet_list_append(PacketList* list, TcpPacket* packet) {
    pthread_mutex_lock(&list->mutex); // Acquire lock for thread safety

    if (list->size == list->capacity) { // If list is full, reallocate memory
        list->packets = (TcpPacket*)realloc(list->packets, (list->capacity * 2 + 1) * sizeof(TcpPacket));
        list->capacity *= 2;
    }

    list->packets[list->size] = *packet; // Append new packet to the end of the list
    list->size++;

    pthread_mutex_unlock(&list->mutex); // Release lock for thread safety
}

// Function to remove a packet from the packet list at the given index
void packet_list_remove(PacketList* list, int index) {
    pthread_mutex_lock(&list->mutex); // Acquire lock for thread safety

    if (index >= list->size) { // If index is out of bounds, return without modifying the list
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Shift all packets after the removed one to fill the gap
    memmove(&list->packets[index], &list->packets[index + 1], (list->size - index - 1) * sizeof(TcpPacket));
    list->size--;

    pthread_mutex_unlock(&list->mutex); // Release lock for thread safety
}

// Function to free the packet list and its contents
void packet_list_free(PacketList* list) {
    if (!list) return; // Handle null pointer

    pthread_mutex_lock(&list->mutex); // Acquire lock for thread safety

    if (list->packets) { // Free dynamically allocated memory
        free(list->packets);
    }

    free(list);

    pthread_mutex_unlock(&list->mutex); // Release lock for thread safety
}
