```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

ListNode* create_pdu_list(int numPDUs) {
    ListNode *head = NULL;
    ListNode **list = &head;

    for (int i = 0; i < numPDUs; i++) {
        struct LTE_PDCP_PDU pdu;
        struct UE_Information_Tag_IE ue_info;
        int rrc_cause;

        // Create UE information tag IE
        ue_info.ue_id = i + 1;

        // Generate random RRC cause
        rrc_cause = rand() % (i + 2);

        // Create PDCP SDU with unique sequence number
        pdu.pdcpsdu.sequence_number = i * 2;

        // Add new PDU to the list
        if (*list == NULL) {
            *list = malloc(sizeof(ListNode));
            (*list)->data = pdu;
            (*list)->next = NULL;
        } else {
            ListNode *curr = *list;
            while (curr->next != NULL) {
                curr = curr->next;
            }
            curr->next = malloc(sizeof(ListNode));
            curr->next->data = pdu;
            curr->next->next = NULL;
        }

        // Check if list needs to be resized
        int size = 0;
        ListNode *currPDU = *list;
        while (currPDU != NULL) {
            size++;
            currPDU = currPDU->next;
        }
        if (size > 10) {
            ListNode **newList = malloc(sizeof(ListNode *) * size * 2);
            int j = 0;
            currPDU = *list;
            while (currPDU != NULL) {
                newList[j] = currPDU;
                currPDU = currPDU->next;
                j++;
            }
            for (int i = j; i < 2 * size; i++) {
                newList[i] = NULL;
            }
            *list = newList[0];
            for (int i = 1; i < 2 * size - 1; i++) {
                newList[i]->next = newList[i + 1];
            }
            free(newList);
        }
    }

    return head;
}

void free_pdu_list(ListNode* head) {
    ListNode *currPDU = head;
    while (currPDU != NULL) {
        ListNode *next = currPDU->next;
        free(currPDU);
        currPDU = next;
    }
}
