    uint8_t  dl_sch_allocation;
} MAC_Configuration_Specific_Information;

typedef struct {
    uint16_t num_cells;
    MAC_Configuration_Specific_Information specific_info[];
} LTE_MAC_Configuration_T;

void initialize_mac_configurations(LTE_MAC_Configuration_T *configs, size_t num_configs) {
