    configs->num_cells = 10; // Assume a fixed number of cells for simplicity

    for (size_t i = 0; i < num_configs; ++i) {
        configs->specific_info[i].cell_id = rand() % 256; // Random cell ID
        configs->specific_info[i].mac_version = rand() % 3 + 1; // Random MAC version
        configs->specific_info[i].dl_sch_allocation = rand() % 256; // Random DL SCH allocation
    }
}

int load_configurations_from_json(const char *json_file_path, LTE_MAC_Configuration_T **configs) {
    FILE *file = fopen(json_file_path, "r");
    if (!file) {
        perror("Failed to open JSON file");
        return -1;
    }

    json_object *json_configs = json_object_from_file(file);
    if (!json_configs) {
        fclose(file);
        return -1;
    }

    size_t num_configs = json_object_array_length(json_configs);
    *configs = (LTE_MAC_Configuration_T *)malloc((num_configs + 1) * sizeof(LTE_MAC_Configuration_T));
    if (!*configs) {
        json_object_free_string(json_configs);
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < num_configs; ++i) {
        json_object *config_json = json_object_array_get_idx(json_configs, i);
        LTE_MAC_Configuration_T *config = &(*configs)[i];

        config->num_cells = json_object_get_int(json_object_object_get_value(config_json, "num_cells"));
        MAC_Configuration_Specific_Information specific_info;
        specific_info.cell_id = json_object_get_int(json_object_object_get_value(config_json, "specific_info.cell_id"));
        specific_info.mac_version = json_object_get_int(json_object_object_get_value(config_json, "specific_info.mac_version"));
        specific_info.dl_sch_allocation = json_object_get_int(json_object_object_get_value(config_json, "specific_info.dl_sch_allocation"));

        config->specific_info[0].cell_id = specific_info.cell_id;
        config->specific_info[0].mac_version = specific_info.mac_version;
        config->specific_info[0].dl_sch_allocation = specific_info.dl_sch_allocation;

        json_object_free_string(config_json);
    }

    json_object_free_string(json_configs);
    fclose(file);

    return 0;
}

int main() {
    LTE_MAC_Configuration_T *configs = NULL;
    int result = load_configurations_from_json("config.json", &configs);
    if (result < 0) {
        // Handle error
    } else {
        // Process configurations
    }

    free(configs);

    return 0;
}
