void init_lte_ue_list(int **ue_list, int *ue_list_size, int max_ues) {
    // Initialize the ue_list with NULL values
    for (int i = 0; i < max_ues; i++) {
        (*ue_list)[i] = malloc(sizeof(lte_ue_context));
        if (!(*ue_list)[i]) {
            printf("Memory allocation failed!\n");
            return;
        }
        (*(*ue_list)[i]).ue_id = -1;
        (*(*ue_list)[i]).cell_id = -1;
        (*(*ue_list)[i]).rssi = 0.0;
        (*(*ue_list)[i]).sinr = 0.0;
    }
    *ue_list_size = max_ues;
}

// Function to sort the LTE UE context list based on UE ID in ascending order
void sort_lte_ue_list(int **ue_list, int ue_list_size) {
    int i, j;
    for (i = 0; i < ue_list_size - 1; i++) {
        for (j = i + 1; j < ue_list_size; j++) {
            if ((*(*ue_list)[i]).ue_id > (*(*ue_list)[j]).ue_id) {
                // Swap UE contexts
                lte_ue_context temp = *((*ue_list)[i]);
                (*ue_list)[i] = (*ue_list)[j];
                (*ue_list)[j] = &temp;
            }
        }
    }
}

// Function to add a new LTE UE context to the list
void add_lte_ue(int **ue_list, int *ue_list_size) {
    if (*ue_list_size < 10000) {
        lte_ue_context* new_ue = malloc(sizeof(lte_ue_context));
        if (!new_ue) {
            printf("Memory allocation failed!\n");
            return;
        }
        printf("Enter UE ID: ");
        scanf("%d", &new_ue->ue_id);
        printf("Enter Cell ID: ");
        scanf("%d", &new_ue->cell_id);
        printf("Enter RSSI value: ");
        scanf("%lf", &new_ue->rssi);
        printf("Enter SINR value: ");
        scanf("%lf", &new_ue->sinr);
        (*ue_list)[*ue_list_size] = new_ue;
        *ue_list_size += 1;
    } else {
        printf("List is full! Cannot add more UE contexts.\n");
    }
}

// Function to update an existing LTE UE context in the list
void update_lte_ue(int **ue_list, int ue_list_size) {
    int ue_id;
    printf("Enter UE ID to update: ");
    scanf("%d", &ue_id);
    for (int i = 0; i < ue_list_size; i++) {
