            printf("Invalid UE ID: %d. Using default.\n", list[i].ue_id);
            list[i].ue_id = MIN_UID;
        }
        list[i].rrc_state = rand() % (MAX_RRC_STATE - MIN_RRC_STATE + 1) + MIN_RRC_STATE;
        if (list[i].rrc_state < MIN_RRC_STATE || list[i].rrc_state > MAX_RRC_STATE) {
            printf("Invalid RRC state: %d. Using default.\n", list[i].rrc_state);
            list[i].rrc_state = 0;
        }
        switch (list[i].rrc_state) {
            case 0:
                list[i].tb_size = rand() % (MAX_TB_SIZE - MIN_TB_SIZE + 1) + MIN_TB_SIZE;
                break;
            case 1:
                list[i].tb_size = rand() % ((MAX_TB_SIZE - MIN_TB_SIZE) / 2 + 1) + MIN_TB_SIZE;
                break;
            default:
                list[i].tb_size = rand() % ((MAX_TB_SIZE - MIN_TB_SIZE) / 3 + 1) + MIN_TB_SIZE;
        }
    }
