#define NFAPI_CRC_INDICATION_PDU_T 1000
#define LTE_PHY_MEASUREMENTS 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int UE_INDEX;
    struct {
        time_t timestamp;
        double RSRP;
        double SINR;
    } PHRs[5];
} LTE_PHY_MEASUREMENTS;

NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu_ts;
LTE_PHY_MEASUREMENTS *lte_phy_measurements;

int init_nfapi_crc_indication_pduTs(int N) {
    nfapi_crc_indication_pdu_ts = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        nfapi_crc_indication_pdu_ts[i].RX_UE_INFORMATION_TAG = rand() % 100;
        nfapi_crc_indication_pdu_ts[i].RNTI = rand() % 100;
    }
    return 0;
}

int init_lte_phy_measurements(int M) {
    lte_phy_measurements = (LTE_PHY_MEASUREMENTS *)malloc(M * sizeof(LTE_PHY_MEASUREMENTS));
    for (int i = 0; i < M; i++) {
        lte_phy_measurements[i].UE_INDEX = rand() % 100;
        for (int j = 0; j < 5; j++) {
            lte_phy_measurements[i].PHRs[j].timestamp = time(NULL) + j;
            lte_phy_measurements[i].PHRs[j].RSRP = (double)rand() / RAND_MAX * 30;
            lte_phy_measurements[i].PHRs[j].SINR = (double)rand() / RAND_MAX * 20;
        }
    }
    return 0;
}

int dns_resolution(const char* hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int s;

    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM; // TCP
    hints.ai_protocol = IPPROTO_TCP;

    s = getaddrinfo(hostname, NULL, &hints, &res);
    if (s != 0) {
        return -1;
    }

    if (res == NULL || res->ai_addr == NULL) {
        return -2;
    }

    *ip_address = (u_char *)inet_ntop(AF_INET, &((struct sockaddr_in *)res->ai_addr)->sin_addr, ip_address, INET6_ADDRSTRLEN);
    freeaddrinfo(res);

    if (*ip_address == NULL) {
        return -3;
    }

    return 0;
}

int main() {
    init_nfapi_crc_indication_pduTs(NFAPI_CRC_INDICATION_PDU_T);
    init_lte_phy_measurements(LTE_PHY_MEASUREMENTS);

    u_char *ip_address;
    int status = dns_resolution("example.com", &ip_address);

    if (status != 0) {
        printf("DNS resolution failed with error code %d.\n", -status);
    } else {
        printf("The IP address is: %s\n", ip_address);
    }

    return 0;
}
