#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_list(int num_elements);
void add_crc_indication_pdu_batch(NFAPI_CRC_INDICATION_PDU_T **list, int **num_elements, int batch_size);
void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, int *num_elements);

int main() {
    NFAPI_CRC_INDATION_PDU_T *list = NULL;
    int num_elements = 0;

    // Initialize random seed
    srand(time(NULL));

    // Create a list with initial capacity of 100
    list = create_crc_indication_pdu_list(100);
    if (!list) {
        return -1; // Memory allocation failed
    }

    // Add CRC indication PDU structures in batches of 10
    for (int i = 0; i < 5; i++) {
        add_crc_indication_pdu_batch(&list, &num_elements, 10);
    }

    // Print the list contents
    for (int i = 0; i < num_elements; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRCFLAG);
    }

    // Free the memory
    free_crc_indication_pdu_list(&list, &num_elements);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_list(int num_elements) {
    if (num_elements > 1000) {
        printf("Error: Maximum number of elements exceeded.\n");
        return NULL; // Return error
    }

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Error: Memory allocation failed.\n");
        return NULL; // Return error
    }

    for (int i = 0; i < num_elements; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list[i].RNTI = rand() % 100;
        list[i].CRCFLAG = rand() & 1; // Set CRC flag randomly
    }

    return list;
}

void add_crc_indication_pdu_batch(NFAPI_CRC_INDICATION_PDU_T **list, int **num_elements, int batch_size) {
    if (*num_elements + batch_size > 1000) {
        printf("Error: Attempted to exceed maximum number of elements.\n");
        return; // Return error
    }

    for (int i = 0; i < batch_size; i++) {
        (*list)[(*num_elements)].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[(*num_elements)].RNTI = rand() % 100;
        (*list)[(*num_elements)].CRCFLAG = rand() & 1; // Set CRC flag randomly
        (*num_elements)++;
    }
}

void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, int *num_elements) {
    for (int i = 0; i < *num_elements; i++) {
        free(&((*list)[i]));
    }

    free(*list);
    *list = NULL;
    *num_elements = 0;
}
