    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    LTE_RRC_Capability_Information *rrc_capabilities = (LTE_RRC_Capability_Information *)malloc(sizeof(LTE_RRC_Capability_Information) * 100); // Initial allocation for 100 structures
