        double elapsed_time = ((double)(start_time.tv_sec - start_time.tv_sec)) + ((double)(start_time.tv_nsec - start_time.tv_nsec)) / 1000000000.0;
        if (elapsed_time >= 1.0) {
            rate_limit = 50; // Reset the rate limit every second
        } else {
            rate_limit = 50 / elapsed_time; // Dynamically adjust the rate limit based on system load
        }

        for (int i = 0; i < rate_limit && structure_count < max_structures_per_second; i++) {
            LTE_RRC_Capability_Information *rrc_capability;
            if ((rrc_capabilities + structure_count) % 100 == 0) {
