                rrc_capabilities = (LTE_RRC_Capability_Information *)realloc(rrc_capabilities, sizeof(LTE_RRC_Capability_Information) * (structure_count + 100));
            }
            rrc_capability = &rrc_capabilities[structure_count];
            rrc_capability->ue_id = rand() % 0x10000; // Generate a random UE ID within the valid range
            for (int j = 0; j < max_supported_features; j++) {
                rrc_capability->supported_features[j] = rand() % 2; // Randomly set supported features to 0 or 1
            }
            structure_count++;

            if (rrc_capability->ue_id > 0xFFFF || rrc_capability->ue_id < 0x0001) { // Validate UE ID
                free(rrc_capabilities);
                return -EINVAL;
            }
        }

        clock_gettime(CLOCK_REALTIME, &start_time);

        if (structure_count >= max_structures_per_second) {
            break; // Stop creating structures once the rate limit is exceeded
        }
    }

    free(rrc_capabilities);
    return 0;
}
