// Dynamic list to store structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
    int capacity;
    pthread_mutex_t lock;
} List;

// Initialize the list with a default capacity and create error handling for memory allocation failures
List* init_list(int capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL; // Handle malloc failure

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = capacity;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
List* generate_list(int num_elements) {
    List* list = init_list(10000); // Initialize with a default capacity

    if (!list) return NULL; // Handle malloc failure

    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T new_element;
        strcpy(new_element.RX_UE_INFORMATION_TAG, "VALID_RX_UE_INFORMATION_TAG");
        new_element.RNTI = rand();
        new_element.CRCFLAG = rand() % 2;

        pthread_mutex_lock(&list->lock);
        if (list->size >= list->capacity) {
            int new_capacity = list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_elements) {
                pthread_mutex_unlock(&list->lock);
                return NULL; // Handle realloc failure
            }
            list->capacity = new_capacity;
            list->elements = new_elements;
        }

        list->elements[list->size++] = new_element;

        pthread_mutex_unlock(&list->lock);
    }

    return list;
}

// Function to save the list to a file in binary format
int save_list(List* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return 0; // Handle file open failure

    int size = list->size;
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T element = list->elements[i];
        fwrite(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
    return 1;
}

// Function to load the list from a file in binary format
List* load_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL; // Handle file open failure

    int size;
    fread(&size, sizeof(int), 1, file);

    List* list = init_list(size); // Initialize with the loaded capacity
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T element;
        fread(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        pthread_mutex_lock(&list->lock);
        list->elements[list->size++] = element;
        pthread_mutex_unlock(&list->lock);
    }

    fclose(file);

    return list;
}

// Function to validate the integrity of the loaded data by comparing checksums
int validate_list(List* list) {
    int total_checksum = 0;
    for (int i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T element = list->elements[i];
        int checksum = crc16(element.RX_UE_INFORMATION_TAG, strlen(element.RX_UE_INFORMATION_TAG)) ^
            (element.RNTI << 8) ^ (element.CRCFLAG << 16);
        if (checksum != total_checksum) return 0; // Checksum mismatch
        total_checksum = checksum;
    }

    return 1; // Data integrity validated
}

int main() {
    // Example usage:
    List* list = generate_list(1000); // Generate a list of 1000 NFAPI_CRC_INDICATION_PDU_T structures

    if (!list) return -1; // Handle malloc failure

    int save_status = save_list(list, "example.bin"); // Save the list to a file
    if (save_status == 0) return -2; // Handle file write failure

    List* loaded_list = load_list("example.bin");
    if (!loaded_list) return -3; // Handle file read failure or malloc failure

    int validate_status = validate_list(loaded_list); // Validate the integrity of the loaded data
    if (validate_status == 0) return -4; // Checksum mismatch or other validation failure

    return 0;
}

