// Function to get a random RNTI value from an external data source
uint16_t get_random_rnti(void);

void populate_pdu_list(int max_structs, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    int num_structs = 0;

    while (num_structs < max_structs) {
        pthread_mutex_lock(&lock);

        if (pdu_list == NULL || num_structs >= max_structs) {
            pdu_list = realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (max_structs + 1000));
            if (pdu_list == NULL) {
                pthread_mutex_unlock(&lock);
                return;
            }
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[num_structs];
        pdu->rx_ue_information_tag = (RX_UE_INFORMATION_TAG){};
        pdu->rnti.rnti = get_random_rnti();
        pdu->crc_indication_rel8_tag.crcflag = rand() % 256;

        if (callback) {
            callback(pdu);
        }

        pthread_mutex_unlock(&lock);

        num_structs++;
    }

    free(pdu_list);
