void create_and_populate_list(int N, int max_buffer_size) {
    // Initialize list and buffer
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int *buffer_sizes = NULL;
    int total_size = 0;
    int i, j, current_index = 0;

    // Create a map for storing metadata related to each structure in the list
    FILE *metadata_file = fopen("metadata.txt", "wb");
    if (metadata_file == NULL) {
        printf("Failed to open metadata file.\n");
        return;
    }

    // Open database connection for storing metadata
    int db_fd = db_connect();
    if (db_fd < 0) {
        printf("Failed to connect to database.\n");
        return;
    }

    // Start timer for logging purposes
    clock_t start_time = clock();

    // Create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
    while (current_index < N && total_size <= max_buffer_size) {
        // Allocate memory for new PDU structure
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pdu == NULL) {
            printf("Memory allocation failed.\n");
            continue;
        }

        // Initialize PDU structure with random values
        new_pdu->RX_UE_INFORMATION_TAG = rand();
        new_pdu->RNTI = rand();
        new_pdu->CRCFLAG = rand();

        // Update buffer sizes and total size
        int buffer_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        buffer_sizes = realloc(buffer_sizes, (current_index + 1) * sizeof(int));
        if (buffer_sizes == NULL) {
            printf("Memory allocation failed.\n");
            continue;
        }
        for (i = current_index; i > 0; i--) {
            buffer_sizes[i] = buffer_sizes[i - 1];
        }
        buffer_sizes[0] = buffer_size;
        total_size += buffer_size;

        // Store metadata in file
        fwrite(&new_pdu->RX_UE_INFORMATION_TAG, sizeof(int), 1, metadata_file);
        fwrite(&new_pdu->RNTI, sizeof(int), 1, metadata_file);
        fwrite(&new_pdu->CRCFLAG, sizeof(int), 1, metadata_file);

        // Store metadata in database
        int result = db_store_metadata(new_pdu->RX_UE_INFORMATION_TAG, new_pdu->RNTI, new_pdu->CRCFLAG, db_fd);
        if (result < 0) {
            printf("Failed to store metadata in database.\n");
            continue;
        }

        // Add PDU structure to list
        NFAPI_CRC_INDICATION_PDU_T *previous_list = list;
        list = realloc(list, (current_index + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list == NULL) {
            printf("Memory allocation failed.\n");
            free(previous_list);
            continue;
        }
        for (j = current_index; j > 0; j--) {
            list[j] = list[j - 1];
        }
        list[0] = *new_pdu;

        // Increment index and buffer sizes
        current_index++;
    }

    // Close database connection and metadata file
    db_close(db_fd);
    fclose(metadata_file);

    // Log completion time and total size
    clock_t end_time = clock();
    printf("List created with %d PDUs of total size %d bytes in %f seconds.\n", N, total_size, (double)(end_time - start_time) / CLOCKS_PER_SEC);
}
