int ue_count = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* allocate_ue_context() {
    LTE_UE_Context* new_ue = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!new_ue) {
        return NULL;
    }
    bzero(new_ue, sizeof(LTE_UE_Context));
    return new_ue;
}

void deallocate_ue_context(void* ptr) {
    free(ptr);
}

int create_ue_context_list(int num_uws) {
    int i;
    for (i = 0; i < num_uws; i++) {
        LTE_UE_Context* new_ue = allocate_ue_context();
        if (!new_ue) {
            break;
        }
        ue_list = realloc(ue_list, (ue_count + 1) * sizeof(LTE_UE_Context));
        if (!ue_list) {
            deallocate_ue_context(new_ue);
            break;
        }
        bcopy(&new_ue, &ue_list[ue_count], sizeof(LTE_UE_Context));
        ue_count++;
    }
    return i;
}

void* worker_function(void* ptr) {
    int num_uws = *(int*)ptr;
    create_ue_context_list(num_uws);
    // Your code goes here
    pthread_exit(NULL);
}

void start_workers(int num_uws) {
    int i;
    pthread_t threads[num_uws];
    for (i = 0; i < num_uws; i++) {
        int* ptr = &num_uws;
        if (pthread_create(&threads[i], NULL, worker_function, ptr)) {
            perror("pthread_create");
            exit(1);
        }
    }
    for (i = 0; i < num_uws; i++) {
        if (pthread_join(threads[i], NULL)) {
            perror("pthread_join");
            exit(1);
        }
    }
}

int main() {
    int num_uws = atoi(getenv("NUM_UWS"));
    start_workers(num_uws);
    return 0;
}
