#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

#define MAX_BUFFER_SIZE 1024*1024 // adjust according to your needs
#define N_MAX 10000

typedef struct {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    int size;
    int capacity;
} PDU_LIST;

PDU_LIST create_pdu_list(int max_buffer_size) {
    PDU_LIST list = (PDU_LIST)malloc(sizeof(PDU_LIST));
    list->size = 0;
    list->capacity = 10; // initial capacity
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return list;
}

void destroy_pdu_list(PDU_LIST* list) {
    if (*list) {
        free((*list)->pdus);
        free(*list);
        *list = NULL;
    }
}

int pdu_list_reserve_space(PDU_LIST* list, int new_size) {
    if (new_size > list->capacity) {
        int capacity = list->capacity + (list->capacity >> 1); // grow by half
        void *new_data = realloc(list->pdus, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1; // memory allocation failed
        list->pdus = new_data;
        list->capacity = capacity;
    }
    return 0;
}

int add_pdu(PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->size >= list->capacity) {
        int ret = pdu_list_reserve_space(list, list->size + list->size >> 1); // grow by half
        if (ret == -1) return -1; // memory allocation failed
    }
    memcpy(&list->pdus[list->size++], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return 0;
}

void purge_stale_pdus(PDU_LIST* list) {
    int i = 0;
    while (i < list->size) {
        if (/* check for stale PDUs */) {
            memmove(&list->pdus[i], &list->pdus[i+1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
        } else {
            i++;
        }
    }
}

void log_event(char* message) {
    // implement logging functionality here
    printf("%s\n", message);
}
