        unsigned char* payload = (unsigned char*)malloc(256);
        for (int j = 0; j < 256; j++) {
            payload[j] = (unsigned char)(mib_list[i].ssb_index + j) % 256;
        }
        mib_list[i].mib_payload = payload;

        rach_requests[i] = (LTE_RACH_REQUEST_T*)malloc(sizeof(LTE_RACH_REQUEST_T));
        rach_requests[i]->preamble_id = rand() % 100; // random preamble ID
        rach_requests[i]->rach_channel = rand() % 2; // random RACH channel

    }

    fclose(ssid_map_file);
    for (i = 0; i < num_ue; i++) {
        free(rach_requests[i]);
    }
    free(rach_requests);
    free(mib_list);
}
