// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* createCRCIndicationList(int numStructures) {
    // Initialize the head pointer for the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Check if the number of structures exceeds the maximum allowed (1000)
    if (numStructures > 1000) {
        printf("Error: Maximum number of structures exceeded. Aborting.\n");
        return NULL; // Return NULL to indicate error
    }

    // Iterate through each structure
    for (int i = 0; i < numStructures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newStruct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set the RX_UE_INFORMATION_TAG and RNTI values
        newStruct->RX_UE_INFORMATION_TAG = i;
        newStruct->RNTI = i % 2; // Even RNTI values should have CRCFLAG set to 0, and odd RNTI values should have CRCFLAG set to 1

        // Set the CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        newStruct->CRC_INDICATION_REL8_TAG = (newStruct->RNTI % 2) ? 1 : 0;

        // Log the creation of each structure, including the RNTI and CRCFLAG values
        FILE* logFile = fopen("log.txt", "a");
        if (logFile != NULL) {
            fprintf(logFile, "Created structure with RNTI %d and CRCFLAG %d\n", newStruct->RNTI, newStruct->CRC_INDICATION_REL8_TAG);
            fclose(logFile);
        }

        // Insert the new structure into the linked list
        if (head == NULL) {
            head = newStruct;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newStruct;
        }
    }

    return head; // Return the head of the linked list
}
