// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void createPduList(int n, struct NFAPI_CRC_INDICATION_PDU_T ***list) {
    if (!hasEnoughMemory(n * sizeof(struct NFAPI_CRC_INDICATION_PDU_T))) {
        printf("Not enough memory to create the list.\n");
        return;
    }

    *list = (struct NFAPI_CRC_INDICATION_PDU_T **)malloc(n * sizeof(struct NFAPI_CRC_INDICATION_PDU_T *));
    for (int i = 0; i < n; i++) {
        (*list)[i] = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        // Initialize structures here
    }
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
void addPdu(int n, struct NFAPI_CRC_INDICATION_PDU_T ***list, int index) {
    if (index < 0 || index >= n) {
        printf("Index out of bounds.\n");
        return;
    }

    // Check if memory is available before allocating
    if (!hasEnoughMemory(sizeof(struct NFAPI_CRC_INDICATION_PDU_T))) {
        printf("Not enough memory to add the PDU.\n");
        return;
    }

    (*list)[index] = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    // Initialize structure here
}

// Function to remove an existing NFAPI_CRC_INDICATION_PDU_T structure from the list
void removePdu(int n, struct NFAPI_CRC_INDICATION_PDU_T ***list, int index) {
    if (index < 0 || index >= n) {
        printf("Index out of bounds.\n");
        return;
    }

    free((*list)[index]);
    (*list)[index] = NULL;

    // Shrink the list to accommodate freed memory
    int i = 0;
    for (int j = 0; j < n; j++) {
        if ((*list)[j] != NULL) {
            (*list)[i++] = (*list)[j];
        }
    }

    n = i;
}

// Function to clear all elements from the list
void clearList(int n, struct NFAPI_CRC_INDICATION_PDU_T ***list) {
    for (int i = 0; i < n; i++) {
        free((*list)[i]);
        (*list)[i] = NULL;
    }
}

int main() {
