    struct NFAPI_CRC_INDICATION_PDU_T **list;

    createPduList(n, &list);

    // Example usage of addPdu and removePdu functions
    for (int i = 0; i < n; i++) {
        addPdu(n, &list, i);
    }

    for (int i = 0; i < n / 2; i++) {
        removePdu(n, &list, i);
    }

    clearList(n, &list);

    return 0;
}
