#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_LIST_SIZE 10000
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int n, FILE *fp) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL;
    }

    int crcflag = 0;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        pdu->RX_UE_INFORMATION_TAG = i % 256;
        if (fp) {
            fscanf(fp, "%d", &pdu->RNTI);
            fscanf(fp, "%d", &pdu->CRC_INDICATION_REL8_TAG);
        } else {
            pdu->RNTI = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
            pdu->CRC_INDICATION_REL8_TAG = i % 256;
        }
        if (i % 4 == 0) {
            crcflag = 1;
        } else {
            crcflag = 0;
        }
        pdu->CRCFLAG = crcflag;
        pdu->timestamp = time(NULL);
    }

    return list;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    if (!list || n <= 0) {
        return;
    }
    free(list);
}

int main() {
    FILE *fp = fopen("data.csv", "r");
    int n = MAX_LIST_SIZE;
    NFAPI_CRC_INDICATION_PDU_T* list = create_crc_indication_list(n, fp);
    if (!list) {
        printf("Allocation failed.\n");
        return 1;
    }

    fclose(fp);

    // Use the list here...
    free_crc_indication_list(list, n);

    return 0;
}
