        strcpy(ue_contexts[i].ue_id, "UE_ID_");
        strcat(strcat(ue_contexts[i].ue_id, (i + 1) < 10 ? "00" : (i + 1) < 100 ? "0" : ""), (i + 1) % 26 != 0 ? "a" : "z");

        ue_contexts[i].report.measurement_type = rand() % 2;  // Randomly set measurement type
        ue_contexts[i].report.measurement_value = (double)rand() / RAND_MAX;

        // Randomly decide whether to include a Measurement Control with MeasurementObjectList
        if (rand() % 2) {
            ue_contexts[i].control.present = 1;
            // Allocate memory for Measurement Object List and fill it with random objects
            ue_contexts[i].control.list_size = rand() % 5 + 1;
            ue_contexts[i].control.list = (MeasurementObject**)malloc(ue_contexts[i].control.list_size * sizeof(MeasurementObject*));
            for (size_t j = 0; j < ue_contexts[i].control.list_size; j++) {
                MeasurementObject* measurement_object = (MeasurementObject*)malloc(sizeof(MeasurementObject));
                measurement_object->id = rand() % 100;
                measurement_object->value = (double)rand() / RAND_MAX;
                ue_contexts[i].control.list[j] = measurement_object;
            }
        } else {
            ue_contexts[i].control.present = 0;
            ue_contexts[i].control.list = NULL;
        }
    }

    // Store UE context information in the database
    fseek(db_fp, 0, SEEK_END);
    for (int i = 0; i < num_ue; i++) {
        fwrite(&ue_contexts[i], sizeof(LTEUEContext), 1, db_fp);
    }

    // Free memory allocated for measurement object list
    for (size_t j = 0; j < total_measurement_objects; j++) {
        free(measurement_objects[j]);
    }
    free(measurement_objects);

    return ue_contexts;
}
