#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define UE_ID_LENGTH 16
#define RACH_REQUEST_TAG_LENGTH 4

typedef struct {
    char ue_id[UE_ID_LENGTH];
    int preamble_id;
    char rach_request_tag[RACH_REQUEST_TAG_LENGTH];
} LTE_PHY_RACH_INDICATION;

LTE_PHY_RACH_INDICATION* create_rach_indication_list(int max_size) {
    LTE_PHY_RACH_INDICATION* list = (LTE_PHY_RACH_INDICATION*)malloc(max_size * sizeof(LTE_PHY_RACH_INDICATION));
    int list_size = 0;

    srand(time(NULL)); // Initialize random number generator

    for(int i = 0; i < max_size; i++) {
        LTE_PHY_RACH_INDICATION* current_indication = &list[i];

        do {
            // Generate a random UE ID
            char ue_id[UE_ID_LENGTH];
            for (int j = 0; j < UE_ID_LENGTH; j++) {
                sprintf(&ue_id[j], "%c", 'a' + rand() % 26);
            }

            current_indication->preamble_id = rand();
            current_indication->rach_request_tag[0] = 'R';
            current_indication->rach_request_tag[1] = 'A';
            current_indication->rach_request_tag[2] = 'C';
            current_indication->rach_request_tag[3] = '\0';

            strcpy(current_indication->ue_id, ue_id);
        } while (check_ue_id_duplicates(list, list_size) && list_size < max_size); // Check for duplicate UE IDs

        if (list_size >= max_size) {
            break; // Stop populating the list when it reaches the maximum size
        }

        list_size++;
    }

    return list;
}

int check_ue_id_duplicates(LTE_PHY_RACH_INDICATION* list, int list_size) {
    for(int i = 0; i < list_size - 1; i++) {
        for (int j = i + 1; j < list_size; j++) {
            if (strcmp(list[i].ue_id, list[j].ue_id) == 0) {
                return 1; // Found duplicate UE ID
            }
        }
    }

    return 0; // No duplicates found
