        if (new_connection == NULL) {
            // Handle memory allocation error
            printf("Memory allocation failed.\n");
            return;
        }

        int duplicate_found = 0;
        for (int j = 0; j < *num_connections; j++) {
            if (nodes[i] == connections_list[j]->node_id) {
                duplicate_found = 1;
                break;
            }
        }

        if (!duplicate_found) {
            new_connection->node_id = nodes[i];
            new_connection->connection_status = 'A'; // Assume all initial connections are active
            time_t current_time = time(NULL);
            new_connection->last_known_status_update_time = current_time;

            *num_connections += 1;
            connections_list = (NetworkNodeConnection**)realloc(connections_list, (*num_connections) * sizeof(NetworkNodeConnection*));
            if (connections_list == NULL) {
                // Handle memory reallocation error
                printf("Memory reallocation failed.\n");
                return;
            }

            connections_list[*num_connections - 1] = new_connection;
        } else {
            // Log error and skip duplicate entry
            printf("Duplicate node ID detected. Skipping...\n");
        }
    }

    // Monitor the network nodes
    time_t current_time = time(NULL);
    for (int i = 0; i < *num_connections; i++) {
        NetworkNodeConnection* connection = connections_list[i];
        time_t difference = difftime(current_time, connection->last_known_status_update_time);

        if (difference > 300) { // Monitor connections every 5 minutes
            printf("Warning: Connection to node %d has gone unmonitored for more than 5 minutes.\n", connection->node_id);
        }
    }
}
