#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 1000
#define MAX_EXTERNAL_IDS 10000
#define THRESHOLD 80

typedef struct {
    int UE_ID;
    int RACH_REQUEST_TAG;
    int PREAMBLE_ID;
} LTE_PHY_RACH_INDICATION;

void* my_malloc(size_t size) {
    return malloc(size);
}

void my_free(void* ptr) {
    free(ptr);
}

int main() {
    srand(time(NULL));

    // Allocate the list
    LTE_PHY_RACH_INDICATION** list = (LTE_PHY_RACH_INDICATION**)my_malloc(MAX_SIZE * sizeof(LTE_PHY_RACH_INDICATION*));

    int external_ids[MAX_EXTERNAL_IDS];
    for(int i=0; i<MAX_EXTERNAL_IDS; i++) {
        if(i%2==0) {
            external_ids[i] = rand() % 10000;
        } else {
            external_ids[i] = 0;
        }
    }

    // Validate and add the UE_IDs
    int used_ues[MAX_EXTERNAL_IDS];
    for(int i=0; i<MAX_EXTERNAL_IDS; i++) {
        if(external_ids[i] > 0) {
            bool found = false;
            for(int j=0; j<i; j++) {
                if(used_ues[j] == external_ids[i]) {
                    found = true;
                    break;
                }
            }
            if(!found) {
                used_ues[i] = external_ids[i];
            } else {
                used_ues[i] = -1;
            }
        } else {
            used_ues[i] = -1;
        }
    }

    // Create and populate the list
    int preamble_id=0;
    for(int i=0; i<MAX_SIZE && i < (MAX_EXTERNAL_IDS/2); i++) {
        if(list[i]) {
            free(list[i]);
        }
        list[i] = (LTE_PHY_RACH_INDICATION*)my_malloc(sizeof(LTE_PHY_RACH_INDICATION));
        list[i]->UE_ID = used_ues[i];
        list[i]->RACH_REQUEST_TAG = 0;
        list[i]->PREAMBLE_ID = preamble_id++;
    }

    // Dynamically resize the list if it reaches threshold
    int capacity = MAX_SIZE / 2;
    while(preamble_id < capacity) {
        if(list[capacity]) {
            free(list[capacity]);
        }
        list[capacity] = (LTE_PHY_RACH_INDICATION*)my_malloc(sizeof(LTE_PHY_RACH_INDICATION));
        list[capacity]->UE_ID = used_ues[preamble_id];
        list[capacity]->RACH_REQUEST_TAG = 0;
        list[capacity]->PREAMBLE_ID = preamble_id++;
        capacity *= 2;
    }

    // Log the final result
    FILE* log_file = fopen("result.log", "w");
    if(log_file) {
        for(int i=0; i<MAX_SIZE/2; i++) {
            fprintf(log_file, "%d %d %d\n", list[i]->UE_ID, list[i]->RACH_REQUEST_TAG, list[i]->PREAMBLE_ID);
        }
        fclose(log_file);
    }

    // Clean up
    for(int i=0; i<MAX_SIZE/2; i++) {
        free(list[i]);
    }
    my_free(list);

    return 0;
}
