int validate_json_config(json_object *config) {
    if (json_object_object_get_ex(config, "rx_channels", NULL) == NULL || 
        json_object_array_length(config->object["rx_channels"]) < 1) return -1;
    if (json_object_object_get_ex(config, "ue_ids", NULL) == NULL || 
        json_object_array_length(config->object["ue_ids"]) < 1) return -2;
    if (json_object_object_get_ex(config, "crc_flags", NULL) == NULL || 
        json_object_array_length(config->object["crc_flags"]) < 1) return -3;

    for (int i = 0; i < config->size["rx_channels"]; i++) {
        int rx_channel = json_object_array_get_int(config->object["rx_channels"], i);
        if (rx_channel < 0 || rx_channel > MAX_RX_CHANNELS) return -4;
    }

    for (int i = 0; i < config->size["ue_ids"]; i++) {
        int ue_id = json_object_array_get_int(config->object["ue_ids"], i);
        if (ue_id < 0 || ue_id > MAX_UES) return -5;
    }

    for (int i = 0; i < config->size["crc_flags"]; i++) {
        int crc_flag = json_object_array_get_bool(config->object["crc_flags"], i);
        if (!crc_flag && i > 0) return -6;
    }

    return 1;
}

NFAPI_CRC_INDICATION_PDU_T *populate_config(json_object *config, int count) {
    NFAPI_CRC_INDICATION_PDU_T *nfa_pi_crc_ind_pdu_t = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

