    for (int i = 0; i < count; i++) {
        nfa_pi_crc_ind_pdu_t[i].rnti = rand() % MAX_UES;
        nfa_pi_crc_ind_pdu_t[i].rx_ue_information_tag = rand() % MAX_RX_CHANNELS;
    }

    return nfa_pi_crc_ind_pdu_t;
}

void free_config(NFAPI_CRC_INDICATION_PDU_T *nfa_pi_crc_ind_pdu_t, int count) {
    if (!nfa_pi_crc_ind_pdu_t) return;

    free(nfa_pi_crc_ind_pdu_t);
}

int main() {
    // Initialize JSON service
    json_object *config = NULL;

    while (1) {
        config = get_config_from_json_service();

        if (config == NULL) {
            printf("Failed to retrieve configuration. Retrying in 10 seconds.\n");
