Write a C function that initializes and populates an array of `RadioResourceControlMessage` structures, each containing a valid `UEIdentifier` and `SRSConfiguration`, and a `CQIReport` with parameters derived from external JSON configuration files. The function should handle memory allocation failures and ensure that the data loaded from the JSON files is validated before use. Additionally, the function should support dynamic scaling to handle varying numbers of messages without significant performance degradation.

```c
#include <stdlib.h>
#include <stdio.h>
#include <json-c/json.h>

typedef struct {
    int UEIdentifier;
    int SRSConfiguration;
} UEInfo;

typedef struct {
    int CQI;
    int RI;
    int PMI;
} CQIReport;

typedef struct {
    UEInfo ue_info;
    CQIReport cqi_report;
} RadioResourceControlMessage;

void initialize_radio_resource_control_messages(int num_messages, RadioResourceControlMessage *messages) {
    // Load configuration from JSON file
    json_object *config = json_object_from_file("config.json");
    if (!config) {
        fprintf(stderr, "Failed to load configuration file!\n");
        exit(EXIT_FAILURE);
    }

    // Validate configuration
    if (!validate_configuration(config)) {
        fprintf(stderr, "Invalid configuration!\n");
        exit(EXIT_FAILURE);
    }

    // Seed the random number generator
    srand(time(NULL));

    for (int i = 0; i < num_messages; i++) {
        messages[i].ue_info.UEIdentifier = rand() % 1000 + 1;
        messages[i].ue_info.SRSConfiguration = rand() % 10 + 1;

        messages[i].cqi_report.CQI = get_cqi(config);
        messages[i].cqi_report.RI = get_ri(config);
        messages[i].cqi_report.PMI = get_pmi(config);

        // Error handling for memory allocation
        if (messages == NULL) {
            fprintf(stderr, "Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
    }

    json_object_put(config);
