    // Initialize the list with dynamically allocated memory for each structure
    NFAPI_CRC_INDICATION_PDU_T** crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!crc_indication_pdu_list) {
        return NULL; // Handle memory allocation failure
    }

    // Initialize the external data source for UE information
    int ue_info_available = 0;
    RX_UE_INFORMATION_TAG* ue_info_data = NULL;

