    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_indication_pdu) {
            return NULL; // Handle memory allocation failure
        }

        // Validate the RNTI value and ensure uniqueness
        uint16_t rnti;
        do {
            rnti = (uint16_t)(rand() % 65535 + 1); // Generate a random RNTI value between 1 and 65535
            crc_indication_pdu->rnti = rnti;

            // Validate the CRCFLAG and set it randomly
            uint8_t crcflag;
            do {
                crcflag = (uint8_t)(rand() % 2);
                crc_indication_pdu->crc_indication_rel8.crcflag = crcflag;
            } while (crcflag != 0 && crcflag != 1);

            // Validate the RNTI value and ensure uniqueness
            for (int j = 0; j < i; j++) {
                if (crc_indication_pdu_list[j]->rnti == rnti) {
                    free(crc_indication_pdu);
                    return NULL; // Handle duplicate RNTI value
                }
            }

            // Populate the RX_UE_INFORMATION_TAG field using the external data source for UE information
            if (!ue_info_available || !ue_info_data) {
                // Handle unavailable or invalid UE information data
                crc_indication_pdu->rx_ue_info = (RX_UE_INFORMATION_TAG){0}; // Set to default value
            } else {
                // Populate the RX_UE_INFORMATION_TAG field using the external data source for UE information
                crc_indication_pdu->rx_ue_info = ue_info_data[i % ue_info_data_size];
            }

            // Add the structure to the list
            crc_indication_pdu_list[i] = crc_indication_pdu;
        } while (false); // Ensure uniqueness of RNTI values

        // Handle any exceptions or errors encountered during creation and population of the list
    }

    return crc_indication_pdu_list;
}

