        printf("Invalid input parameters. num_pdu: %d, max_buffer_size: %d\n", num_pdu, max_buffer_size);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu) {
        printf("Memory allocation failed. num_pdu: %d, max_buffer_size: %d\n", num_pdu, max_buffer_size);
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < num_pdu; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = rand() % 100 + 1; // Randomly set RX_UE_INFORMATION_TAG
        pdu[i].RNTI = rand() % 100 + 1; // Randomly set RNTI
        pdu[i].CRC_INDICATION_REL8_TAG = rand() % 100 + 1; // Randomly set CRC_INDICATION_REL8_TAG
        pdu[i].CRCFLAG = (char)(rand() % 2); // Randomly set CRCFLAG

        if ((pdu[i].RX_UE_INFORMATION_TAG | pdu[i].RNTI | pdu[i].CRC_INDICATION_REL8_TAG) > max_buffer_size) {
            printf("Total size of SDUs exceeds maximum buffer size: %d\n", max_buffer_size);
