#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[256];
    int RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDATION_PDU_T *create_crc_indication_pdu(int n) {
    srand(time(NULL)); // seed for consistent random generation
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        strcpy(pdu[i].RX_UE_INFORMATION_TAG, "TAG"); // valid RX_UE_INFORMATION_TAG
        pdu[i].RNTI = rand() % 256; // random RNTI
        pdu[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (uint8_t)rand(); // random CRCFLAG
    }
    return pdu;
}

int find_max_port(char **ips, int n) {
    int max_port = -1;
    for (int i = 0; i < n; i++) {
        // helper function to parse IP and port from string
        int port = parse_ip_port(ips[i]);
        if (port > max_port)
            max_port = port;
    }
    return max_port;
}

// helper function to parse IP and port from string
int parse_ip_port(char *ip) {
    char *token = strtok(ip, ":");
    // assume the first token is the IP address and second token is the port number
    int port = atoi(token);
    return port;
}

void print_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int n) {
    for (int i = 0; i < n; i++) {
        printf("RX_UE_INFORMATION_TAG: %s\n", pdu[i].RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", pdu[i].RNTI);
        printf("CRCFLAG: 0x%x\n", pdu[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

int main() {
    int n = 1000; // maximum number of elements
    NFAPI_CRC_INDICATION_PDU_T *pdu = create_crc_indication_pdu(n);

    char **ips = read_ips_from_database(); // read IP addresses from database
    int max_port = find_max_port(ips, n);
    printf("IP address with the highest port: %d\n", max_port);

    print_crc_indication_pdu(pdu, n);

    free(pdu); // memory leak prevention

    return 0;
}

char **read_ips_from_database() {
    FILE *fp = fopen("ip_addresses.txt", "r");
    if (fp == NULL) {
        perror("Error opening file");
        return NULL;
    }

    char **ips = malloc(10000 * sizeof(char *));
    int n = 0;
    while (!feof(fp)) {
        char buffer[256];
        fgets(buffer, sizeof(buffer), fp);
        if (buffer[0] == '#') continue; // skip comments
        ips[n++] = strdup(buffer);
    }
    fclose(fp);

    // add error handling for invalid IP formats
    for (int i = 0; i < n; i++) {
        char *token = strtok(ips[i], ":");
        if (token == NULL || strlen(token) > 15) {
            printf("Invalid IP address: %s\n", ips[i]);
            free(ips[i]);
            --n;
        }
    }

    char **result = malloc((n + 1) * sizeof(char *));
    for (int i = 0; i < n; i++) {
        result[i] = ips[i];
    }
    result[n] = NULL;

    free(ips);
    return result;
}
