    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    for (i = 0; i < N; i++) {
        (*list)[i].ue_info.tag = 'R'; // Valid RX_UE_INFORMATION_TAG
        (*list)[i].rnti = rand() % 100 + 1; // Randomly set RNTI
        (*list)[i].crc_indication_rel8.crcflag = (rand() % 2); // Randomly set CRCFLAG

        if (N > MAX_N) {
            printf("Warning: List size exceeds maximum limit.\n");
        }
    }

    // Error handling for system memory limit exceed
    if (N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > SYSTEM_MAX_MEMORY_LIMIT) {
        fprintf(stderr, "System memory limit exceeded. Please reduce list size.\n");
        free(*list);
        *list = NULL;
    }
}

void sort_list_by_rnti(NFAPI_CRC_INDICATION_PDU_T **list, int N) {
    qsort(*list, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_fn);
}

int compare_fn(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_indication_pdu_t_a = *(NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_indication_pdu_t_b = *(NFAPI_CRC_INDICATION_PDU_T *)b;

    if (nfaapi_crc_indication_pdu_t_a->rnti < nfaapi_crc_indication_pdu_t_b->rnti) {
        return -1;
    }
    else if (nfaapi_crc_indication_pdu_t_a->rnti > nfaapi_crc_indication_pdu_t_b->rnti) {
        return 1;
    }

    return 0;
}

void remove_structure_by_rnti(NFAPI_CRC_INDICATION_PDU_T **list, int N, int rnti_to_remove) {
    // Mechanism to remove a specific structure from the list based on its RNTI
    for (int i = 0; i < N; i++) {
        if ((*list)[i].rnti == rnti_to_remove) {
            memmove(&(*list)[i], &(*list)[i + 1], (N - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            N--;
            break;
        }
    }
}

int find_and_return_index_of_structure_by_rnti(NFAPI_CRC_INDICATION_PDU_T **list, int N, int rnti_to_find) {
    for (int i = 0; i < N; i++) {
        if ((*list)[i].rnti == rnti_to_find) {
            return i;
        }
    }

    return -1; // Structure not found
}

void garbage_collection(NFAPI_CRC_INDICATION_PDU_T **list, int *N) {
    int i;
    for (i = 0; i < *N; i++) {
        if (!((*list)[i].ue_info.tag == 'R' && (*list)[i].rnti > 0)) {
            // Remove unused structures from the list
            memmove(&(*list)[i], &(*list)[i + 1], (*N - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            (*N]--;
        }
    }
}

int main() {
    int N = 10;
    NFAPI_CRC_INDICATION_PDU_T *list;

    create_and_populate_list(N, &list);

    sort_list_by_rnti(&list, N);

    remove_structure_by_rnti(&list, N, 5);

    printf("Structure at index %d: RNTI - %d\n", find_and_return_index_of_structure_by_rnti(&list, N, 3), list[find_and_return_index_of_structure_by_rnti(&list, N, 3)]->rnti);

    garbage_collection(&list, &N);

    return 0;
}

