#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STATS 10000
#define MAX_PACKETS 5000

typedef struct {
    int pdcchSearchSpaceId;
    int cceIndex;
    int crcFlag;
} PDCCH_Statistics;

PDCCH_Statistics *stats = NULL;
int statsCount = 0;
pthread_mutex_t statsMutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile = NULL;

void *malloc_statistic(int count) {
    PDCCH_Statistics *newStats = (PDCCH_Statistics *) malloc(sizeof(PDCCH_Statistics) * count);
    if (!newStats) {
        fprintf(logFile, "Error: Unable to allocate memory for statistics.\n");
        return NULL;
    }
    memset(newStats, 0, sizeof(PDCCH_Statistics) * count);
    return newStats;
}

int resize_stats(int newCount) {
    PDCCH_Statistics *newStats = malloc_statistic(newCount);
    if (!newStats) {
        return -1; // Error allocating memory
    }

    pthread_mutex_lock(&statsMutex);
    stats = newStats;
    statsCount = newCount;
    pthread_mutex_unlock(&statsMutex);

    return 0; // Successful resize
}

void add_packet_stats(int pdcchSearchSpaceId, int cceIndex) {
    if (statsCount >= MAX_PACKETS) {
        if (resize_stats(MAX_STATS)) {
            fprintf(logFile, "Error: Unable to resize statistics list.\n");
            return;
        }
    }

    pthread_mutex_lock(&statsMutex);
    stats[statsCount].pdcchSearchSpaceId = pdcchSearchSpaceId;
    stats[statsCount].cceIndex = cceIndex;
    stats[statsCount++].crcFlag = rand() % 2; // Randomly set CRC flag
    pthread_mutex_unlock(&statsMutex);
}

void log_error(char *msg) {
    fprintf(logFile, "Error: %s\n", msg);
}
