// Define the structure NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a doubly linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node* prev;
    struct Node* next;
} NODE;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** createPopulateList(int n) {
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((n+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    NODE *head = NULL, *tail = NULL;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Validate RX_UE_INFORMATION_TAG before inclusion in the list
        char RX_UE_INFORMATION_TAG[16];
        // Obtain RX_UE_INFORMATION_TAG from an external data source

        // Set RNTI and CRCFLAG randomly
        pdu->RNTI = rand() % 256;
        pdu->CRCFLAG = rand() % 2;

        strcpy(pdu->RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG);

        // Add the new node to the list
        NODE *node = (NODE*)malloc(sizeof(NODE));
        node->data = pdu;
        node->prev = NULL;
        node->next = NULL;

        if (head == NULL) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }

        list[i] = pdu;
    }

    // Serialize the populated list to a file for later use or deserialization
    FILE *file = fopen("NFAPI_CRC_INDICATION_PDU_T_list.bin", "wb");
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*), n+1, file);
    fclose(file);

    // Free the dynamically allocated memory
    for (int i = 0; i < n; i++) {
        free(list[i]);
    }
    free(list);

    return NULL;
}
