// Define a linked list node
typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} ListNode;

// Initialize the head of the list
ListNode* list_head = NULL;

// Lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void create_and_populate_list(int n, int max_rnti) {
    srand(time(NULL)); // Seed random number generator

    // Validate input parameters
    if (n <= 0 || max_rnti < 1) {
        printf("Invalid input. Aborting...\n");
        return;
    }

    // Create and populate the list
    for (int i = 0; i < n; i++) {
        ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
        if (!new_node) {
            printf("Memory allocation failed. Aborting...\n");
            return;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu_data;
        strcpy(pdu_data.RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_"); // Initialize with a default value
        pdu_data.RNTI = rand() % (max_rnti + 1); // Randomly set RNTI within the range [0, max_rnti]
        pdu_data.CRCFLAG = (rand() % 2) ? CRCFLAG_ON : CRCFLAG_OFF; // Randomly set CRCFLAG

        new_node->data = pdu_data;
        new_node->next = list_head;
        pthread_mutex_lock(&lock);
        {
            if (!list_head)
                list_head = new_node;
            else {
                ListNode* current = list_head;
                while (current->next) current = current->next;
                current->next = new_node;
            }
        }
        pthread_mutex_unlock(&lock);
    }
}
