#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int* RTNI_values = (int*)malloc(sizeof(int)*n);
    srand(time(NULL));

    // Create and populate the array of RNTI values
    for (int i = 0; i < n; i++) {
        RTNI_values[i] = rand() % 100; // Generate random RNTI values between 0-99
    }

    qsort(RTNI_values, n, sizeof(int), compare_RNTI);

    // Create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*n);
    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = RTNI_values[i];
        list[i].RNTI = RTNI_values[i]; // Since RNTI values are already sorted, assign them to both RX_UE_INFORMATION_TAG and RNTI
        list[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG as either 0 or 1
    }

    free(RTNI_values);

    return list;
}

int compare_RNTI(const void* a, const void* b) {
    int* valueA = (int*)a;
    int* valueB = (int*)b;

    if (*valueA < *valueB)
        return -1;
    else if (*valueA > *valueB)
        return 1;

    return 0;
}
