    struct dl_tb {
        int payload_size;
        char modulation_scheme;  // 'QPSK', '16QAM', or '64QAM'
    } *dl_tbs;
} lte_ue_context;

// Function to create and populate a list of LTE UE context structures
lte_ue_context* create_ue_list(int num_ues, int max_dl_tbs_per_ue) {
    // Initialize the list with NULL pointers
    lte_ue_context* ue_list = (lte_ue_context*)malloc((num_ues + 1) * sizeof(lte_ue_context));
    for (int i = 0; i <= num_ues; i++) {
        ue_list[i].ue_id = rand() % 1000;
        ue_list[i].rnti = rand() % 500;
        ue_list[i].num_dl_tbs = rand() % (max_dl_tbs_per_ue + 1);
        // Dynamically allocate memory for DL_TBS array
        ue_list[i].dl_tbs = (struct dl_tb*)malloc(ue_list[i].num_dl_tbs * sizeof(struct dl_tb));
        for (int j = 0; j < ue_list[i].num_dl_tbs; j++) {
            ue_list[i].dl_tbs[j].payload_size = rand() % 1024;
            // Randomly choose modulation scheme
            switch (rand() % 3) {
                case 0:
                    ue_list[i].dl_tbs[j].modulation_scheme = 'QPSK';
                    break;
                case 1:
                    ue_list[i].dl_tbs[j].modulation_scheme = '16QAM';
                    break;
                default:
                    ue_list[i].dl_tbs[j].modulation_scheme = '64QAM';
                    break;
            }
        }
    }
    return ue_list;
}

// Function to free the memory allocated for UE context structures
void free_ue_list(lte_ue_context* ue_list, int num_ues) {
    for (int i = 0; i <= num_ues; i++) {
        // Free memory for DL_TBS array
        if (ue_list[i].num_dl_tbs > 0) {
            free(ue_list[i].dl_tbs);
        }
    }
    // Free the main UE list structure
    free(ue_list);
}
