    LTE_PHY_LAYER_CONFIG* config_list = (LTE_PHY_LAYER_CONFIG*)malloc(sizeof(LTE_PHY_LAYER_CONFIG));
    while (fscanf(file, "%d %d %d %2s", &config_list[*num_configs].cell_id, 
