            config_list = (LTE_PHY_LAYER_CONFIG*)realloc(config_list, sizeof(LTE_PHY_LAYER_CONFIG) * (*num_configs + 1));
        } else {
            printf("Invalid prefix type. Skipping this configuration.\n");
        }
