LteUeContextList* lte_ue_context_list_create(int num_contexts) {
    LteUeContextList* list = (LteUeContextList*)malloc(sizeof(LteUeContextList));
    if (!list) return NULL; // Handle memory allocation failure

    list->contexts = (LteUeContext*)calloc(num_contexts, sizeof(LteUeContext));
    if (!list->contexts) {
        free(list); // Release allocated memory
        return NULL;
    }

    list->size = num_contexts;

    pthread_mutex_init(&list->lock, NULL); // Initialize mutex for thread safety

    return list;
}

// Function to populate the LTE UE Context list with random data
void lte_ue_context_list_populate(LteUeContextList* list) {
    for (int i = 0; i < list->size; i++) {
        LteUeContext* context = &list->contexts[i];
        context->ue_id = rand() % 10000;
        context->cell_id = rand() % 100;
        context->signal_strength = (float)rand() / RAND_MAX;
