        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_structures; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        while (pdu_list[i].RX_UE_INFORMATION_TAG <= 0) {
            pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        }
        pdu_list[i].RNTI = rand() % 2;
        sprintf(pdu_list[i].CRC_INDICATION_REL8_TAG, "CRCFLAG_%d", rand() % 10);
        pdu_list[i].timestamp = time(NULL) + i;
    }

    return pdu_list;
}

int verify_crc_indication_pdu_list(NFAPI_CRC_INDINATION_PDU_T* pdu_list, int num_structures) {
    for (int i = 0; i < num_structures; i++) {
        if (!pdu_list[i].RX_UE_INFORMATION_TAG || !pdu_list[i].RNTI || strlen(pdu_list[i].CRC_INDICATION_REL8_TAG) != 14) {
            printf("Error: Invalid structure found at index %d.\n", i);
            return -1;
        }
    }
    return 0;
}

void sort_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int num_structures) {
    qsort(pdu_list, num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), (int (*)(const void *, const void *))cmp_timestamp);
}

int cmp_timestamp(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = *(NFAPI_CRC_INDICATION_PDU_T**)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = *(NFAPI_CRC_INDICATION_PDU_T**)b;

    if (pdu_a->timestamp < pdu_b->timestamp) {
        return -1;
    } else if (pdu_a->timestamp > pdu_b->timestamp) {
        return 1;
    }

    return 0;
}

