#include <pthread.h>

#define MAX_LIST_SIZE 5000
#define RRC_MESSAGE_T struct { int type; int cell_id; int ue_id; }
typedef struct {
    RRC_MESSAGE_T *messages;
    size_t len;
    pthread_mutex_t lock;
} rrc_list_t;

rrc_list_t* rrc_list_create() {
    rrc_list_t* list = (rrc_list_t*)malloc(sizeof(rrc_list_t));
    if (!list) return NULL;
    list->messages = (RRC_MESSAGE_T*)calloc(MAX_LIST_SIZE, sizeof(RRC_MESSAGE_T));
    if (!list->messages) {
        free(list);
        return NULL;
    }
    list->len = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int rrc_list_add(rrc_list_t* list, RRC_MESSAGE_T* message) {
    pthread_mutex_lock(&list->lock);
    if (list->len >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // error: maximum size reached
    }
    list->messages[list->len++] = *message;
    pthread_mutex_unlock(&list->lock);
    return 0; // success
}

void rrc_list_free(rrc_list_t* list) {
    free(list->messages);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
