#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_list(int num_elements) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_elements; i++) {
        // Initialize structure
        NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_struct) {
            // Handle allocation failure
            printf("Memory allocation failed.\n");
            break;
        }

        int RX_UE_INFORMATION_TAG = rand() % 1000; // Randomly generated value
        int RNTI = rand() % 1000; // Randomly generated value
        int CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        new_struct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_struct->RNTI = RNTI;
        new_struct->CRCFLAG = CRCFLAG;

        pthread_mutex_lock(&lock);
        list = realloc(list, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!list) {
            printf("Memory reallocation failed.\n");
            free(new_struct);
            break;
        }

        list[i] = new_struct;
        pthread_mutex_unlock(&lock);
    }

    // Ensure uniqueness of RX_UE_INFORMATION_TAG
    for (int i = 0; i < num_elements; i++) {
        for (int j = i + 1; j < num_elements; j++) {
            if (list[i]->RX_UE_INFORMATION_TAG == list[j]->RX_UE_INFORMATION_TAG) {
                printf("Error: Duplicate RX_UE_INFORMATION_TAG found.\n");
                break;
            }
        }
    }

    // Support sorting the list based on RNTI values
    qsort(list, num_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T*), compare);

    return list;
}

int compare(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* struct_a = *(NFAPI_CRC_INDICATION_PDU_T**)a;
    NFAPI_CRC_INDICATION_PDU_T* struct_b = *(NFAPI_CRC_INDICATION_PDU_T**)b;

    if (struct_a->RNTI < struct_b->RNTI) {
        return -1;
    } else if (struct_a->RNTI > struct_b->RNTI) {
        return 1;
    }
    return 0;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T** list, int num_elements) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_elements; i++) {
        if (list[i]) {
            free(list[i]);
        }
    }
    free(list);
    pthread_mutex_unlock(&lock);
}

// Example usage:
int main() {
    NFAPI_CRC_INDICATION_PDU_T* list = create_crc_list(10);
    // Use the created list
    free_crc_list(list, 10);
    return 0;
}
