    for (int i = 0; i < n; i += 10000) {
        int batch_total = fmin(n - i, 10000);

        NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(batch_total * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_list) {
            log_func(2, "Memory allocation failure");
            free(pdu_list);
            return -1;
        }

        for (int j = 0; j < batch_total; j++) {
            pdu_list[j].rnti = rand() % 1000000 + 1;
            sprintf(pdu_list[j].rx_ue_info_tag, "RX_UE_INFO_TAG_%d", j);
        }

        total_created += batch_total;

        for (int j = 0; j < batch_total; j++) {
            if (!log_func(1, "Created structure: RNTI - %d, RX UE Tag - %s")) {
                free(pdu_list);
                return -1;
            }
        }

        free(pdu_list);
    }

    log_func(1, "Total structures created across batches: %d", total_created);

    return total_created;
}

int fmin(int a, int b) {
    return (a < b) ? a : b;
