// Define linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
Node* create_NFAPICRCIndicationPDUList(int N, FILE *log_file) {
    Node *head = NULL;
    Node **tail = &head;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure
            return NULL;
        }

        // Initialize random CRCFLAG value
        srand(time(NULL));
        int crcflag = rand() % 2;

        // Populate RX_UE_INFORMATION_TAG and RNTI values
        sprintf(pdu->RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG_%d", i);
        pdu->RNTI = i;

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

        // Log the creation of each structure
        fprintf(log_file, "Created NFAPI_CRC_INDICATION_PDU_T structure with RNTI=%d and CRCFLAG=%d.\n", pdu->RNTI, crcflag);

        Node *new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            // Handle memory allocation failure
            free(pdu);
            return NULL;
        }

        new_node->data = pdu;
        new_node->next = NULL;

        *tail = new_node;
        tail = &(new_node->next);

        // Validate input parameters and check for data integrity
        if (i > 0) {
            // Check the CRCFLAG values are not consecutive
            int prev_crcflag = (*tail)->data->CRC_INDICATION_REL8_TAG.CRCFLAG;
            if ((*tail)->data->RNTI - i == 1 && prev_crcflag + 1 != (*tail)->data->CRC_INDICATION_REL8_TAG.CRCFLAG) {
                // Handle invalid CRCFLAG sequence
                free(pdu);
                return NULL;
            }
        }
    }

    return head;
}

int main() {
    FILE *log_file = fopen("nfapicrcindicationpdu.log", "w");
    if (!log_file) {
        // Handle file operation failure
        return 1;
    }

    Node *list = create_NFAPICRCIndicationPDUList(1000, log_file);
    if (!list) {
        // Handle memory allocation or file operation failure
        fclose(log_file);
        return 2;
    }

    // Process the list of NFAPI_CRC_INDICATION_PDU_T structures

