size_t write_memory(void *ptr, size_t size) {
    json_len = size;
    return size;
}

void fetch_ue_data_json(CURL *handle, char **json_data, CURLcode *result) {
    // Fetch UE data from JSON file using HTTP request
    curl_easy_setopt(handle, CURLOPT_URL, "http://example.com/ue_data.json");
    curl_easy_setopt(handle, CURLOPT_WRITEFUNCTION, write_memory);
    curl_easy_setopt(handle, CURLOPT_WRITEDATA, json_data);
    *result = curl_easy_perform(handle);

    if (*result != CURLE_OK) {
        handle_curl_error(handle, *result);
    }
}

