use tokio::sync::{mpsc, oneshot};
use reqwest::blocking::get;

async fn fetch_data(urls: Vec<String>) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut client = reqwest::Client::new();

    // Handle concurrency level based on system load and network conditions
    let concurrency_level = determine_concurrency_level();
    let (tx, rx) = mpsc::channel(concurrency_level);

    for url in urls {
        tx.send(url).await.unwrap();
    }

    let responses: Vec<String> = rx.recv_all().await?.into_iter().map(|response| response.text()).collect();

    Ok(responses)
}

async fn fetch_and_cache_data(urls: Vec<String>, cache: &mut std::collections::HashMap<String, String>) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut client = reqwest::Client::new();
    let (tx, rx) = oneshot::channel();

    for url in urls {
        tx.send(client.get(url).send()).await.unwrap();
    }

    let responses: Vec<String> = rx.recv_all().await?.into_iter().map(|response| response.text()).collect();

    for (url, response) in responses.into_iter() {
        cache.insert(url.clone(), response);
    }

    Ok(responses)
}

async fn handle_fetch_and_cache_data(urls: Vec<String>, cache: &mut std::collections::HashMap<String, String>) -> Result<(), Box<dyn std::error::Error>> {
    let mut futures = vec![];

    for url in urls {
        let future = fetch_and_cache_data(url.clone(), cache).await;
        futures.push(future);
    }

    for future in futures {
        if let Err(err) = future.await {
            println!("Error: {}", err);
        }
    }

    Ok(())
}
```

