// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** createAndPopulateList(int numElements) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < numElements; i++) {
        // Create a new RX_UE_INFORMATION_TAG structure
        RX_UE_INFORMATION_TAG* ueInfoTag = (RX_UE_INFORMATION_TAG*)malloc(sizeof(RX_UE_INFORMATION_TAG));
        // Set valid values in the tag

        // Create a new CRC_INDICATION_REL8_TAG structure
        CRC_INDICATION_REL8_TAG* crcTag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        // Randomly set CRCFLAG

        // Allocate memory for an NFAPI_CRC_INDICATION_PDU_T structure and initialize it
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = ueInfoTag;
        pdu->RNTI = 0; // Initialize RNTI to a default value
        pdu->CRC_INDICATION_REL8_TAG = crcTag;

        // Add the new element to the list and link it with the previous node
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = pdu;
        newNode->prev = NULL;
        newNode->next = (list + i) ? ((Node*)list[i-1])->next : NULL;

        // Update the prev and next pointers of adjacent nodes
        if (newNode->next) {
            newNode->next->prev = newNode;
        }
        if ((list + i-1)) {
            ((Node*)list[i-1])->next = newNode;
        }

        list[i] = pdu;
    }

    return list;
}

// Function to remove an element by RNTI from the doubly linked list
void removeFromList(NFAPI_CRC_INDICATION_PDU_T** list, int numElements, int rntiToRemove) {
    for (int i = 0; i < numElements; i++) {
        if (((Node*)list[i])->data->RNTI == rntiToRemove) {
            // Remove the element from the list
            ((Node*)list[i])->prev->next = ((Node*)list[i])->next;
            ((Node*)list[i])->next->prev = ((Node*)list[i])->prev;

            // Free the memory allocated for the removed element
            free(((Node*)list[i])->data);

            // Shift down the remaining elements and update their pointers
            for (int j = i; j < numElements - 1; j++) {
                list[j] = list[j+1];
            }

            // Update the number of elements in the list
            numElements--;

            return;
        }
    }
}

// Function to free the memory allocated by createAndPopulateList
void freeList(NFAPI_CRC_INDICATION_PDU_T** list, int numElements) {
    for (int i = 0; i < numElements; i++) {
        // Free the memory allocated for each NFAPI_CRC_INDICATION_PDU_T structure
        free(list[i]);

        // Free the memory allocated for each RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG structure
        free(((Node*)list[i])->data->RX_UE_INFORMATION_TAG);
        free(((Node*)list[i])->data->CRC_INDICATION_REL8_TAG);

        // Free the memory allocated for each Node structure
        free((Node*)list[i]);
    }

    // Free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(list);
}
