NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int i;

    // Dynamically allocate memory for the list
    if (!(list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        printf("Error: Memory allocation failed.\n");
        return NULL;  // Handle error and log message
    }

    // Initialize each structure in the list with valid RX_UE_INFORMATION_TAG and RNTI
    for (i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = i;
        list[i].RNTI = i * 2;  // Ensure unique RNTIs
        list[i].CRCFLAG = rand() % 2 ? CRCFLAG_SET : CRCFLAG_CLEAR;  // Randomly set CRCFLAG

        if (list[i].RX_UE_INFORMATION_TAG > 255) {
            printf("Error: Invalid RX_UE_INFORMATION_TAG value.\n");
            free(list);  // Handle error and log message
            return NULL;
        }
    }

    // Sort the list based on RNTI in ascending order
    qsort(list, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    return list;
