typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indication_pdu_list(int max_size) {
    // Initialize error code to 0 (success)
    int error_code = 0;

    // Initialize list size and total memory usage
    int list_size = 0;
    size_t total_memory_usage = 0;

    NFAPI_CRC_INDICATION_PDU_T **crc_indication_pdu_list = NULL;
    crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!crc_indication_pdu_list) {
        error_code = 1; // Memory allocation failed
        printf("Error: Failed to allocate memory for list.\n");
        return error_code;
    }

    // Initialize random number generator
    srand(time(NULL));

    while (list_size < max_size && total_memory_usage <= (1 << 20)) { // 1 MB in bytes
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            error_code = 2; // Memory allocation failed
            printf("Error: Failed to allocate memory for pdu structure.\n");
            return error_code;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % (1 << 16);
        while (find_pdu_in_list(crc_indication_pdu_list, list_size, pdu->RX_UE_INFORMATION_TAG)) {
            pdu->RX_UE_INFORMATION_TAG = rand() % (1 << 16);
        }

        pdu->RNTI = rand();
        pdu->CRCFLAG = rand();

        crc_indication_pdu_list[list_size] = pdu;
        list_size++;
        total_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // Save the populated list to disk at regular intervals
        if (list_size % 100 == 0) {
            FILE *file = fopen("crc_indication_pdu_list.bin", "wb");
            if (!file) {
                error_code = 3; // File I/O operation failed
                printf("Error: Failed to write populated list to disk.\n");
                return error_code;
            }

            fwrite(crc_indication_pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T *), list_size, file);
            fclose(file);
        }
    }

    if (list_size >= max_size) {
        error_code = 4; // Maximum size exceeded
        printf("Error: List size exceeds maximum allowed size.\n");
    } else if (total_memory_usage > (1 << 20)) { // 1 MB in bytes
        error_code = 5; // Memory limit exceeded
        printf("Error: Total memory usage exceeds the allowed limit.\n");
    }

    for (int i = 0; i < list_size; i++) {
        free(crc_indication_pdu_list[i]);
    }
    free(crc_indication_pdu_list);

    return error_code;
}

// Helper function to find a pdu with the given RX_UE_INFORMATION_TAG in the list
int find_pdu_in_list(NFAPI_CRC_INDICATION_PDU_T **pdu_list, int size, int tag) {
    for (int i = 0; i < size; i++) {
        if (pdu_list[i]->RX_UE_INFORMATION_TAG == tag) {
            return 1;
        }
    }

    return 0;
}
