void createOctree(int featureSize, int numLeafNodes) {
    // Dynamically allocate memory for the octree
    OctreeNode* octree = (OctreeNode*)malloc(sizeof(OctreeNode));
    octree->featureSize = featureSize;
    octree->numLeafNodes = numLeafNodes;
    octree->children = (OctreeNode**)malloc((1 << featureSize) * sizeof(OctreeNode*));

    for (int i = 0; i < (1 << featureSize); i++) {
        octree->children[i] = createOctreeNode(featureSize, numLeafNodes / (1 << featureSize));
    }
}

void populateOctree(NFAPI_CRC_INDICATION_PDU_T** data, OctreeNode* root) {
    if (root == NULL || root->numLeafNodes <= 0) {
        return;
    }

    for (int i = 0; i < root->numLeafNodes; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = *data++;
        // Insert the PDU into the octree
        insertPduIntoOctree(pdu, root);
    }

    for (int i = 0; i < (1 << root->featureSize); i++) {
        populateOctree(data, root->children[i]);
    }
}

void freeOctree(OctreeNode* root) {
    if (root == NULL) {
        return;
    }

    for (int i = 0; i < (1 << root->featureSize); i++) {
        freeOctree(root->children[i]);
    }

    free(root);
}

int main() {
    int featureSize = 3;
    int numLeafNodes = 8;

    NFAPI_CRC_INDICATION_PDU_T* data[] = {(NFAPI_CRC_INDICATION_PDU_T){123, 456, rand() % 2},
                                             (NFAPI_CRC_INDICATION_PDU_T){789, 012, rand() % 2},
                                             // ... more PDUs ...
                                            };

    OctreeNode* root = createOctree(featureSize, numLeafNodes);
    populateOctree(data, root);

    freeOctree(root);

    return 0;
}

