sem_t semaphore;
pthread_mutex_t lock;
int max_threads = DEFAULT_MAX_THREADS;
int max_structures_per_thread = DEFAULT_MAX_STRUCTURES_PER_THREAD;
int retry_count = 3;
int rate_limit = 10;

void* processNfaPdu(void* ptr) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)ptr;
    // Validate RNTI and RX_UE_INFORMATION_TAG
    pthread_mutex_lock(&lock);
    sem_wait(&semaphore);

    if (validateData(pdu->RNTI, pdu->RX_UE_INFORMATION_TAG) == 0) {
        retry_count--;
        if (retry_count > 0) {
            // Retry with exponential backoff
            sleep(1 << retry_count);
            processNfaPdu(ptr);
        } else {
            logError(pdu, "Validation failed");
        }
    } else {
        sem_post(&semaphore);
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

int main() {
