    sem_init(&semaphore, 0, 1);
    pthread_mutex_init(&lock, NULL);

    pthread_t threads[MAX_THREADS];
    NFAPI_CRC_INDICATION_PDU_T* pdu_array[MAX_STRUCTURES];

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        // Initialize structures
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = rand() % 10000000;
        strcpy(pdu.RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
        // Custom fields can be added here

        // Add to array
        pdu_array[i] = &pdu;

        if (i % max_structures_per_thread == 0 && i > 0) {
            for (int j = i - max_structures_per_thread; j < i; j++) {
                pthread_create(&threads[j], NULL, processNfaPdu, pdu_array[j]);
            }
        }
    }

    // Process remaining structures
    for (int i = MAX_STRUCTURES_PER_THREAD; i <= MAX_STRUCTURES; i++) {
        pthread_create(&threads[i], NULL, processNfaPdu, pdu_array[i % max_structures_per_thread]);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    sem_destroy(&semaphore);
    pthread_mutex_destroy(&lock);

    return 0;
}

