// Function to create and populate a list of LTE MAC Configuration DUs (MAC_Config_Downlink_T)
void* create_MAC_Config_Downlink_T_list(int num_elements) {
    // Dynamically allocate memory for the list
    void *list = malloc(num_elements * sizeof(MAC_Config_Downlink_T));

    // Create a linked list using the dynamically allocated memory
    MAC_Config_Downlink_T *head = (MAC_Config_Downlink_T*) list;

    // Initialize each element in the list with default values
    for (int i = 0; i < num_elements; i++) {
        head[i].mac_ce = -1;
        head[i].ul_sch = -1;
        head[i].last_update_timestamp = time(NULL);
    }

    return &head;
}

// Function to update the MAC_Config_Downlink_T list
void update_MAC_Config_Downlink_T_list(void *list, int new_num_elements) {
    // Dynamically reallocate memory for the updated list
    void *new_list = realloc(list, new_num_elements * sizeof(MAC_Config_Downlink_T));

    // Update each element in the list with new values
    MAC_Config_Downlink_T *head = (MAC_Config_Downlink_T*) new_list;
    for (int i = 0; i < new_num_elements; i++) {
        head[i].mac_ce = -1;
        head[i].ul_sch = -1;
        head[i].last_update_timestamp = time(NULL);
    }
}

