#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_N 1000
#define MAX_RNTI_LENGTH 20
#define MAX_CRCFLAG_LENGTH 10

typedef struct {
    char RX_UE_INFORMATION_TAG[MAX_RNTI_LENGTH];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[MAX_CRCFLAG_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

void create_and_populate_list(int n, int* max_n, int* verbosity, FILE* log_file) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int i, rnti_count = 0;
    srand(time(NULL)); // seed random number generator

    if (n > *max_n) {
        fprintf(log_file, "Error: Requested number of structures exceeds maximum limit.\n");
        return;
    }

    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            fprintf(log_file, "Error: Memory allocation failed.\n");
            return;
        }

        // generate random RNTI
        char rnti_tag[MAX_RNTI_LENGTH];
        sprintf(rnti_tag, "%06x", rand());
        pdu->RNTI = atoi(rnti_tag);

        // generate random CRC flag
        char crc_flag[MAX_CRCFLAG_LENGTH];
        sprintf(crc_flag, "%02x", rand() % 256);
        strcpy(pdu->CRC_INDICATION_REL8_TAG, crc_flag);

        if (strncasecmp(pdu->RX_UE_INFORMATION_TAG, " valid RX UE information tag", strlen(" valid RX UE information tag")) != 0) {
            free(pdu);
            continue;
        }

        // validate RNTI
        if (pdu->RNTI < 1 || pdu->RNTI > 65535) {
            free(pdu);
            continue;
        }

        list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 2));
        list[i] = *pdu;

        if (*verbosity > 1) {
            fprintf(log_file, "Added structure %d with RNTI %06x and CRC flag %s.\n", i, pdu->RNTI, crc_flag);
        }

        free(pdu);

        rnti_count++;
    }

    *max_n = rnti_count;
}

int main() {
    int n = 10; // adjust this value for your specific use case
    int max_n = MAX_N;
    int verbosity = 1; // set to 0 for silent mode, 1 for informational messages, or 2 for debug logging
    FILE* log_file = fopen("log.txt", "w");

    if (log_file == NULL) {
        perror("Failed to open log file.");
        return 1;
    }

    create_and_populate_list(n, &max_n, &verbosity, log_file);

    fclose(log_file);
    return 0;
}
