NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
        node->RNTI = rand() % 10000;
        node->CRCFLAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG
        node->next = NULL;

        if (!head) {
            head = node;
        } else {
            pthread_mutex_lock(&lock);
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
            pthread_mutex_unlock(&lock);
        }
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    NFAPI_CRC_INDATION_PDU_T* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

void log_linked_list_events(NFAPI_CRC_INDICATION_PDU_T* head, int operation_type) {
