#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_list(int n, int seed) {
    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        RX_UE_INFORMATION_TAG rx_ue_info_tag;
        rx_ue_info_tag.rnti = rand() % 100;

        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
        crc_indication_rel8_tag.crcflag = (rand() % 2) ? 0 : 1; // Randomly set to either 0 or 1

        list[i].rx_ue_info_tag = rx_ue_info_tag;
        list[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
    }

    return list;
}

void save_crc_list_to_file(NFAPI_CRC_INDICATION_PDU_T* list, int n, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    for (int i = 0; i < n; i++) {
        fwrite(&list[i].rx_ue_info_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&list[i].crc_indication_rel8_tag.crcflag, sizeof(int), 1, file);
    }

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* load_crc_list_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return NULL;
    }

    int n = 0;
    while (fread(&((NFAPI_CRC_INDICATION_PDU_T*)NULL)->rx_ue_info_tag.rnti, sizeof(int), 1, file)) {
        n++;
    }
    rewind(file);

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        fread(&list[i].rx_ue_info_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fread(&list[i].crc_indication_rel8_tag.crcflag, sizeof(int), 1, file);
    }

    fclose(file);

    return list;
}
