NFAPI_CRC_INDICATION_PDU_T* create_population(int n, int seed) {
    if (n > MAX_STRUCTURES) {
        printf("Error: Requested number of structures exceeds the maximum limit.\n");
        return NULL;
    }

    // Initialize mutex for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    NFAPI_CRC_INDICATION_PDU_T* population = NULL;

    // Allocate initial memory for the list
    int size = n;
    population = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!population) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize random number generator with the provided seed
    srand(seed);

    int i;
    for (i = 0; i < size; i++) {
        // Create a new structure and populate its members...
        NFAPI_CRC_INDICATION_PDU_T* p = &population[i];
        // Add your structure initialization code here...

        pthread_mutex_lock(&lock);
        population = realloc(population, (size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!population) {
            printf("Error: Memory reallocation failed.\n");
            free(population);
            return NULL;
        }
        size++;
        population[size - 1] = *p;
        pthread_mutex_unlock(&lock);
    }

    // Log any errors or warnings during execution
    printf("Population created successfully.\n");

    return population;
