uint32_t crc32(uint16_t data, int len) {
    uint32_t crc = 0xFFFFFFFF;
    for (int i = 0; i < len; i++) {
        crc = (crc >> 8) ^ (unsigned int)(data & 0xFF);
        data >>= 8;
    }
    return ~crc;
