#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_BATCH_SIZE 10000
#define RATE_LIMIT 1000
#define LOGGING_ENABLED 1

typedef struct {
    int rnti;
    char rx_ue_information_tag[16];
} RX_UE_INFORMATION_TAG;

typedef struct {
    int rnti;
    char crc_flag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

void processCRCIndications(int n, int batch_size) {
    if (n < 0 || batch_size <= 0) return;

    // Initialize database connection and rate limiter
    void* db_conn = dbInitialize();
    unsigned long last_processing_time = time(NULL);

    for (int i = 0; i < n / batch_size; i++) {
        int current_batch_size = min(batch_size, n - i * batch_size);

        // Allocate memory for the current batch
        NFAPI_CRC_INDICATION_PDU_T* crc_indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_batch_size);

        for (int j = 0; j < current_batch_size; j++) {
            crc_indications[j].rx_ue_info.rnti = rand() % 100;
            strcpy(crc_indications[j].rx_ue_info.rx_ue_information_tag, getRandomTag());
            crc_indications[j].crc_indication_rel8.rnti = rand() % 100;
            crc_indications[j].crc_indication_rel8.crc_flag = 'x' + (rand() % 26);
        }

        // Validate RX_UE_INFORMATION_TAG integrity and rate limit
        for (int j = 0; j < current_batch_size; j++) {
            if (!validateRXUETag(&crc_indications[j].rx_ue_info)) {
                printf("Invalid RX_UE_INFORMATION_TAG at index %d.\n", j);
                continue;
            }

            // Rate limit
            unsigned long current_processing_time = time(NULL);
            if (current_processing_time - last_processing_time < 60 && rateLimited(last_processing_time, RATE_LIMIT)) {
                printf("Rate limited. Please wait before continuing.\n");
                return;
            }
        }

        // Store CRC indications in the database and log processing time
        dbStoreCRCIndications(crc_indications, current_batch_size);
        if (LOGGING_ENABLED) {
            printf("Processing time for batch %d: %f seconds.\n", i + 1, (double)(time(NULL) - last_processing_time));
        }

        // Release memory and update rate limiter
        free(crc_indications);
        last_processing_time = current_processing_time;
    }
}

int main() {
    int n = 10000; // Number of CRC indications to process
    int batch_size = 1000; // Batch size for processing

    processCRCIndications(n, batch_size);

    return 0;
}
