    printf("Enter the number of entries: ");
    scanf("%d", &num_entries);

    // Initialize list and its size
    LTE_PHY_RX_DATA_T* lte_data_list = NULL;
    int list_size = 0;

    for (int i = 0; i < num_entries; i++) {
        // Allocate memory for new structure
        LTE_PHY_RX_DATA_T* new_lte_data = (LTE_PHY_RX_DATA_T*)malloc(sizeof(LTE_PHY_RX_DATA_T));
        if (!new_lte_data) {
