        // Generate channel estimation data
        for (int j = 0; j < 1000; j++) {
            new_lte_data->channel_est_tags[j] = (double)rand() / RAND_MAX;
        }

        // Add the new structure to the list and update its size
        if (!lte_data_list) {
            lte_data_list = new_lte_data;
            list_size = 1;
