            if (!temp_list) {
                printf("Memory allocation failed!\n");
                free(new_lte_data);
                return 1;
            }

            for (int k = 0; k < list_size; k++) {
                temp_list[k] = lte_data_list + k;
            }
            temp_list[list_size] = new_lte_data;
            free(lte_data_list);
            lte_data_list = temp_list;
            list_size++;
        }
    }

    // Print the generated data
    for (int i = 0; i < num_entries; i++) {
        printf("UE_ID: %d, PHR_MEASUREMENT_TAG: %s\n", lte_data_list[i].UE_ID, lte_data_list[i].PHR_MEASUREMENT_TAG);
