        int crcFlag = rand() % 2;
        // Initialize RX_UE_INFORMATION_TAG with valid data
        sprintf(list[i].RX_UE_INFORMATION_TAG, "RxUeInformationTag_%d", i);

        list[i].CRC_INDICATION_REL8_TAG = (crcFlag == 0) ? 1 : 2;
    }

    // Sort the list based on RNTI values in ascending order
    qsort(list, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compareFunction);

    return list;
}

int compareFunction(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* na = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* nb = (NFAPI_CRC_INDICATION_PDU_T*)b;

    return (na->RNTI - nb->RNTI);
}

void freeList(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    if (list != NULL && N > 0) {
        free(list);
    }
}
