    lte_ue_context* data;
    size_t size;
    pthread_mutex_t lock;
} lte_ue_context_list;

// Function to create and populate a list of LTE UE Context structures
lte_ue_context_list* create_lte_ue_context_list() {
    lte_ue_context_list* list = (lte_ue_context_list*)malloc(sizeof(lte_ue_context_list));
    if (!list) return NULL; // Handle memory allocation failure

    list->data = (lte_ue_context*)calloc(1000, sizeof(lte_ue_context));
    if (!list->data) {
        free(list);
        return NULL; // Handle memory allocation failure
    }

    list->size = 0;
    pthread_mutex_init(&list->lock, NULL); // Initialize the lock

    return list;
}

// Function to add a new LTE UE Context structure to the list
int add_lte_ue_context(lte_ue_context_list* list, int ue_id, int measurement_report_tag, int measurement_control_tag) {
    lte_ue_context new_ue_context = {ue_id, measurement_report_tag, measurement_control_tag};

    pthread_mutex_lock(&list->lock); // Acquire the lock

    // Insert the new UE context at the end of the list
    list->data[list->size] = new_ue_context;
    list->size++;

    // Sort the list by UE ID in ascending order
    qsort(list->data, list->size, sizeof(lte_ue_context), ue_id_compare);

    pthread_mutex_unlock(&list->lock); // Release the lock

    return 0; // Success
}

// Comparison function for sorting the LTE UE Context structures
int ue_id_compare(const void* a, const void* b) {
    lte_ue_context* ua = (lte_ue_context*)a;
    lte_ue_context* ub = (lte_ue_context*)b;

    if (ua->ue_id < ub->ue_id) return -1; // Less than
    else if (ua->ue_id > ub->ue_id) return 1; // Greater than
    else return 0; // Equal
}

// Function to update the measurement types dynamically from an external data source
void update_measurement_types(lte_ue_context_list* list, int ue_id, char* measurement_type_str) {
    pthread_mutex_lock(&list->lock); // Acquire the lock

    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].ue_id == ue_id) {
            // Update the measurement control tag with the new measurement type
            list->data[i].measurement_control_tag = get_measurement_type(measurement_type_str);
            break;
        }
    }

    pthread_mutex_unlock(&list->lock); // Release the lock
}

// Function to handle memory deallocation and destruction of the list
void destroy_lte_ue_context_list(lte_ue_context_list* list) {
    pthread_mutex_destroy(&list->lock); // Destroy the lock

    if (list) {
        free(list->data);
        free(list);
    }
}
