            tb->payload = (uint8_t*)malloc((rand() % MAX_PAYLOAD_SIZE + 1) * sizeof(uint8_t));

            if (!tb->payload) {
                printf("Error allocating memory for transport block payload.\n");
                return NULL;
            }

            tb->size = rand() % MAX_PAYLOAD_SIZE + 1;
        }
    }

    return pdus;
}

void free_lte_phy_pdu(LTE_PHY_LAYER_PDU* pdus, int num_pdus) {
    for (int i = 0; i < num_pdus; i++) {
        if (pdus[i].tb_array) {
            for (int j = 0; j < pdus[i].num_tb; j++) {
                free(pdus[i].tb_array[j].payload);
            }
            free(pdus[i].tb_array);
        }
    }

