    for(int i = 0; i < initialSize; i++) {
        crcList[i] = NULL;
    }

    return crcList;
}

// Function to dynamically resize the list and add a new element
int addCRCIndication(NFAPI_CRC_INDICATION_PDU_T** crcList, int* size) {
    // Dynamically increase the size of the list if necessary
    while((*size <= 0 || *size % 16 == 0 && *size < 1024)) {
        void* old = crcList;
        *size *= 2;  // double the size
        crcList = (NFAPI_CRC_INDICATION_PDU_T**)realloc(old, *size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }

    // Allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T* newElement = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

