#include <time.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    // placeholder for RX_UE_INFORMATION_TAG
    int tag;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int crcflag;
    } rel8_tag;
};

struct NFAPI_CRC_INDICATION_PDU_T* createNFAPI_CRC_INDICATION_PDU_T(int pdu_count, int min_rnti, int max_rnti) {
    if (pdu_count <= 0) {
        printf("Invalid pdu count: %d\n", pdu_count);
        return NULL;
    }

    struct NFAPI_CRC_INDICATION_PDU_T* pdus = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(pdu_count * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        printf("Memory allocation failed for pdu array\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < pdu_count; i++) {
        pdus[i].tag = 0; // placeholder
        pdus[i].RNTI = rand() % ((max_rnti - min_rnti) + 1) + min_rnti;
        pdus[i].rel8_tag.crcflag = rand() & 0xFF;
    }

    return pdus;
}

void freeNFAPI_CRC_INDICATION_PDU_T(struct NFAPI_CRC_INDICATION_PDU_T* pdus, int pdu_count) {
    if (pdus && pdu_count > 0) {
        free(pdus);
    }
}
