```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populate_crc_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t initial_size) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    for (size_t i = 0; i < initial_size; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].RNTI = rand() % 256;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 255;
        (*list)[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    return initial_size;
}

int main() {
    int size;
    NFAPI_CRC_INDICATION_PDU_T *list;

    srand(time(NULL)); // Initialize random seed

    size = populate_crc_list(&list, 5);

    printf("Initial list size: %d\n", size);

    for (size_t i = 0; i < size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG, list[i].CRCFLAG);
    }

    free(list); // Free allocated memory

    return 0;
}
